def hungarian(cost):
    """Minimum-cost assignment for n rows and m>=n columns."""
    n=len(cost); m=len(cost[0]) if n else 0
    u=[0]*(n+1); v=[0]*(m+1); p=[0]*(m+1); way=[0]*(m+1)
    for i in range(1,n+1):
        p[0]=i; j0=0; minv=[10**12]*(m+1); used=[False]*(m+1)
        while True:
            used[j0]=True; i0=p[j0]; delta=10**12; j1=0
            for j in range(1,m+1):
                if not used[j]:
                    cur=cost[i0-1][j-1]-u[i0]-v[j]
                    if cur<minv[j]: minv[j]=cur; way[j]=j0
                    if minv[j]<delta: delta=minv[j]; j1=j
            for j in range(m+1):
                if used[j]: u[p[j]]+=delta; v[j]-=delta
                else: minv[j]-=delta
            j0=j1
            if p[j0]==0: break
        while True:
            j1=way[j0]; p[j0]=p[j1]; j0=j1
            if j0==0: break
    ans=[-1]*n
    for j in range(1,m+1):
        if p[j]: ans[p[j]-1]=j-1
    return ans


def relation_obj(key,text):
    return {"subject":{"start":key[0],"end":key[1],"label":key[2],"text":text[key[0]:key[1]]},
            "predicate":key[3],
            "object":{"start":key[4],"end":key[5],"label":key[6],"text":text[key[4]:key[5]]}}


def pair_kind(g,p):
    gs,gp,go=g[:3],g[3],g[4:]; ps,pp,po=p[:3],p[3],p[4:]
    if gs==ps and go==po and gp!=pp: return 400,"WRONG_PREDICATE",f"{gp}->{pp}"
    if gs==po and go==ps and gp==pp: return 300,"REVERSED_DIRECTION",gp
    if gs==ps and gp==pp and go!=po: return 200,"WRONG_OBJECT_ATTACHMENT",gp
    if go==po and gp==pp and gs!=ps: return 200,"WRONG_SUBJECT_ATTACHMENT",gp
    return 0,"",""


def causal_census(gold,preds):
    by={p["doc_id"]:p for p in preds}; strata=defaultdict(list)
    for g in gold:
        p=by[g["doc_id"]]; available={two.ekey(x) for x in p["entities"]}
        gc=Counter(two.rkey(g,q) for q in g["relations"]); pc=Counter(two.rkey(p,q) for q in p["relations"])
        fn=[]; fp=[]
        for k,n in sorted((gc-pc).items(),key=lambda x:str(x[0])):
            for _ in range(n):
                if k[:3] not in available or k[4:] not in available:
                    strata["UNAVAILABLE|missing_entity_endpoint"].append({"doc_id":g["doc_id"],"gold":relation_obj(k,g["text"])})
                else: fn.append(k)
        for k,n in sorted((pc-gc).items(),key=lambda x:str(x[0])):
            fp.extend([k]*n)
        weights=[[pair_kind(x,y)[0] for y in fp]+[0]*len(fn) for x in fn]
        assignment=hungarian([[-w for w in row] for row in weights]) if fn else []
        used=set()
        for i,gk in enumerate(fn):
            j=assignment[i]
            if 0<=j<len(fp) and weights[i][j]>0:
                used.add(j); _,kind,detail=pair_kind(gk,fp[j]); key=f"{kind}|{detail}"
                strata[key].append({"doc_id":g["doc_id"],"gold":relation_obj(gk,g["text"]),
                    "prediction":relation_obj(fp[j],g["text"]),"context":g["text"]})
            else:
                strata[f"MISSING_EDGE|{gk[3]}"].append({"doc_id":g["doc_id"],"gold":relation_obj(gk,g["text"]),"prediction":None,"context":g["text"]})
        for j,pk in enumerate(fp):
            if j not in used:
                strata[f"SPURIOUS_EDGE|{pk[3]}"].append({"doc_id":g["doc_id"],"gold":None,"prediction":relation_obj(pk,g["text"]),"context":g["text"]})
    return dict(strata)


def true_positive_contrasts(stratum,gold,preds):
    predicates=set()
    tail=stratum.split("|",1)[1] if "|" in stratum else ""
    for x in two.RELATION_LABELS:
        if x in tail: predicates.add(x)
    by={p["doc_id"]:p for p in preds}; out=[]
    for g in gold:
        p=by[g["doc_id"]]; common=Counter(two.rkey(g,q) for q in g["relations"]) & Counter(two.rkey(p,q) for q in p["relations"])
        for k,n in sorted(common.items(),key=lambda x:str(x[0])):
            if not predicates or k[3] in predicates:
                for _ in range(n): out.append({"doc_id":g["doc_id"],"verified_true_positive":relation_obj(k,g["text"]),"context":g["text"]})
    return out


def load_r0(source):
    raw=json.loads((source/"relation/relation_initial_raw.json").read_text(encoding="utf-8"))
    g=json.loads(raw["choices"][0]["message"]["content"])
    return two.validate_guideline(g,"relation")


def main():
    a=cli(); base.load_env(a.env_file)
    plan=json.loads(a.plan.read_text(encoding="utf-8")); cond=next(x for x in plan["conditions"] if x["condition_id"]==a.condition)
    gold=two.load_selected(a.gold,cond["doc_ids"])
    ep=json.loads((a.source/"entity/G_star/predictions.json").read_text(encoding="utf-8")); eb={x["doc_id"]:x for x in ep}
    relgold=[]
    for g in gold:
        x=copy.deepcopy(g); x["frozen_entities"]=copy.deepcopy(eb[g["doc_id"]]["entities"]); relgold.append(x)
    current=load_r0(a.source); pred=json.loads((a.source/"relation/G0/predictions.json").read_text(encoding="utf-8"))
    score=two.relation_score(relgold,pred); api=two.API(argparse.Namespace(provider=a.provider,model=a.model,
        reasoning_effort=a.reasoning_effort,max_retries=a.max_retries))
    a.output.mkdir(parents=True,exist_ok=True); two.dump(a.output/"R0/guideline.json",current); two.dump(a.output/"R0/predictions.json",pred); two.dump(a.output/"R0/score.json",score)
    manifest={"protocol":"relation-causal-ledger-v1","source":str(a.source.resolve()),"provider":a.provider,"model":a.model,"reasoning_effort":"high",
        "frozen_entity_artifact":str((a.source/"entity/G_star").resolve()),"same_r0_as_baseline":True,
        "decoder":"free_edge_generation_unchanged","admission":"end_to_end_relation_f1_then_net_causal_errors",
        "matching":"deterministic maximum-weight one-to-one FN-FP assignment","heldout_retained_or_evaluated":False,
        "created_utc":datetime.now(timezone.utc).isoformat()}; two.dump(a.output/"manifest.json",manifest)
    rejected=defaultdict(set); history=[]; i=1
    while True:
        census=causal_census(relgold,pred); eligible={k:v for k,v in census.items() if not k.startswith("UNAVAILABLE|")}
        sig=hashlib.sha256(json.dumps({"g":current["principles"],"c":eligible},sort_keys=True).encode()).hexdigest()
        ranked=[k for k,v in sorted(eligible.items(),key=lambda z:(-len(z[1]),-len({str(x['doc_id']) for x in z[1]}),z[0])) if k not in rejected[sig]]
        if not ranked: break
        stratum=ranked[0]; cases=eligible[stratum]; contrasts=true_positive_contrasts(stratum,relgold,pred)
