            "selected_causal_stratum":stratum,"complete_causal_error_evidence":cases,"complete_verified_true_positive_contrasts":contrasts,
            "current_principles":current["principles"],"prior_decisions":history,
            "output_contract":{"action":"ADD or REVISE","target_rule_id":"existing ID for REVISE; null for ADD",
                "principle":{"instruction":"one operational relation rule","applies_when":"condition","exceptions":[],"priority":1,"examples":[]},"rationale":"text"}}
        cdir=a.output/f"candidate_{i:03d}"; two.dump(cdir/"prompt.json",payload)
        try:
            cand=api.json("Return one valid JSON object. Change one relation rule only. Entities are immutable.",payload,cdir/"raw.json")
            proposed=two.apply_candidate(current,cand,i,cases,"relation"); two.dump(cdir/"guideline.json",proposed)
            newpred=two.annotate_relations(api,proposed,relgold,cdir); newscore=two.relation_score(relgold,newpred)
            oldn=sum(len(v) for v in eligible.values()); newc=causal_census(relgold,newpred); newn=sum(len(v) for k,v in newc.items() if not k.startswith("UNAVAILABLE|"))
            accept=newscore["f1"]>score["f1"]+1e-12 or (abs(newscore["f1"]-score["f1"])<=1e-12 and newn<oldn)
            reason="f1_improved" if newscore["f1"]>score["f1"]+1e-12 else ("f1_tied_net_causal_errors_improved" if accept else "admission_failed")
        except Exception as e:
            accept=False; reason=f"invalid_candidate:{e}"; newscore=score
        decision={"iteration":i,"stratum":stratum,"cases":len(cases),"accepted":accept,"reason":reason,"before":score,"after":newscore}
        two.dump(cdir/"decision.json",decision); history.append(decision)
        if accept: current,pred,score=proposed,newpred,newscore
        else: rejected[sig].add(stratum)
        two.dump(a.output/"state.json",{"history":history,"current_score":score}); i+=1
    final_census=causal_census(relgold,pred); two.dump(a.output/"R_star/guideline.json",current); two.dump(a.output/"R_star/predictions.json",pred)
    two.dump(a.output/"R_star/score.json",score); two.dump(a.output/"R_star/causal_census.json",final_census)
    manifest.update({"completed_utc":datetime.now(timezone.utc).isoformat(),"r0_score":two.relation_score(relgold,json.loads((a.source/"relation/G0/predictions.json").read_text(encoding="utf-8"))),
        "final_score":score,"candidates":len(history),"accepted":sum(x["accepted"] for x in history)})
    two.dump(a.output/"manifest.json",manifest); print(json.dumps(manifest,ensure_ascii=False,indent=2))

if __name__=="__main__": main()

