def ekey(e): return e["start"],e["end"],e["label"]
def f1(tp,fp,fn): return 0 if 2*tp+fp+fn==0 else 2*tp/(2*tp+fp+fn)


def entity_score(gold,preds):
    by={p["doc_id"]:p for p in preds}; tp=fp=fn=0
    for g in gold:
        a=Counter(ekey(x) for x in g["entities"]); b=Counter(ekey(x) for x in by[g["doc_id"]]["entities"])
        tp+=sum((a&b).values()); fn+=sum((a-b).values()); fp+=sum((b-a).values())
    return {"tp":tp,"fp":fp,"fn":fn,"f1":f1(tp,fp,fn)}


def entity_census(gold,preds):
    by={p["doc_id"]:p for p in preds}; d=defaultdict(list)
    for g in gold:
        p=by[g["doc_id"]]; ga=list(g["entities"]); pa=list(p["entities"])
        exact=set(ekey(x) for x in ga)&set(ekey(x) for x in pa)
        gu=[x for x in ga if ekey(x) not in exact]; pu=[x for x in pa if ekey(x) not in exact]
        used=set()
        for x in gu:
            candidates=[(i,y) for i,y in enumerate(pu) if i not in used and x["start"]==y["start"] and x["end"]==y["end"]]
            if candidates:
                i,y=candidates[0]; used.add(i); d[f"ENT_LABEL|{x['label']}->{y['label']}"] .append({"doc_id":g["doc_id"],"gold":x,"prediction":y,"context":g["text"][max(0,x['start']-50):x['end']+50]})
            else:
                candidates=[(i,y) for i,y in enumerate(pu) if i not in used and x["label"]==y["label"] and max(x["start"],y["start"])<min(x["end"],y["end"])]
                if candidates:
                    i,y=candidates[0]; used.add(i); d[f"ENT_BOUNDARY|{x['label']}"] .append({"doc_id":g["doc_id"],"gold":x,"prediction":y,"context":g["text"][max(0,min(x['start'],y['start'])-50):max(x['end'],y['end'])+50]})
                else: d[f"ENT_FN|{x['label']}"] .append({"doc_id":g["doc_id"],"gold":x,"context":g["text"][max(0,x['start']-50):x['end']+50]})
        for i,y in enumerate(pu):
            if i not in used: d[f"ENT_FP|{y['label']}"] .append({"doc_id":g["doc_id"],"prediction":y,"context":g["text"][max(0,y['start']-50):y['end']+50]})
    return dict(d)


def annotate_relations(api,g,gold,out):
    def one(r):
        ents=copy.deepcopy(r["frozen_entities"]); valid={x["id"] for x in ents}; rels=[]; seen=set()
        payload={"guideline":g["deployment_guideline"],"rules":g["principles"],"report":{"doc_id":r["doc_id"],"text":r["text"]},"immutable_entities":ents,
                 "output_contract":{"relations":[{"subj":"T1","pred":"LocatedAt","obj":"T2"}]}}
        ans=api.json("Annotate relations only over immutable_entities. Never create or modify entities. Return one JSON object.",payload,out/"raw_annotations"/f"{r['doc_id']}.json")
        for q in ans.get("relations",[]):
            key=(str(q.get("subj")),str(q.get("pred")),str(q.get("obj")))
            if key[0] in valid and key[2] in valid and key[1] in RELATION_LABELS and key not in seen:
                seen.add(key); rels.append({"id":f"R{len(rels)+1}","subj":key[0],"pred":key[1],"obj":key[2]})
        return {"doc_id":r["doc_id"],"split":"pilot","text":r["text"],"entities":ents,"relations":rels}
    with ThreadPoolExecutor(max_workers=len(gold)) as pool:
        preds=list(pool.map(one,gold))
    dump(out/"predictions.json",preds); return preds


def rkey(record,q):
    es={x["id"]:x for x in record["entities"]}; return ekey(es[q["subj"]])+(q["pred"],)+ekey(es[q["obj"]])


def relation_score(gold,preds):
    by={p["doc_id"]:p for p in preds}; tp=fp=fn=0
    for g in gold:
        a=Counter(rkey(g,x) for x in g["relations"]); p=by[g["doc_id"]]; b=Counter(rkey(p,x) for x in p["relations"])
        tp+=sum((a&b).values()); fn+=sum((a-b).values()); fp+=sum((b-a).values())
    return {"tp":tp,"fp":fp,"fn":fn,"f1":f1(tp,fp,fn)}


def relation_census(gold,preds):
    by={p["doc_id"]:p for p in preds}; d=defaultdict(list)
    for g in gold:
        p=by[g["doc_id"]]; available={ekey(x) for x in p["entities"]}
        a=Counter(rkey(g,x) for x in g["relations"]); b=Counter(rkey(p,x) for x in p["relations"])
        for key,n in (a-b).items():
            cause="UNAVAILABLE|missing_entity_endpoint" if key[:3] not in available or key[4:] not in available else f"REL_FN|{key[3]}"
            for _ in range(n): d[cause].append({"doc_id":g["doc_id"],"gold_relation":key,"context":g["text"]})
        for key,n in (b-a).items():
            for _ in range(n): d[f"REL_FP|{key[3]}"] .append({"doc_id":g["doc_id"],"predicted_relation":key,"context":g["text"]})
    return dict(d)


def apply_candidate(g,c,iteration,cases,phase):
    out=copy.deepcopy(g); action=str(c.get("action","")).upper(); rule=copy.deepcopy(c.get("principle",{}))
    if action not in {"ADD","REVISE"} or not rule.get("instruction"): raise ValueError("invalid atomic candidate")
    rule.update({"domain":phase,"status":"active","supporting_doc_ids":sorted({str(x["doc_id"]) for x in cases})})
    if action=="ADD": rule["rule_id"]=f"{'EA' if phase=='entity' else 'RA'}{iteration:03d}"; out["principles"].append(rule)
    else:
        target=str(c.get("target_rule_id")); ix=[i for i,x in enumerate(out["principles"]) if str(x.get("rule_id"))==target]
        if len(ix)!=1: raise ValueError("REVISE target missing")
        rule["rule_id"]=target; out["principles"][ix[0]]=rule
    out["deployment_guideline"]=render(out); return out


def atomic_phase(api,phase,gold,g0,out):
    current=g0; pred=(annotate_entities if phase=="entity" else annotate_relations)(api,current,gold,out/"G0")
    score=(entity_score if phase=="entity" else relation_score)(gold,pred); rejected=defaultdict(set); history=[]; i=1
    while True:
        census=(entity_census if phase=="entity" else relation_census)(gold,pred)
        eligible={k:v for k,v in census.items() if not k.startswith("UNAVAILABLE|")}
        sig=hashlib.sha256(json.dumps({"g":current["principles"],"c":eligible},sort_keys=True,default=str).encode()).hexdigest()
        ranked=[k for k,v in sorted(eligible.items(),key=lambda z:(-len(z[1]),-len({str(x['doc_id']) for x in z[1]}),z[0])) if k not in rejected[sig]]
        if not ranked: break
        stratum=ranked[0]; cases=eligible[stratum]
        payload={"task":f"Propose exactly one generalizable atomic ADD or REVISE for the selected {phase} discrepancy stratum.","selected_stratum":stratum,
                 "complete_discrepancy_evidence":cases,"current_principles":current["principles"],"prior_decisions":history,
                 "output_contract":{"action":"ADD or REVISE","target_rule_id":"existing ID for REVISE; null for ADD","principle":{"instruction":"one operational rule","applies_when":"condition","exceptions":[],"priority":1,"examples":[]},"rationale":"text"}}
        cdir=out/f"candidate_{i:03d}"; dump(cdir/"prompt.json",payload)
        try:
            c=api.json("Return one valid JSON object. Change one rule only; do not patch a document-specific answer.",payload,cdir/"raw.json")
            proposed=apply_candidate(current,c,i,cases,phase); dump(cdir/"guideline.json",proposed)
            newpred=(annotate_entities if phase=="entity" else annotate_relations)(api,proposed,gold,cdir)
            newscore=(entity_score if phase=="entity" else relation_score)(gold,newpred)
            oldn=sum(len(x) for x in eligible.values()); newc=(entity_census if phase=="entity" else relation_census)(gold,newpred)
            newn=sum(len(v) for k,v in newc.items() if not k.startswith("UNAVAILABLE|"))
            accept=newscore["f1"]>score["f1"]+1e-12 or (abs(newscore["f1"]-score["f1"])<=1e-12 and newn<oldn)
            reason="f1_improved" if newscore["f1"]>score["f1"]+1e-12 else ("f1_tied_net_errors_improved" if accept else "admission_failed")
        except Exception as e:
            accept=False; reason=f"invalid_candidate:{e}"; newscore=score
        decision={"iteration":i,"stratum":stratum,"cases":len(cases),"accepted":accept,"reason":reason,"before":score,"after":newscore}
        dump(cdir/"decision.json",decision); history.append(decision)
        if accept: current,pred,score=proposed,newpred,newscore
        else: rejected[sig].add(stratum)
        dump(out/"state.json",{"history":history,"current_score":score}); i+=1
    dump(out/"G_star"/"guideline.json",current); dump(out/"G_star"/"predictions.json",pred); dump(out/"G_star"/"score.json",score)
    return current,pred,score,history


def main():
    a=cli(); base.load_env(a.env_file); plan=json.loads(a.plan.read_text(encoding="utf-8"))
    cond=next((x for x in plan["conditions"] if x["condition_id"]==a.condition),None)
    if not cond: raise ValueError("Unknown condition")
    gold=load_selected(a.gold,cond["doc_ids"]); a.output.mkdir(parents=True,exist_ok=True); api=API(a)
    manifest={"protocol":"two-phase-preliminary-v1","provider":a.provider,"requested_model":a.model,"reasoning_effort":"high",
              "thinking_enabled":a.provider=="deepseek","temperature_sent":False,"condition":cond,"heldout_retained_or_evaluated":False,
              "created_utc":datetime.now(timezone.utc).isoformat()}; dump(a.output/"manifest.json",manifest)
    e0=initial_guideline(api,"entity",gold,a.output/"entity"); eg,ep,es,eh=atomic_phase(api,"entity",gold,e0,a.output/"entity")
    relgold=[]
    by={p["doc_id"]:p for p in ep}
    for g in gold:
        x=copy.deepcopy(g); x["frozen_entities"]=copy.deepcopy(by[g["doc_id"]]["entities"]); relgold.append(x)
    r0=initial_guideline(api,"relation",relgold,a.output/"relation"); rg,rp,rs,rh=atomic_phase(api,"relation",relgold,r0,a.output/"relation")
    manifest.update({"completed_utc":datetime.now(timezone.utc).isoformat(),"entity_score":es,"relation_score":rs,
                     "entity_candidates":len(eh),"relation_candidates":len(rh),"usage":api.usage,
                     "returned_models":sorted({str(x.get('returned_model')) for x in api.usage})})
    dump(a.output/"manifest.json",manifest)
    print(json.dumps({"output":str(a.output),"entity":es,"relation":rs,"entity_candidates":len(eh),"relation_candidates":len(rh)},indent=2))

if __name__=="__main__": main()

"""Recompute the complete no-API held-out analysis after span canonicalization.

The canonicalizer is model independent and applied to every model/condition:
1. reconcile raw surface text with numeric offsets using only the source report;
2. trim terminal clause punctuation from prediction and reference spans;
3. merge duplicate canonical entities and remap/deduplicate relations; and
4. drop only irreconcilable internally inconsistent entities and dependent relations.

No held-out reference span is consulted when repairing a prediction.
"""

from __future__ import annotations

import csv
import json
import re
import statistics
import sys
from collections import Counter, defaultdict
from copy import deepcopy
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))

import analyze_final_guideline_study as final
import evaluate_radgraph_ie as evaluator


OUT = ROOT / "llm_preliminary/analysis/canonicalized_heldout_analysis_v1"
PUNCTUATION = ".,;:"


def raw_answer(path: Path) -> dict:
    wrapper = json.loads(path.read_text(encoding="utf-8"))
    content = wrapper["response"]["choices"][0]["message"]["content"]
    return json.loads(content)


def retained_raw_entities(doc: dict, answer: dict) -> dict[str, dict]:
    """Recreate run_heldout38.normalize_entities_audit ID assignment."""
    proposed = answer.get("entities", [])
    if not isinstance(proposed, list):
        return {}
    seen = set()
    retained = {}
    for item in proposed:
        if not isinstance(item, dict):
            continue
        try:
            start, end, label = int(item["start"]), int(item["end"]), str(item["label"])
        except Exception:
            continue
        key = (start, end, label)
        if label not in evaluator.ENTITY_LABELS or not 0 <= start < end <= len(doc["text"]) or key in seen:
            continue
        seen.add(key)
        entity_id = f"T{len(retained) + 1}"
        retained[entity_id] = {
            "id": entity_id,
            "start": start,
            "end": end,
            "label": label,
            "returned_text": item.get("text"),
        }
    return retained


def nearest_overlapping_surface(text: str, returned: str, start: int, end: int) -> tuple[int, int] | None:
    candidates = []
    for match in re.finditer(re.escape(returned), text):
        pair = (match.start(), match.end())
        if max(pair[0], start) < min(pair[1], end):
            distance = abs(pair[0] - start) + abs(pair[1] - end)
            candidates.append((distance, pair))
    candidates.sort()
    if not candidates:
        return None
    if len(candidates) > 1 and candidates[0][0] == candidates[1][0]:
        return None
    return candidates[0][1]


def trim_terminal_punctuation(text: str, start: int, end: int) -> tuple[int, int]:
    while end > start and text[end - 1] in PUNCTUATION:
        end -= 1
    return start, end


def canonicalize_prediction_document(doc: dict, raw: dict) -> tuple[dict, dict, list[dict]]:
    source = doc["text"]
    raw_by_id = retained_raw_entities(doc, raw)
    audit = Counter()
    examples = []
    candidates = []

    for entity in doc["entities"]:
        old = dict(entity)
        start, end, label = int(entity["start"]), int(entity["end"]), str(entity["label"])
        raw_item = raw_by_id.get(str(entity["id"]))
        if raw_item is None:
            audit["missing_raw_entity_mapping"] += 1
            returned = source[start:end]
        else:
            returned = raw_item.get("returned_text")

        offset_surface = source[start:end]
        mismatch = returned != offset_surface
        if mismatch:
            audit["raw_text_offset_mismatches"] += 1
            if isinstance(returned, str) and returned and returned.casefold() == offset_surface.casefold():
                audit["case_only_mismatches_retained"] += 1
            elif isinstance(returned, str) and returned:
                repaired = nearest_overlapping_surface(source, returned, start, end)
                if repaired is None:
                    audit["irreconcilable_entities_dropped"] += 1
                    examples.append(
                        {
                            "event": "irreconcilable_entity_dropped",
                            "entity_id": entity["id"],
                            "label": label,
                            "old_start": start,
                            "old_end": end,
                            "offset_surface": offset_surface,
                            "returned_text": returned,
                        }
                    )
                    continue
                start, end = repaired
                audit["offsets_realigned_to_raw_surface"] += 1
            else:
                audit["irreconcilable_entities_dropped"] += 1
                continue

        before_trim = (start, end)
        start, end = trim_terminal_punctuation(source, start, end)
        if (start, end) != before_trim:
            audit["terminal_punctuation_trimmed"] += 1
        if start >= end:
            audit["empty_entities_dropped"] += 1
            continue
        canonical = {
            "id": str(entity["id"]),
            "start": start,
            "end": end,
            "label": label,
            "text": source[start:end],
        }
        candidates.append((canonical, old))

    kept_entities = []
    key_to_id = {}
    old_to_new = {}
    for canonical, old in candidates:
        key = (canonical["start"], canonical["end"], canonical["label"])
        if key in key_to_id:
            old_to_new[str(old["id"])] = key_to_id[key]
            audit["duplicate_entities_merged"] += 1
            continue
        key_to_id[key] = canonical["id"]
        old_to_new[str(old["id"])] = canonical["id"]
        kept_entities.append(canonical)

    kept_relations = []
    seen_relations = set()
    for relation in doc.get("relations", []):
        subj = old_to_new.get(str(relation["subj"]))
        obj = old_to_new.get(str(relation["obj"]))
        if subj is None or obj is None:
            audit["relations_dropped_missing_canonical_endpoint"] += 1
            continue
        key = (subj, relation["pred"], obj)
        if key in seen_relations:
            audit["duplicate_relations_merged"] += 1
            continue
        seen_relations.add(key)
        kept_relations.append({"id": str(relation["id"]), "subj": subj, "pred": relation["pred"], "obj": obj})

    canonical_doc = {**doc, "entities": kept_entities, "relations": kept_relations}
    audit.update(
        {
            "entities_before": len(doc["entities"]),
            "entities_after": len(kept_entities),
            "relations_before": len(doc.get("relations", [])),
            "relations_after": len(kept_relations),
        }
    )
    return canonical_doc, dict(audit), examples


def canonicalize_reference_document(doc: dict) -> tuple[dict, dict]:
    row = deepcopy(doc)
    audit = Counter()
    old_to_new = {}
    key_to_id = {}
    kept = []
    for entity in row["entities"]:
        start, old_end = int(entity["start"]), int(entity["end"])
        start, end = trim_terminal_punctuation(row["text"], start, old_end)
        if end != old_end:
            audit["reference_terminal_punctuation_trimmed"] += 1
        if start >= end:
            audit["reference_empty_entities_dropped"] += 1
            continue
        key = (start, end, entity["label"])
        if key in key_to_id:
            old_to_new[str(entity["id"])] = key_to_id[key]
            audit["reference_duplicate_entities_merged"] += 1
            continue
        canonical = {**entity, "start": start, "end": end, "text": row["text"][start:end]}
        key_to_id[key] = str(entity["id"])
        old_to_new[str(entity["id"])] = str(entity["id"])
        kept.append(canonical)
    relations = []
    seen = set()
    for relation in row["relations"]:
        subj = old_to_new.get(str(relation["subj"]))
        obj = old_to_new.get(str(relation["obj"]))
        if subj is None or obj is None:
            audit["reference_relations_dropped_missing_endpoint"] += 1
            continue
        key = (subj, relation["pred"], obj)
        if key in seen:
            audit["reference_duplicate_relations_merged"] += 1
            continue
        seen.add(key)
        relations.append({**relation, "subj": subj, "obj": obj})
    row["entities"], row["relations"] = kept, relations
    return row, dict(audit)


def condition_root(config: dict, condition: str) -> tuple[Path, str]:
    cid = final.CONDITIONS[condition][0]
    return (config["g0"] if condition == "G0" else config["final"]), cid


def canonicalize_condition(model: str, config: dict, condition: str) -> tuple[list[dict], list[dict], list[dict]]:
    _entity_rows, relation_rows = final.load_predictions(config, condition)
    root, cid = condition_root(config, condition)
    canonical_rows, audit_rows, examples = [], [], []
    for row in relation_rows:
        doc_id = str(row["doc_id"])
        canonical, audit, doc_examples = canonicalize_prediction_document(
            row, raw_answer(root / cid / "raw_entities" / f"{doc_id}.json")
        )
        canonical_rows.append(canonical)
        audit_rows.append({"model": model, "condition": condition, "doc_id": doc_id, **audit})
        examples.extend({"model": model, "condition": condition, "doc_id": doc_id, **item} for item in doc_examples)
    canonical_rows.sort(key=lambda row: str(row["doc_id"]))
    return canonical_rows, audit_rows, examples


def canonicalize_special_predictions(
    model: str,
    condition: str,
    predictions_path: Path,
    raw_dir: Path,
) -> tuple[list[dict], list[dict], list[dict]]:
    rows = json.loads(predictions_path.read_text(encoding="utf-8"))
    canonical_rows, audits, examples = [], [], []
    for row in rows:
        doc_id = str(row["doc_id"])
        canonical, audit, doc_examples = canonicalize_prediction_document(row, raw_answer(raw_dir / f"{doc_id}.json"))
        canonical_rows.append(canonical)
        audits.append({"model": model, "condition": condition, "doc_id": doc_id, **audit})
        examples.extend({"model": model, "condition": condition, "doc_id": doc_id, **item} for item in doc_examples)
    return canonical_rows, audits, examples


def evaluate_rows(gold_by_id: dict[str, dict], predictions: list[dict]) -> dict[str, dict]:
    by_id = {str(row["doc_id"]): row for row in predictions}
    return {doc_id: evaluator.evaluate_document(gold, by_id[doc_id])[0] for doc_id, gold in gold_by_id.items()}


def metric_and_label_rows(model: str, condition: str, doc_results: dict[str, dict]) -> tuple[list[dict], list[dict]]:
    merged = evaluator.render_scores(evaluator.merge_results(list(doc_results.values())))
    aggregates, labels_out = [], []
    for metric, (family, method) in final.METRIC_KEYS.items():
        aggregates.append(
            {
                "model": model,
                "condition": condition,
                "condition_name": final.CONDITIONS[condition][1],
                "analysis_status": final.CONDITIONS[condition][2],
                "metric": metric,
                **merged[family][method]["overall"],
            }
        )
        labels = final.two.ENTITY_LABELS if family == "entities" else final.two.RELATION_LABELS
        for label in labels:
            values = merged[family][method]["per_label"][label]
            support = sum(
                final.metric_counts(result, metric, label)["tp"] + final.metric_counts(result, metric, label)["fn"]
                for result in doc_results.values()
            )
            labels_out.append(
                {
                    "model": model,
                    "condition": condition,
                    "metric": metric,
                    "label": label,
                    "gold_support": support,
                    **values,
                }
            )
    return aggregates, labels_out


def summarize_audit(rows: list[dict]) -> list[dict]:
    grouped = defaultdict(Counter)
    for row in rows:
        key = (row["model"], row["condition"])
        for field, value in row.items():
            if field not in {"model", "condition", "doc_id"}:
                grouped[key][field] += int(value or 0)
    return [{"model": model, "condition": condition, **dict(values)} for (model, condition), values in sorted(grouped.items())]


def write_capture_tables(
    aggregate: list[dict],
    contrasts: list[dict],
    label_metrics: list[dict],
    label_contrasts: list[dict],
    directions: list[dict],
    endpoint_rows: list[dict],
