    audit_summary: list[dict],
    reconciliation: list[dict],
) -> None:
    metric = {(row["model"], row["condition"], row["metric"]): row for row in aggregate}
    contrast = {(row["model"], row["contrast"], row["metric"]): row for row in contrasts}
    lines = [
        "# Capture-ready canonicalized held-out results",
