            lines.append(
                f"| {model} | {condition} | {metric[(model, condition, 'entity_exact')]['f1']:.4f} | "
                f"{metric[(model, condition, 'entity_overlap')]['f1']:.4f} | "
                f"{metric[(model, condition, 'relation_exact')]['f1']:.4f} | "
                f"{metric[(model, condition, 'relation_overlap')]['f1']:.4f} |"
            )
    lines += [
        "",
        "## Table 2. Canonicalized S0–G0–G* contrasts",
        "",
        "| Model | Contrast | Metric | Difference | 95% CI | Status |",
