"""Build a reproducible qualitative casebook from canonicalized held-out outputs.

This script performs no API calls. It stratifies entity and relation errors,
tracks exact-unit repair/regression across S0, G0, and Gstar, and contrasts the
two model pipelines on the same 38 held-out reports.
"""

from __future__ import annotations

import csv
import json
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))

import analyze_canonicalized_heldout as canonical
import analyze_final_guideline_study as final
from build_error_taxonomy import pair_entities


