def dump(path: Path, value) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8")


def write_csv(path: Path, rows: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fields = list(dict.fromkeys(key for row in rows for key in row))
    with path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)


def load_gold() -> list[dict]:
    source_gold = final.load_jsonl(final.GOLD)
    deduplicated, _ = final.deduplicate_reference_relations(source_gold)
    canonical_gold = [canonical.canonicalize_reference_document(row)[0] for row in deduplicated]
    return [row for row in canonical_gold if row["split"] == "heldout"]


def load_predictions(slug: str, condition: str) -> list[dict]:
    return json.loads(
        (SOURCE / "canonical_predictions" / slug / f"{condition}.json").read_text(encoding="utf-8")
    )


def clean_space(value: str) -> str:
    return re.sub(r"\s+", " ", value).strip()


def context_window(text: str, spans: list[tuple[int, int]], width: int = 130) -> str:
    if not spans:
        return ""
    start = max(0, min(left for left, _ in spans) - width)
    end = min(len(text), max(right for _, right in spans) + width)
    left_breaks = [text.rfind(marker, 0, start) for marker in ("\n", ". ")]
    left = max(left_breaks)
    if left >= 0:
        start = left + 1
    right_candidates = [position for position in (text.find("\n", end), text.find(". ", end)) if position >= 0]
    if right_candidates:
        end = min(right_candidates) + 1
    return clean_space(text[start:end])


def entity_key(entity: dict) -> tuple:
    return int(entity["start"]), int(entity["end"]), str(entity["label"])


def entity_ref(entity: dict | None) -> str:
    if not entity:
        return "—"
    return f"{entity['text']} [{entity['label']}; {entity['start']}:{entity['end']}]"


def relation_key(doc: dict, relation: dict) -> tuple:
    entities = {entity["id"]: entity for entity in doc["entities"]}
    subj, obj = entities[relation["subj"]], entities[relation["obj"]]
    return (*entity_key(subj), relation["pred"], *entity_key(obj))


def relation_ref_from_key(key: tuple, text: str) -> str:
    ss, se, sl, pred, os, oe, ol = key
    return f"{text[ss:se]} [{sl}] --{pred}--> {text[os:oe]} [{ol}]"


def event_lexeme(event: dict) -> str:
    target = event.get("gold") or event.get("prediction") or {}
    if "subject" in target:
        return clean_space(
            f"{target['subject']['text']} {target.get('predicate', '')} {target['object']['text']}"
        ).lower()
    return clean_space(str(target.get("text", ""))).lower()


def entity_construction(event: dict) -> str:
    target = event.get("gold") or event.get("prediction") or {}
    token = clean_space(str(target.get("text", ""))).lower()
    if token == "xxxx" or "xxxx" in token:
        return "deidentified_placeholder"
    if token in {"bilateral", "bilaterally", "right", "left"}:
        return "laterality_or_distribution"
    if token in {"interval", "prior", "again", "unchanged", "stable"}:
        return "temporal_or_comparison_language"
    if token in {"within", "normal", "limits", "unremarkable", "clear"}:
        return "normality_construction"
    if token in {"disease", "scarring", "chronic", "possible", "probable", "focal"}:
        return "certainty_scope"
    if token in {"size", "configuration", "appearance", "interstitial", "density"}:
        return "anatomy_observation_role"
    if token in {"in", "of", "evidence", "present", "findings", "grossly"}:
        return "function_or_discourse_token"
    if re.search(r"\d", token) or token in {"cm", "mm", "diameter"}:
        return "measurement_expression"
    return "other"


def relation_construction(event: dict) -> str:
    endpoints = []
    for side in ("gold", "prediction"):
        relation = event.get(side)
        if relation:
            endpoints.extend(
                [
                    clean_space(relation["subject"]["text"]).lower(),
                    clean_space(relation["object"]["text"]).lower(),
                ]
            )
    values = set(endpoints)
    context = event.get("context", "").lower()
    if "

" in context and values & {"within", "normal", "limits"}:
        return "within_normal_limits_graph"
    if "heart size" in context and values & {"heart", "size", "normal"}:
        return "heart_size_normality_graph"
    if {"pulmonary", "vascularity"}.issubset(values):
        return "pulmonary_vascularity_direction"
    if {"osseous", "structures"}.issubset(values):
        return "osseous_structures_direction"
    if values & {"bilateral", "bilaterally"}:
        return "laterality_or_distribution_attachment"
    if values & {"xxxx"}:
        return "deidentified_placeholder_endpoint"
    if any(re.search(r"\d", value) or value in {"cm", "mm", "diameter"} for value in values):
        return "measurement_attachment"
    if values & {"disease", "scarring", "pneumonia", "atelectasis", "empyema", "hematoma"}:
        return "diagnostic_or_certainty_chain"
    return "other"


def select_diverse(events: list[dict], limit: int = 3) -> list[dict]:
    frequencies = Counter(event_lexeme(event) for event in events)
    ranked = sorted(
        events,
        key=lambda event: (
            -frequencies[event_lexeme(event)],
            str(event.get("doc_id", "")),
            event_lexeme(event),
        ),
    )
    selected, seen_docs = [], set()
    for event in ranked:
        if str(event.get("doc_id")) in seen_docs:
            continue
        selected.append(event)
        seen_docs.add(str(event.get("doc_id")))
        if len(selected) == limit:
            break
    return selected


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    gold = load_gold()
    gold_by = {str(row["doc_id"]): row for row in gold}
    predictions = {
        model: {condition: load_predictions(slug, condition) for condition in CONDITIONS}
        for slug, model in MODELS.items()
    }
    pred_by = {
        model: {
            condition: {str(row["doc_id"]): row for row in rows}
            for condition, rows in conditions.items()
        }
        for model, conditions in predictions.items()
    }

    entity_events, relation_events = [], []
    entity_examples, relation_examples = defaultdict(list), defaultdict(list)
    for model in MODELS.values():
        for condition in CONDITIONS:
            for gold_doc in gold:
                doc_id = str(gold_doc["doc_id"])
                pred_doc = pred_by[model][condition][doc_id]
                events, _ = pair_entities(gold_doc["entities"], pred_doc["entities"])
                for event in events:
                    spans = []
                    for side in ("gold", "prediction"):
                        if event.get(side):
                            spans.append((int(event[side]["start"]), int(event[side]["end"])))
                    row = {
                        "model": model,
                        "condition": condition,
                        "doc_id": doc_id,
                        "category": event["category"],
                        "subtype": event.get("subtype"),
                        "gold": event.get("gold"),
                        "prediction": event.get("prediction"),
                        "context": context_window(gold_doc["text"], spans),
                    }
                    entity_events.append(row)
                    entity_examples[(model, condition, event["category"])].append(row)

            census = final.causal.causal_census(gold, predictions[model][condition])
            for stratum, events in census.items():
                category = stratum.split("|", 1)[0]
                for event in events:
                    spans = []
                    for side in ("gold", "prediction"):
                        rel = event.get(side)
                        if rel:
                            spans.extend(
                                [
                                    (int(rel["subject"]["start"]), int(rel["subject"]["end"])),
                                    (int(rel["object"]["start"]), int(rel["object"]["end"])),
                                ]
                            )
                    doc_id = str(event["doc_id"])
                    row = {
                        "model": model,
                        "condition": condition,
                        "doc_id": doc_id,
                        "category": category,
                        "stratum": stratum,
                        "gold": event.get("gold"),
                        "prediction": event.get("prediction"),
                        "context": context_window(gold_by[doc_id]["text"], spans),
                    }
                    relation_events.append(row)
                    relation_examples[(model, condition, category)].append(row)

    trajectory_rows, trajectory_examples = [], defaultdict(list)
    for model in MODELS.values():
        for before, after in (("S0", "G0"), ("G0", "Gstar"), ("S0", "Gstar")):
            for task in ("entity", "relation"):
                totals = Counter()
                candidates = defaultdict(list)
                for doc_id, gold_doc in gold_by.items():
                    before_doc = pred_by[model][before][doc_id]
                    after_doc = pred_by[model][after][doc_id]
                    if task == "entity":
                        gold_units = {entity_key(entity) for entity in gold_doc["entities"]}
                        before_units = {entity_key(entity) for entity in before_doc["entities"]}
                        after_units = {entity_key(entity) for entity in after_doc["entities"]}
                    else:
                        gold_units = {relation_key(gold_doc, relation) for relation in gold_doc["relations"]}
                        before_units = {relation_key(before_doc, relation) for relation in before_doc["relations"]}
                        after_units = {relation_key(after_doc, relation) for relation in after_doc["relations"]}
                    groups = {
                        "gold_error_resolved": (gold_units - before_units) & after_units,
                        "gold_error_persistent": (gold_units - before_units) - after_units,
                        "gold_true_positive_regressed": (gold_units & before_units) - after_units,
                        "spurious_unit_removed": (before_units - gold_units) - after_units,
                        "new_spurious_unit": (after_units - gold_units) - before_units,
                    }
                    for category, units in groups.items():
                        totals[category] += len(units)
                        for unit in sorted(units, key=str):
                            spans = [(unit[0], unit[1])] if task == "entity" else [(unit[0], unit[1]), (unit[4], unit[5])]
                            candidates[category].append(
                                {
                                    "model": model,
                                    "transition": f"{before}->{after}",
                                    "task": task,
                                    "category": category,
                                    "doc_id": doc_id,
                                    "unit": entity_ref({"text": gold_doc["text"][unit[0]:unit[1]], "label": unit[2], "start": unit[0], "end": unit[1]})
                                    if task == "entity"
                                    else relation_ref_from_key(unit, gold_doc["text"]),
                                    "context": context_window(gold_doc["text"], spans),
                                }
                            )
                for category, count in totals.items():
                    trajectory_rows.append(
                        {
                            "model": model,
                            "transition": f"{before}->{after}",
                            "task": task,
                            "category": category,
                            "count": count,
                        }
                    )
                    trajectory_examples[(model, f"{before}->{after}", task, category)] = select_diverse(
                        candidates[category]
                    )

    cross_model_rows, cross_model_examples = [], defaultdict(list)
    deep, gpt = "DeepSeek V4 Pro", "GPT-5.6 Terra"
    for task in ("entity", "relation"):
        totals = Counter()
        examples = defaultdict(list)
        for doc_id, gold_doc in gold_by.items():
            if task == "entity":
                gold_units = {entity_key(entity) for entity in gold_doc["entities"]}
                deep_units = {entity_key(entity) for entity in pred_by[deep]["Gstar"][doc_id]["entities"]}
                gpt_units = {entity_key(entity) for entity in pred_by[gpt]["Gstar"][doc_id]["entities"]}
            else:
                gold_units = {relation_key(gold_doc, relation) for relation in gold_doc["relations"]}
                deep_units = {relation_key(pred_by[deep]["Gstar"][doc_id], relation) for relation in pred_by[deep]["Gstar"][doc_id]["relations"]}
                gpt_units = {relation_key(pred_by[gpt]["Gstar"][doc_id], relation) for relation in pred_by[gpt]["Gstar"][doc_id]["relations"]}
            groups = {
                "shared_gold_miss": (gold_units - deep_units) & (gold_units - gpt_units),
                "deepseek_only_gold_miss": (gold_units - deep_units) - (gold_units - gpt_units),
                "gpt_only_gold_miss": (gold_units - gpt_units) - (gold_units - deep_units),
                "shared_spurious_unit": (deep_units - gold_units) & (gpt_units - gold_units),
            }
            for category, units in groups.items():
                totals[category] += len(units)
                for unit in sorted(units, key=str):
                    spans = [(unit[0], unit[1])] if task == "entity" else [(unit[0], unit[1]), (unit[4], unit[5])]
                    examples[category].append(
                        {
                            "task": task,
                            "category": category,
                            "doc_id": doc_id,
                            "unit": entity_ref({"text": gold_doc["text"][unit[0]:unit[1]], "label": unit[2], "start": unit[0], "end": unit[1]})
                            if task == "entity"
                            else relation_ref_from_key(unit, gold_doc["text"]),
                            "context": context_window(gold_doc["text"], spans),
                        }
                    )
        for category, count in totals.items():
            cross_model_rows.append({"task": task, "category": category, "count": count})
            cross_model_examples[(task, category)] = select_diverse(examples[category])

    casebook = {
        "selection_rule": "Within each stratum, rank recurring lexical signatures first, then choose at most three different reports deterministically.",
        "entity_gstar": {
            model: {
                category: select_diverse(entity_examples[(model, "Gstar", category)])
                for category in sorted({key[2] for key in entity_examples if key[:2] == (model, "Gstar")})
            }
            for model in MODELS.values()
        },
        "relation_gstar": {
            model: {
                category: select_diverse(relation_examples[(model, "Gstar", category)])
                for category in sorted({key[2] for key in relation_examples if key[:2] == (model, "Gstar")})
            }
            for model in MODELS.values()
        },
        "trajectory": {"|".join(key): value for key, value in sorted(trajectory_examples.items())},
        "cross_model": {"|".join(key): value for key, value in sorted(cross_model_examples.items())},
    }

    construction_rows = []
    for model in MODELS.values():
        entity_counts = Counter(
            (entity_construction(row), row["category"])
            for row in entity_events
            if row["model"] == model and row["condition"] == "Gstar"
        )
        relation_counts = Counter(
            (relation_construction(row), row["category"])
            for row in relation_events
            if row["model"] == model and row["condition"] == "Gstar"
        )
        construction_rows.extend(
            {
                "model": model,
                "task": "entity",
                "construction": construction,
                "error_category": category,
                "count": count,
            }
            for (construction, category), count in sorted(entity_counts.items())
        )
        construction_rows.extend(
            {
                "model": model,
                "task": "relation",
                "construction": construction,
                "error_category": category,
                "count": count,
            }
            for (construction, category), count in sorted(relation_counts.items())
        )

    trajectory_net_rows = []
    trajectory_lookup = {
        (row["model"], row["transition"], row["task"], row["category"]): int(row["count"])
        for row in trajectory_rows
    }
    for model in MODELS.values():
        for transition in ("S0->G0", "G0->Gstar", "S0->Gstar"):
            for task in ("entity", "relation"):
                get = lambda category: trajectory_lookup.get((model, transition, task, category), 0)
                resolved = get("gold_error_resolved")
                regressed = get("gold_true_positive_regressed")
                removed = get("spurious_unit_removed")
                introduced = get("new_spurious_unit")
                trajectory_net_rows.append(
                    {
                        "model": model,
                        "transition": transition,
                        "task": task,
                        "resolved_gold_errors": resolved,
                        "regressed_true_positives": regressed,
                        "net_true_positive_change": resolved - regressed,
                        "removed_spurious_units": removed,
                        "introduced_spurious_units": introduced,
                        "net_false_positive_change": introduced - removed,
                    }
                )

    write_csv(
        OUT / "entity_events.csv",
        [
            {**row, "gold": entity_ref(row.get("gold")), "prediction": entity_ref(row.get("prediction"))}
            for row in entity_events
        ],
    )
    write_csv(
        OUT / "relation_events.csv",
        [
            {
                **row,
                "gold": json.dumps(row.get("gold"), ensure_ascii=False),
                "prediction": json.dumps(row.get("prediction"), ensure_ascii=False),
            }
            for row in relation_events
        ],
    )
    write_csv(OUT / "trajectory_summary.csv", trajectory_rows)
    write_csv(OUT / "trajectory_net_summary.csv", trajectory_net_rows)
    write_csv(OUT / "cross_model_summary.csv", cross_model_rows)
    write_csv(OUT / "construction_cluster_summary.csv", construction_rows)
    dump(OUT / "QUALITATIVE_CASEBOOK.json", casebook)
    summary = {
        "heldout_reports": len(gold),
        "entity_error_events": len(entity_events),
        "relation_error_events": len(relation_events),
        "trajectory_rows": len(trajectory_rows),
        "cross_model_rows": len(cross_model_rows),
        "casebook_strata": sum(len(value) for value in casebook["entity_gstar"].values())
        + sum(len(value) for value in casebook["relation_gstar"].values())
        + len(casebook["trajectory"])
        + len(casebook["cross_model"]),
    }
    dump(OUT / "SUMMARY.json", summary)
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()

