"""Diagnose exact-versus-overlap gaps in the final held-out G* runs.

This analysis is deliberately API-free.  It reproduces the official scorer,
links raw surface-text mismatches to scored entities, classifies every entity
rescued by overlap matching, decomposes downstream relation recovery, and runs
a conservative gold-blind offset repair when the raw surface text occurs at one
unique location in the source report.
"""

from __future__ import annotations

import csv
import json
import re
import string
import sys
from collections import Counter, defaultdict
from copy import deepcopy
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))

import evaluate_radgraph_ie as evaluator


OUT = ROOT / "llm_preliminary/analysis/exact_overlap_gap_v1"
GOLD = (
    ROOT
    / "study_resources/emnlp_guideline_study/data/interim/iu_xray/"
    "human_gold_with_relations.jsonl"
)
CONDITION = "S1_sparse_gold_gstar"
MODELS = {
    "DeepSeek V4 Pro": ROOT / "llm_preliminary/runs/deepseek_v4_pro_heldout38_final_v2",
    "GPT-5.6 Terra": ROOT / "llm_preliminary/runs/gpt_5_6_terra_high_heldout38_final_v2",
}


def load_jsonl(path: Path) -> list[dict]:
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def write_csv(path: Path, rows: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if not rows:
        path.write_text("", encoding="utf-8")
        return
    fields: list[str] = []
    for row in rows:
        for key in row:
            if key not in fields:
                fields.append(key)
    with path.open("w", encoding="utf-8-sig", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(rows)


def deduplicate_reference_relations(rows: list[dict]) -> list[dict]:
    cleaned = []
    for source in rows:
        row = {**source, "relations": []}
        seen = set()
        for relation in source["relations"]:
            key = (relation["subj"], relation["pred"], relation["obj"])
            if key not in seen:
                row["relations"].append(relation)
                seen.add(key)
        cleaned.append(row)
    return cleaned


def trim_reference_terminal_punctuation(rows: list[dict]) -> tuple[list[dict], list[dict]]:
    """Apply G* E10 to a copy of the reference spans for sensitivity analysis."""
    normalized = deepcopy(rows)
    audit = []
    for row in normalized:
        for entity in row["entities"]:
            old_start, old_end = entity["start"], entity["end"]
            new_end = old_end
            while new_end > old_start and row["text"][new_end - 1] in ".,;:":
                new_end -= 1
            if new_end != old_end:
                audit.append(
                    {
                        "doc_id": str(row["doc_id"]),
                        "entity_id": entity["id"],
                        "label": entity["label"],
                        "old_start": old_start,
                        "old_end": old_end,
                        "old_text": row["text"][old_start:old_end],
                        "new_start": old_start,
                        "new_end": new_end,
                        "new_text": row["text"][old_start:new_end],
                        "normalization_rule": "Gstar E10 terminal punctuation trimming",
                    }
                )
                entity["end"] = new_end
                entity["text"] = row["text"][old_start:new_end]
    return normalized, audit


def score(counts: Counter) -> dict:
    tp, fp, fn = counts["tp"], counts["fp"], counts["fn"]
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * tp / (2 * tp + fp + fn) if 2 * tp + fp + fn else 0.0
    return {"tp": tp, "fp": fp, "fn": fn, "precision": precision, "recall": recall, "f1": f1}


def raw_answer(path: Path) -> dict:
    wrapper = json.loads(path.read_text(encoding="utf-8"))
    response = wrapper["response"]
    content = response["choices"][0]["message"]["content"]
    return json.loads(content)


def raw_entity_audit(run_root: Path, prediction_rows: list[dict]) -> tuple[dict[str, set[tuple]], list[dict]]:
    """Recover mismatched raw text items by the same retention logic as the run."""
    by_doc = {str(row["doc_id"]): row for row in prediction_rows}
    mismatch_keys: dict[str, set[tuple]] = defaultdict(set)
    details = []
    for doc_id, doc in by_doc.items():
        answer = raw_answer(run_root / CONDITION / "raw_entities" / f"{doc_id}.json")
        proposed = answer.get("entities", [])
        if not isinstance(proposed, list):
            continue
        seen = set()
        for item in proposed:
            if not isinstance(item, dict):
                continue
            try:
                start, end, label = int(item["start"]), int(item["end"]), str(item["label"])
            except Exception:
                continue
            key = (start, end, label)
            if label not in evaluator.ENTITY_LABELS or not 0 <= start < end <= len(doc["text"]) or key in seen:
                continue
            seen.add(key)
            returned_text = item.get("text")
            offset_text = doc["text"][start:end]
            if returned_text != offset_text:
                mismatch_keys[doc_id].add(key)
                details.append(
                    {
                        "doc_id": doc_id,
                        "start": start,
                        "end": end,
                        "label": label,
                        "returned_text": returned_text,
                        "offset_text": offset_text,
                    }
                )
    return mismatch_keys, details


def strip_edge_punctuation(text: str) -> str:
    return text.strip(string.whitespace + string.punctuation)


def token_count(text: str) -> int:
    return len(re.findall(r"\b\w+\b", text))


def boundary_pair_rows(model: str, gold_doc: dict, pred_doc: dict, raw_mismatches: set[tuple]) -> list[dict]:
    strict = evaluator.entity_mapping(gold_doc["entities"], pred_doc["entities"], "strict")
    overlap = evaluator.entity_mapping(gold_doc["entities"], pred_doc["entities"], "overlap")
    rows = []
    for pi, gi in sorted(overlap.items()):
        pred = pred_doc["entities"][pi]
        gold = gold_doc["entities"][gi]
        if (pred["start"], pred["end"]) == (gold["start"], gold["end"]):
            continue
        pred_overlaps = sum(
            evaluator.overlap(pred, other) > 0 and pred["label"] == other["label"]
            for other in gold_doc["entities"]
        )
        gold_overlaps = sum(
            evaluator.overlap(gold, other) > 0 and gold["label"] == other["label"]
            for other in pred_doc["entities"]
        )
        gold_text = gold_doc["text"][gold["start"] : gold["end"]]
        pred_text = pred_doc["text"][pred["start"] : pred["end"]]
        punctuation_only = strip_edge_punctuation(gold_text) == strip_edge_punctuation(pred_text)
        if pred_overlaps > 1 and gold_overlaps > 1:
            pattern = "many_to_many_context"
        elif pred_overlaps > 1:
            pattern = "predicted_merge_context"
        elif gold_overlaps > 1:
            pattern = "predicted_split_context"
        elif punctuation_only:
            pattern = "edge_punctuation_or_space_only"
        elif pred["start"] <= gold["start"] and pred["end"] >= gold["end"]:
            pattern = "lexical_expansion"
        elif gold["start"] <= pred["start"] and gold["end"] >= pred["end"]:
            pattern = "lexical_contraction"
        else:
            pattern = "partial_overlap_shift"
        if pred["start"] == gold["start"]:
            side = "right_only"
        elif pred["end"] == gold["end"]:
            side = "left_only"
        else:
            side = "both_boundaries"
        pred_key = (pred["start"], pred["end"], pred["label"])
        rows.append(
            {
                "model": model,
                "doc_id": str(gold_doc["doc_id"]),
                "label": gold["label"],
                "gold_start": gold["start"],
                "gold_end": gold["end"],
                "gold_text": gold_text,
                "pred_start": pred["start"],
                "pred_end": pred["end"],
                "pred_text": pred_text,
                "left_delta_pred_minus_gold": pred["start"] - gold["start"],
                "right_delta_pred_minus_gold": pred["end"] - gold["end"],
                "gold_tokens": token_count(gold_text),
                "pred_tokens": token_count(pred_text),
                "boundary_side": side,
                "boundary_pattern": pattern,
                "pred_overlapping_same_label_gold": pred_overlaps,
                "gold_overlapping_same_label_predictions": gold_overlaps,
                "raw_returned_text_mismatch": pred_key in raw_mismatches,
                "strict_mapping_contains_prediction": pi in strict,
            }
        )
    return rows


def metric_rows(model: str, prediction_rows: list[dict], gold_by_id: dict[str, dict], variant: str) -> list[dict]:
    results = []
    for row in prediction_rows:
        result, _ = evaluator.evaluate_document(gold_by_id[str(row["doc_id"])], row)
        results.append(result)
    merged = evaluator.merge_results(results)
    rows = []
    for target, family, method in (
        ("entity", "entities", "strict"),
        ("entity", "entities", "overlap"),
        ("relation", "relations", "end_to_end_strict"),
        ("relation", "relations", "end_to_end_overlap"),
    ):
        matching = "overlap" if method.endswith("overlap") else "exact"
        rows.append({"model": model, "variant": variant, "target": target, "matching": matching, "label": "ALL", **score(merged[family][method]["overall"])})
        labels = evaluator.ENTITY_LABELS if family == "entities" else evaluator.RELATION_LABELS
        for label in labels:
            rows.append(
                {
                    "model": model,
                    "variant": variant,
                    "target": target,
                    "matching": matching,
                    "label": label,
                    **score(merged[family][method]["per_label"][label]),
                }
            )
    return rows


def conservative_raw_text_repair(
    prediction_rows: list[dict], raw_details: list[dict]
) -> tuple[list[dict], list[dict]]:
    """Gold-blind repair: move only to a unique exact occurrence of returned text."""
    repaired = deepcopy(prediction_rows)
    by_doc = {str(row["doc_id"]): row for row in repaired}
    audit = []
    for item in raw_details:
        doc = by_doc[item["doc_id"]]
        returned = item["returned_text"]
        status = "not_repaired"
        reason = "returned_text_not_string_or_empty"
        candidates = []
        if isinstance(returned, str) and returned:
            candidates = [match.start() for match in re.finditer(re.escape(returned), doc["text"])]
            if len(candidates) == 1:
                new_start = candidates[0]
                new_end = new_start + len(returned)
                old_key = (item["start"], item["end"], item["label"])
                new_key = (new_start, new_end, item["label"])
                duplicates = {
                    (entity["start"], entity["end"], entity["label"])
                    for entity in doc["entities"]
                    if (entity["start"], entity["end"], entity["label"]) != old_key
                }
                entity = next(
                    (
                        entity
                        for entity in doc["entities"]
                        if (entity["start"], entity["end"], entity["label"]) == old_key
                    ),
                    None,
                )
                if entity is None:
                    reason = "normalized_entity_not_found"
                elif new_key in duplicates:
                    reason = "repair_would_create_duplicate"
                elif new_key == old_key:
                    reason = "offsets_already_match_returned_text"
                else:
                    entity["start"], entity["end"], entity["text"] = new_start, new_end, returned
                    status, reason = "repaired", "unique_exact_surface_occurrence"
            elif not candidates:
                reason = "returned_text_not_found_exactly"
            else:
                reason = "returned_text_occurrence_ambiguous"
        audit.append({**item, "candidate_occurrences": len(candidates), "status": status, "reason": reason})
    return repaired, audit


def local_raw_text_repair(prediction_rows: list[dict], raw_details: list[dict]) -> tuple[list[dict], list[dict]]:
    """Gold-blind local repair using the nearest occurrence overlapping the old span.

    This resolves the common case where the returned surface form omits terminal
    punctuation but the numeric end offset includes it.  Global relocations are
    prohibited: a candidate must overlap the originally returned span.
    """
    repaired = deepcopy(prediction_rows)
    by_doc = {str(row["doc_id"]): row for row in repaired}
    audit = []
    for item in raw_details:
        doc = by_doc[item["doc_id"]]
        returned = item["returned_text"]
        status = "not_repaired"
        reason = "returned_text_not_string_or_empty"
        candidates = []
        if isinstance(returned, str) and returned:
            for match in re.finditer(re.escape(returned), doc["text"]):
                candidate = (match.start(), match.end())
                if max(candidate[0], item["start"]) < min(candidate[1], item["end"]):
                    candidates.append(candidate)
            ranked = sorted(
                candidates,
                key=lambda pair: (abs(pair[0] - item["start"]) + abs(pair[1] - item["end"]), pair),
            )
            unique_best = bool(ranked) and (
                len(ranked) == 1
                or abs(ranked[0][0] - item["start"]) + abs(ranked[0][1] - item["end"])
                < abs(ranked[1][0] - item["start"]) + abs(ranked[1][1] - item["end"])
            )
            if unique_best:
                new_start, new_end = ranked[0]
                old_key = (item["start"], item["end"], item["label"])
                new_key = (new_start, new_end, item["label"])
                duplicates = {
                    (entity["start"], entity["end"], entity["label"])
                    for entity in doc["entities"]
                    if (entity["start"], entity["end"], entity["label"]) != old_key
                }
                entity = next(
                    (
                        entity
                        for entity in doc["entities"]
                        if (entity["start"], entity["end"], entity["label"]) == old_key
                    ),
                    None,
                )
                if entity is None:
                    reason = "normalized_entity_not_found"
                elif new_key in duplicates:
                    reason = "repair_would_create_duplicate"
                elif new_key == old_key:
                    reason = "offsets_already_match_returned_text"
                else:
                    entity["start"], entity["end"], entity["text"] = new_start, new_end, returned
                    status, reason = "repaired", "nearest_overlapping_exact_surface_occurrence"
            elif not candidates:
                reason = "no_exact_surface_occurrence_overlaps_old_span"
            else:
                reason = "nearest_overlapping_occurrence_tied"
        audit.append({**item, "candidate_occurrences": len(candidates), "status": status, "reason": reason})
    return repaired, audit


def relation_rescue_rows(model: str, gold_doc: dict, pred_doc: dict) -> list[dict]:
    """Classify overlap true-positive relations by endpoint boundary status."""
    mapping = evaluator.entity_mapping(gold_doc["entities"], pred_doc["entities"], "overlap")
    pred_index = {entity["id"]: i for i, entity in enumerate(pred_doc["entities"])}
    gold_index = {entity["id"]: i for i, entity in enumerate(gold_doc["entities"])}
    gold_available: dict[tuple, list[dict]] = defaultdict(list)
    for relation in gold_doc["relations"]:
        key = (gold_index[relation["subj"]], relation["pred"], gold_index[relation["obj"]])
        gold_available[key].append(relation)
    candidates = []
    for relation in pred_doc["relations"]:
        subj_pi, obj_pi = pred_index[relation["subj"]], pred_index[relation["obj"]]
        if subj_pi not in mapping or obj_pi not in mapping:
            continue
        key = (mapping[subj_pi], relation["pred"], mapping[obj_pi])
        candidates.append((key, relation, subj_pi, obj_pi))
    rows = []
    for key, relation, subj_pi, obj_pi in candidates:
        if not gold_available[key]:
            continue
        gold_available[key].pop()
        subj_gold, obj_gold = gold_doc["entities"][key[0]], gold_doc["entities"][key[2]]
        subj_pred, obj_pred = pred_doc["entities"][subj_pi], pred_doc["entities"][obj_pi]
        subj_exact = (subj_pred["start"], subj_pred["end"]) == (subj_gold["start"], subj_gold["end"])
        obj_exact = (obj_pred["start"], obj_pred["end"]) == (obj_gold["start"], obj_gold["end"])
        endpoint_pattern = (
            "both_exact"
            if subj_exact and obj_exact
            else "subject_boundary_only"
            if not subj_exact and obj_exact
            else "object_boundary_only"
            if subj_exact and not obj_exact
            else "both_endpoints_boundary"
        )
        rows.append(
            {
                "model": model,
                "doc_id": str(gold_doc["doc_id"]),
                "predicate": relation["pred"],
                "endpoint_pattern": endpoint_pattern,
                "rescued_beyond_exact": endpoint_pattern != "both_exact",
                "pred_subj_text": subj_pred["text"],
                "gold_subj_text": subj_gold["text"],
                "pred_obj_text": obj_pred["text"],
                "gold_obj_text": obj_gold["text"],
            }
        )
    return rows


def exact_tp_prediction_ids(gold_doc: dict, pred_doc: dict) -> tuple[set[str], set[str]]:
    """Return entity and relation prediction IDs allocated as strict TPs."""
    mapping = evaluator.entity_mapping(gold_doc["entities"], pred_doc["entities"], "strict")
    entity_ids = {pred_doc["entities"][pi]["id"] for pi in mapping}
    pred_index = {entity["id"]: i for i, entity in enumerate(pred_doc["entities"])}
    gold_index = {entity["id"]: i for i, entity in enumerate(gold_doc["entities"])}
    available = Counter(
        (gold_index[relation["subj"]], relation["pred"], gold_index[relation["obj"]])
        for relation in gold_doc["relations"]
    )
    relation_ids = set()
    for relation in pred_doc["relations"]:
        subj, obj = pred_index[relation["subj"]], pred_index[relation["obj"]]
        if subj not in mapping or obj not in mapping:
            continue
        key = (mapping[subj], relation["pred"], mapping[obj])
        if available[key] > 0:
            relation_ids.add(relation["id"])
            available[key] -= 1
    return entity_ids, relation_ids


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    gold_rows = deduplicate_reference_relations(load_jsonl(GOLD))
    gold_rows = [row for row in gold_rows if row.get("split") == "heldout"]
    gold_by_id = {str(row["doc_id"]): row for row in gold_rows}
    normalized_gold_rows, gold_punctuation_audit = trim_reference_terminal_punctuation(gold_rows)
    normalized_gold_by_id = {str(row["doc_id"]): row for row in normalized_gold_rows}
    metric_output = []
    boundary_output = []
    raw_output = []
    repair_output = []
    relation_output = []
    repaired_boundary_output = []
    repaired_relation_output = []
    repair_effect_output = []
    repair_effect_details = []
    summaries = []

    for model, run_root in MODELS.items():
        prediction_rows = json.loads((run_root / CONDITION / "predictions.json").read_text(encoding="utf-8"))
        pred_by_id = {str(row["doc_id"]): row for row in prediction_rows}
        raw_mismatch, raw_details = raw_entity_audit(run_root, prediction_rows)
        raw_output.extend({"model": model, **item} for item in raw_details)
        metric_output.extend(metric_rows(model, prediction_rows, gold_by_id, "as_returned_parser_view"))
        repaired_rows, repair_audit = conservative_raw_text_repair(prediction_rows, raw_details)
        repair_output.extend({"model": model, "repair_variant": "unique_global", **item} for item in repair_audit)
        metric_output.extend(metric_rows(model, repaired_rows, gold_by_id, "unique_raw_text_offset_repair"))
        local_repaired_rows, local_repair_audit = local_raw_text_repair(prediction_rows, raw_details)
        repair_output.extend({"model": model, "repair_variant": "nearest_overlapping", **item} for item in local_repair_audit)
        metric_output.extend(metric_rows(model, local_repaired_rows, gold_by_id, "local_raw_text_offset_repair"))
        metric_output.extend(
            metric_rows(
                model,
                local_repaired_rows,
                normalized_gold_by_id,
                "rule_aligned_prediction_and_gold_boundary_sensitivity",
            )
        )
        local_by_id = {str(row["doc_id"]): row for row in local_repaired_rows}
        for doc_id, gold_doc in gold_by_id.items():
            boundary_output.extend(boundary_pair_rows(model, gold_doc, pred_by_id[doc_id], raw_mismatch[doc_id]))
            relation_output.extend(relation_rescue_rows(model, gold_doc, pred_by_id[doc_id]))
            repaired_boundary_output.extend(boundary_pair_rows(model, gold_doc, local_by_id[doc_id], set()))
            repaired_relation_output.extend(relation_rescue_rows(model, gold_doc, local_by_id[doc_id]))
            before_entity, before_relation = exact_tp_prediction_ids(gold_doc, pred_by_id[doc_id])
            after_entity, after_relation = exact_tp_prediction_ids(gold_doc, local_by_id[doc_id])
            for target, before, after in (
                ("entity", before_entity, after_entity),
                ("relation", before_relation, after_relation),
            ):
                repair_effect_output.append(
                    {
                        "model": model,
                        "doc_id": doc_id,
                        "target": target,
                        "exact_tp_before": len(before),
                        "exact_tp_after": len(after),
                        "gained_exact_tp": len(after - before),
                        "lost_exact_tp": len(before - after),
                        "net_exact_tp_change": len(after) - len(before),
                    }
                )
                collection = "entities" if target == "entity" else "relations"
                before_items = {item["id"]: item for item in pred_by_id[doc_id][collection]}
                after_items = {item["id"]: item for item in local_by_id[doc_id][collection]}
                for effect, identifiers in (("gained", after - before), ("lost", before - after)):
                    for identifier in sorted(identifiers):
                        old = before_items[identifier]
                        new = after_items[identifier]
                        repair_effect_details.append(
                            {
                                "model": model,
                                "doc_id": doc_id,
                                "target": target,
                                "effect": effect,
                                "prediction_id": identifier,
                                "before": json.dumps(old, ensure_ascii=False, sort_keys=True),
                                "after": json.dumps(new, ensure_ascii=False, sort_keys=True),
                            }
                        )

        model_boundaries = [row for row in boundary_output if row["model"] == model]
        model_relations = [row for row in relation_output if row["model"] == model]
        summaries.append(
            {
                "model": model,
                "raw_text_mismatches": len(raw_details),
                "overlap_rescued_entities": len(model_boundaries),
                "rescued_entities_also_raw_text_mismatch": sum(bool(row["raw_returned_text_mismatch"]) for row in model_boundaries),
                "unique_global_repaired_offsets": sum(item["status"] == "repaired" for item in repair_audit),
                "local_overlap_repaired_offsets": sum(item["status"] == "repaired" for item in local_repair_audit),
                "overlap_tp_relations": len(model_relations),
                "overlap_rescued_relations": sum(bool(row["rescued_beyond_exact"]) for row in model_relations),
            }
        )

    pattern_rows = []
    for model in MODELS:
        subset = [row for row in boundary_output if row["model"] == model]
        for dimension in ("label", "boundary_side", "boundary_pattern", "raw_returned_text_mismatch"):
            counts = Counter(str(row[dimension]) for row in subset)
            for value, count in sorted(counts.items()):
                pattern_rows.append(
                    {
                        "model": model,
                        "dimension": dimension,
                        "value": value,
                        "count": count,
                        "percent_of_rescued_entities": count / len(subset) if subset else 0,
                    }
                )
    relation_pattern_rows = []
    for model in MODELS:
        subset = [row for row in relation_output if row["model"] == model and row["rescued_beyond_exact"]]
        for dimension in ("predicate", "endpoint_pattern"):
            counts = Counter(str(row[dimension]) for row in subset)
            for value, count in sorted(counts.items()):
                relation_pattern_rows.append(
                    {
                        "model": model,
                        "dimension": dimension,
                        "value": value,
                        "count": count,
                        "percent_of_rescued_relations": count / len(subset) if subset else 0,
                    }
                )

    repaired_pattern_rows = []
    repaired_relation_pattern_rows = []
    for model in MODELS:
        subset = [row for row in repaired_boundary_output if row["model"] == model]
        for dimension in ("label", "boundary_side", "boundary_pattern"):
            for value, count in sorted(Counter(str(row[dimension]) for row in subset).items()):
                repaired_pattern_rows.append(
                    {
                        "model": model,
                        "dimension": dimension,
                        "value": value,
                        "count": count,
                        "percent_of_residual_overlap_rescues": count / len(subset) if subset else 0,
                    }
                )
        rel_subset = [row for row in repaired_relation_output if row["model"] == model and row["rescued_beyond_exact"]]
        for dimension in ("predicate", "endpoint_pattern"):
            for value, count in sorted(Counter(str(row[dimension]) for row in rel_subset).items()):
                repaired_relation_pattern_rows.append(
                    {
                        "model": model,
                        "dimension": dimension,
                        "value": value,
                        "count": count,
                        "percent_of_residual_overlap_rescues": count / len(rel_subset) if rel_subset else 0,
                    }
                )

    write_csv(OUT / "metric_recalculation.csv", metric_output)
    write_csv(OUT / "entity_boundary_pairs.csv", boundary_output)
    write_csv(OUT / "entity_boundary_patterns.csv", pattern_rows)
    write_csv(OUT / "raw_text_mismatches.csv", raw_output)
    write_csv(OUT / "offset_repair_audit.csv", repair_output)
    write_csv(OUT / "relation_overlap_tp_details.csv", relation_output)
    write_csv(OUT / "relation_rescue_patterns.csv", relation_pattern_rows)
    write_csv(OUT / "entity_boundary_pairs_after_local_repair.csv", repaired_boundary_output)
    write_csv(OUT / "entity_boundary_patterns_after_local_repair.csv", repaired_pattern_rows)
    write_csv(OUT / "relation_overlap_tp_after_local_repair.csv", repaired_relation_output)
    write_csv(OUT / "relation_rescue_patterns_after_local_repair.csv", repaired_relation_pattern_rows)
    write_csv(OUT / "local_repair_exact_tp_effects.csv", repair_effect_output)
    write_csv(OUT / "local_repair_exact_tp_effect_details.csv", repair_effect_details)
    write_csv(OUT / "model_summary.csv", summaries)
    write_csv(OUT / "gold_terminal_punctuation_audit.csv", gold_punctuation_audit)
    checks = []

    def add_check(name: str, observed, expected) -> None:
        passed = observed == expected if not isinstance(expected, float) else abs(float(observed) - expected) < 1e-12
        checks.append({"check": name, "observed": observed, "expected": expected, "passed": passed})

    add_check("heldout_document_count", len(gold_rows), 38)
    add_check("heldout_entity_count", sum(len(row["entities"]) for row in gold_rows), 1586)
    add_check("deduplicated_heldout_relation_count", sum(len(row["relations"]) for row in gold_rows), 1167)
    add_check("reference_terminal_punctuation_spans", len(gold_punctuation_audit), 7)
    raw_analysis = list(csv.DictReader((ROOT / "llm_preliminary/analysis/raw_as_returned_heldout_analysis_v1/aggregate_metrics.csv").open(encoding="utf-8-sig")))
    model_rows = {row["model"]: row for row in summaries}
    for model, run_root in MODELS.items():
        metrics = [row for row in metric_output if row["model"] == model and row["label"] == "ALL"]
        lookup = {(row["variant"], row["target"], row["matching"]): row for row in metrics}
        validation = json.loads((run_root / CONDITION / "entity_validation.json").read_text(encoding="utf-8"))
        validation_mismatches = sum(
            int((item.get("diagnostics") or {}).get("text_mismatch_retained_by_offsets") or 0)
            for item in validation.values()
        )
        add_check(f"{model}:raw_mismatch_reconciles_to_run_validation", model_rows[model]["raw_text_mismatches"], validation_mismatches)
        for target, metric_name in (("entity", "entity_exact"), ("relation", "relation_exact")):
            official = next(row for row in raw_analysis if row["model"] == model and row["condition"] == "Gstar" and row["metric"] == metric_name)
            reproduced = lookup[("as_returned_parser_view", target, "exact")]
            for field in ("tp", "fp", "fn"):
                add_check(f"{model}:{target}:official_{field}_reproduced", int(reproduced[field]), int(official[field]))
        for target in ("entity", "relation"):
            exact = lookup[("as_returned_parser_view", target, "exact")]
            overlap = lookup[("as_returned_parser_view", target, "overlap")]
            repaired_overlap = lookup[("local_raw_text_offset_repair", target, "overlap")]
            rescued = model_rows[model]["overlap_rescued_entities" if target == "entity" else "overlap_rescued_relations"]
            add_check(f"{model}:{target}:overlap_rescue_equals_tp_delta", rescued, int(overlap["tp"]) - int(exact["tp"]))
            for field in ("tp", "fp", "fn"):
                add_check(f"{model}:{target}:local_repair_preserves_overlap_{field}", int(repaired_overlap[field]), int(overlap[field]))
    if not all(item["passed"] for item in checks):
        raise AssertionError([item for item in checks if not item["passed"]])
    (OUT / "validation_checks.json").write_text(json.dumps(checks, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (OUT / "summary.json").write_text(
        json.dumps(
            {
                "model_summary": summaries,
                "entity_boundary_patterns": pattern_rows,
                "relation_rescue_patterns": relation_pattern_rows,
            },
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    print(json.dumps(summaries, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

"""Comprehensive no-API analysis of the completed IU X-Ray guideline study.

The script treats the original S1-vs-S0 held-out contrast as prespecified and
the later G0 arm as post-hoc exploratory.  It writes machine-readable tables,
deterministic error inventories, bootstrap intervals, rule inventories, and a
compact report without making any provider calls. Held-out scoring uses the
materialized prediction-only normalized view; immutable API responses and the
as-returned parsed analysis remain separate provenance artifacts.
"""

