    "relation_exact": ("relations", "end_to_end_strict"),
    "relation_overlap": ("relations", "end_to_end_overlap"),
    "relation_matched_endpoint_exact": ("relations", "matched_endpoint_strict"),
    "relation_matched_endpoint_overlap": ("relations", "matched_endpoint_overlap"),
}


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def dump(path: Path, value) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def write_csv(path: Path, rows: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if not rows:
        path.write_text("", encoding="utf-8")
        return
    fields = []
    for row in rows:
        for key in row:
            if key not in fields:
                fields.append(key)
    with path.open("w", encoding="utf-8-sig", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, extrasaction="ignore")
        writer.writeheader()
        writer.writerows(rows)


def load_jsonl(path: Path) -> list[dict]:
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def deduplicate_reference_relations(rows: list[dict]) -> tuple[list[dict], list[dict]]:
    """Return an analysis view with exact duplicate directed triples removed.

    The immutable source snapshot is preserved.  This prevents a duplicate
    reference record from counting twice when provider outputs are required to
    contain unique ordered triples.
    """
    cleaned = []
    audit = []
    for source_row in rows:
        row = {**source_row, "relations": []}
        first_by_key = {}
        for relation in source_row["relations"]:
            key = (relation["subj"], relation["pred"], relation["obj"])
            if key in first_by_key:
                audit.append(
                    {
                        "doc_id": source_row["doc_id"],
                        "split": source_row["split"],
                        "retained_relation_id": first_by_key[key]["id"],
                        "removed_duplicate_relation_id": relation["id"],
                        "subj": relation["subj"],
                        "pred": relation["pred"],
                        "obj": relation["obj"],
                        "reason": "exact duplicate directed triple",
                    }
                )
                continue
            first_by_key[key] = relation
            row["relations"].append(relation)
        cleaned.append(row)
    return cleaned, audit


