def score_dict(counts: Counter | dict) -> dict:
    counts = Counter(counts)
    tp, fp, fn = counts["tp"], counts["fp"], counts["fn"]
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * tp / (2 * tp + fp + fn) if 2 * tp + fp + fn else 0.0
    return {"tp": tp, "fp": fp, "fn": fn, "precision": precision, "recall": recall, "f1": f1}


def metric_counts(document_result: dict, metric: str, label: str | None = None) -> Counter:
    family, method = METRIC_KEYS[metric]
    values = document_result[family][method]
    return Counter(values["overall"] if label is None else values["per_label"][label])


def percentile(values: list[float], q: float) -> float:
    ordered = sorted(values)
    position = (len(ordered) - 1) * q
    lower = int(math.floor(position))
    upper = min(lower + 1, len(ordered) - 1)
    fraction = position - lower
    return ordered[lower] * (1 - fraction) + ordered[upper] * fraction


def paired_bootstrap(
    first: dict[str, dict],
    second: dict[str, dict],
    metric: str,
    label: str | None,
    seed: int,
) -> dict:
    ids = sorted(first)
    if ids != sorted(second):
        raise ValueError("Paired bootstrap document IDs differ")
    observed_first = sum((metric_counts(first[doc], metric, label) for doc in ids), Counter())
    observed_second = sum((metric_counts(second[doc], metric, label) for doc in ids), Counter())
    observed = score_dict(observed_first)["f1"] - score_dict(observed_second)["f1"]
    rng = random.Random(seed)
    differences = []
    for _ in range(BOOTSTRAP_REPLICATES):
        sampled = [ids[rng.randrange(len(ids))] for _ in ids]
        a = sum((metric_counts(first[doc], metric, label) for doc in sampled), Counter())
        b = sum((metric_counts(second[doc], metric, label) for doc in sampled), Counter())
        differences.append(score_dict(a)["f1"] - score_dict(b)["f1"])
    return {
        "difference": observed,
        "ci95_lower": percentile(differences, 0.025),
        "ci95_upper": percentile(differences, 0.975),
        "replicates": BOOTSTRAP_REPLICATES,
        "seed": seed,
        "unit": "report",
        "interval": "percentile 95%",
    }


def section_intervals(text: str) -> list[tuple[int, int]]:
    headers = list(re.finditer(r"(?m)^(IMAGE|INDICATION|COMPARISON|FINDINGS|IMPRESSION):\s*", text))
    intervals = []
    for index, match in enumerate(headers):
        if match.group(1) not in {"FINDINGS", "IMPRESSION"}:
            continue
        end = headers[index + 1].start() if index + 1 < len(headers) else len(text)
        intervals.append((match.end(), end))
    return intervals


def is_in_intervals(start: int, end: int, intervals: list[tuple[int, int]]) -> bool:
    return any(left <= start < end <= right for left, right in intervals)


def validation_file_for(root: Path, cid: str, kind: str) -> Path:
    return root / cid / ("entity_validation.json" if kind == "entity" else "relation_validation.json")


def compliance(config: dict, condition: str, relation_predictions: list[dict]) -> dict:
    cid = CONDITIONS[condition][0]
    root = config["g0"] if condition == "G0" else config["final"]
    totals = Counter()
    for kind in ("entity", "relation"):
        path = validation_file_for(root, cid, kind)
        data = json.loads(path.read_text(encoding="utf-8"))
        for audit in data.values():
            totals[f"{kind}_proposed"] += int(audit.get("proposed") or 0)
            totals[f"{kind}_retained"] += int(audit.get("retained") or 0)
            totals[f"{kind}_dropped"] += int(audit.get("dropped") or 0)
            for key, value in (audit.get("diagnostics") or {}).items():
                totals[f"{kind}_{key}"] += int(value or 0)
    outside_entities = 0
    outside_relations = 0
    for row in relation_predictions:
        intervals = section_intervals(row["text"])
        outside_ids = {
            entity["id"]
            for entity in row["entities"]
            if not is_in_intervals(entity["start"], entity["end"], intervals)
        }
        outside_entities += len(outside_ids)
        outside_relations += sum(
            relation["subj"] in outside_ids or relation["obj"] in outside_ids
            for relation in row["relations"]
        )
    totals["retained_entities_outside_findings_impression"] = outside_entities
    totals["retained_relations_touching_outside_entity"] = outside_relations
    return dict(totals)


def endpoint_availability(gold: list[dict], predictions: list[dict], mode: str) -> dict:
    by_pred = {str(row["doc_id"]): row for row in predictions}
    available = 0
    total = 0
    per_label = Counter()
    per_label_total = Counter()
    for gold_row in gold:
        pred_row = by_pred[str(gold_row["doc_id"])]
        mapping = evaluator.entity_mapping(gold_row["entities"], pred_row["entities"], mode)
        mapped_gold = set(mapping.values())
        gold_index = {entity["id"]: index for index, entity in enumerate(gold_row["entities"])}
        for relation in gold_row["relations"]:
            total += 1
            per_label_total[relation["pred"]] += 1
            if gold_index[relation["subj"]] in mapped_gold and gold_index[relation["obj"]] in mapped_gold:
                available += 1
                per_label[relation["pred"]] += 1
    return {
        "available_gold_relations": available,
        "total_gold_relations": total,
        "ceiling_recall": available / total if total else 0.0,
        "per_label": {
            label: {
                "available": per_label[label],
                "total": per_label_total[label],
                "ceiling_recall": per_label[label] / per_label_total[label]
                if per_label_total[label]
                else 0.0,
            }
            for label in two.RELATION_LABELS
        },
    }


def compact_relation_taxonomy(gold: list[dict], predictions: list[dict]) -> tuple[dict, dict]:
    strata = causal.causal_census(gold, predictions)
    categories = Counter()
    examples = defaultdict(list)
    for stratum, items in strata.items():
        category = stratum.split("|", 1)[0]
        categories[category] += len(items)
        for item in items[:2]:
            examples[category].append(
                {
                    "stratum": stratum,
                    "doc_id": item.get("doc_id"),
                    "gold": item.get("gold"),
                    "prediction": item.get("prediction"),
                }
            )
    exact_tp = 0
    by = {str(row["doc_id"]): row for row in predictions}
    for row in gold:
        exact_tp += held.doc_counts(row, by[str(row["doc_id"])], "relation")[0]
    categories["EXACT_TP"] = exact_tp
    return dict(categories), dict(examples)


def compact_entity_taxonomy(gold: list[dict], predictions: list[dict]) -> tuple[dict, dict]:
    by = {str(row["doc_id"]): row for row in predictions}
    totals = Counter()
    examples = defaultdict(list)
    for gold_row in gold:
        events, counts = pair_entities(gold_row["entities"], by[str(gold_row["doc_id"])]["entities"])
        totals.update(counts)
        for event in events:
            if len(examples[event["category"]]) < 2:
                examples[event["category"]].append({"doc_id": gold_row["doc_id"], **event})
    return dict(totals), dict(examples)


