RULE_CATEGORIES = {
    "section_scope": r"section|findings|impression|indication|comparison|image header",
    "span_boundary": r"span|boundary|offset|token|punctuation|hyphen|measurement|unit|word-level",
    "exclusion": r"exclude|ignore|do not annotate|never annotate|redact|pronoun|patient|exam|method",
    "entity_type": r"ANAT|OBS-DP|OBS-DA|OBS-U|anatom|observation|device|fluid|airspace",
    "certainty": r"uncertain|uncertainty|absent|negat|definitely|possible|suggest|cue",
    "entity_composition": r"coordination|conjunct|compound|modifier|head|multi-word|separate entit",
    "relation_direction": r"direction|subject|object|ordered|source|target",
    "relation_predicate": r"Modify|LocatedAt|SuggestiveOf|predicate|relation type",
    "relation_attachment": r"attach|attachment|nearest|site|location|endpoint|immutable entit",
}


def rule_text(rule: dict) -> str:
    parts = [rule.get("instruction", ""), rule.get("applies_when", "")]
    parts.extend(str(item) for item in rule.get("exceptions", []))
    parts.extend(str(item) for item in rule.get("examples", []))
    return " ".join(parts)


def rule_categories(rule: dict) -> list[str]:
    text = rule_text(rule)
    return [name for name, pattern in RULE_CATEGORIES.items() if re.search(pattern, text, re.I)] or ["other"]


def tokens(text: str) -> set[str]:
    stop = {"the", "a", "an", "and", "or", "of", "to", "in", "is", "are", "when", "for", "with", "as", "only"}
    return {word for word in re.findall(r"[a-z0-9-]+", text.lower()) if len(word) > 2 and word not in stop}


def jaccard(first: str, second: str) -> float:
    a, b = tokens(first), tokens(second)
    return len(a & b) / len(a | b) if a | b else 0.0


def active_rules(guideline: dict) -> list[dict]:
    return [rule for rule in guideline.get("principles", []) if rule.get("status", "active") == "active"]


