def rule_inventory(model: str, config: dict) -> tuple[list[dict], dict]:
    artifacts = guideline_artifacts(config)
    rows = []
    for stage, guideline in artifacts.items():
        phase, version = stage.split("_", 1)
        for rule in active_rules(guideline):
            text = rule_text(rule)
            rows.append(
                {
                    "model": model,
                    "phase": phase,
                    "version": version,
                    "rule_id": rule.get("rule_id"),
                    "priority": rule.get("priority"),
                    "instruction": rule.get("instruction", ""),
                    "categories": ";".join(rule_categories(rule)),
                    "words": len(re.findall(r"\S+", text)),
                    "characters": len(text),
                    "exceptions": len(rule.get("exceptions", [])),
                    "examples": len(rule.get("examples", [])),
                }
            )
    trajectory = {}
    entity_state = json.loads((config["development"] / "entity/state.json").read_text(encoding="utf-8"))
    relation_state = json.loads((config["relation_causal"] / "state.json").read_text(encoding="utf-8"))
    for phase, state in (("entity", entity_state), ("relation", relation_state)):
        history = state["history"]
        trajectory[phase] = {
            "candidates": len(history),
            "accepted": sum(bool(item.get("accepted")) for item in history),
            "rejected": sum(not bool(item.get("accepted")) for item in history),
            "initial_f1": history[0]["before"]["f1"] if history else state["current_score"]["f1"],
            "final_f1": state["current_score"]["f1"],
            "accepted_iterations": [item["iteration"] for item in history if item.get("accepted")],
        }
    return rows, trajectory


def cross_model_rule_comparison(inventory_rows: list[dict]) -> list[dict]:
    output = []
    for phase in ("entity", "relation"):
        for version in ("G0", "Gstar"):
            deep = [row for row in inventory_rows if row["model"] == "DeepSeek V4 Pro" and row["phase"] == phase and row["version"] == version]
            gpt = [row for row in inventory_rows if row["model"] == "GPT-5.6 Terra" and row["phase"] == phase and row["version"] == version]
            for row in deep:
                matches = sorted(
                    ((jaccard(row["instruction"], other["instruction"]), other) for other in gpt),
                    key=lambda item: (-item[0], str(item[1]["rule_id"])),
                )
                score, best = matches[0] if matches else (0.0, {"rule_id": None, "instruction": "", "categories": ""})
                output.append(
                    {
                        "phase": phase,
                        "version": version,
                        "deepseek_rule_id": row["rule_id"],
                        "gpt_best_rule_id": best["rule_id"],
                        "lexical_jaccard": score,
                        "shared_deterministic_categories": ";".join(
                            sorted(set(row["categories"].split(";")) & set(best["categories"].split(";")))
                        ),
                        "qualification": "lexical/category diagnostic, not semantic equivalence",
                    }
                )
    return output


def v2_lexical_coverage(model: str, config: dict) -> list[dict]:
    inventory_path = ROOT / "study_resources/emnlp_guideline_study/guideline_analysis/guideline_change_inventory.json"
    v2_rules = json.loads(inventory_path.read_text(encoding="utf-8"))
    artifacts = guideline_artifacts(config)
    entity_rules = active_rules(artifacts["entity_Gstar"])
    relation_rules = active_rules(artifacts["relation_Gstar"])
    rows = []
    for v2 in v2_rules:
        candidates = relation_rules if str(v2.get("domain", "")).startswith("relation") or v2.get("domain") == "modifier_typing" else entity_rules
        ranked = sorted(
            ((jaccard(v2["v2"], rule_text(rule)), rule) for rule in candidates),
            key=lambda item: (-item[0], str(item[1].get("rule_id"))),
        )
        similarity, best = ranked[0] if ranked else (0.0, {})
        rows.append(
            {
                "model": model,
                "v2_rule_id": v2["rule_id"],
                "v2_domain": v2["domain"],
                "best_gstar_rule_id": best.get("rule_id"),
                "lexical_jaccard": similarity,
                "qualification": "post-hoc surface-form diagnostic; v2 postdates the second annotation stage",
            }
        )
    return rows


def provider_usage_records(root: Path, provider: str, exclude_ids: set[str] | None = None) -> dict:
    exclude_ids = exclude_ids or set()
    by_id = {}
    for path in root.rglob("*.json"):
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(value, dict) or not value.get("id") or not value.get("usage") or not value.get("choices"):
            continue
        response_id = str(value["id"])
        if response_id not in exclude_ids:
            by_id[response_id] = value
    totals = Counter()
    cost = 0.0
    returned_models = Counter()
    for value in by_id.values():
        usage = value.get("usage") or {}
        for key in ("prompt_tokens", "completion_tokens", "total_tokens", "prompt_cache_hit_tokens", "prompt_cache_miss_tokens"):
            totals[key] += int(usage.get(key) or 0)
        details = usage.get("completion_tokens_details") or {}
        totals["reasoning_tokens"] += int(details.get("reasoning_tokens") or 0)
        prompt_details = usage.get("prompt_tokens_details") or {}
        totals["cached_input_tokens"] += int(prompt_details.get("cached_tokens") or 0)
        returned_models[str(value.get("model"))] += 1
        cost += held.token_cost(provider, usage)["computed_usd"]
    return {
        "unique_provider_responses": len(by_id),
        "tokens": dict(totals),
        "computed_token_cost_usd": cost,
        "returned_models": dict(returned_models),
        "response_ids": sorted(by_id),
        "qualification": "Reconstructed from unique saved provider response IDs; provider invoices remain authoritative.",
    }


def resource_accounting(model: str, config: dict) -> list[dict]:
    rows = []
    development_usage = provider_usage_records(config["development"], config["provider"])
    # The causal fork retains its seed response in both directories. Exclude all
    # IDs already counted in the base run so the reconstructed total is unique.
    causal_usage = provider_usage_records(
        config["relation_causal"], config["provider"], set(development_usage["response_ids"])
    )
    for stage, usage in (("development_base", development_usage), ("development_relation_error_fork", causal_usage)):
        rows.append(
            {
                "model": model,
                "stage": stage,
                "provider_responses": usage["unique_provider_responses"],
                "prompt_tokens": usage["tokens"].get("prompt_tokens", 0),
                "completion_tokens": usage["tokens"].get("completion_tokens", 0),
                "reasoning_tokens": usage["tokens"].get("reasoning_tokens", 0),
                "total_tokens": usage["tokens"].get("total_tokens", 0),
                "computed_usd": usage["computed_token_cost_usd"],
                "wall_seconds": None,
                "accounting_source": "unique saved raw provider responses",
            }
        )
    for stage, root in (("heldout_original", config["final"]), ("heldout_G0_posthoc", config["g0"])):
        summary = json.loads((root / "resource_summary.json").read_text(encoding="utf-8"))
        ledger = summary["ledger"]
        computed_usd = ledger["computed_token_cost_usd"]
        accounting_source = "append-only call ledger including billed failed responses"
        # DeepSeek changed its public prices on 2026-08-16.  The original
        # held-out run predates that change, whereas the G0 addendum does not.
        # Its contemporaneous resource summary was produced by an older runner
        # and therefore retained the superseded flat rate.  Reconstruct the
        # post-change cost from the recorded aggregate usage and request start
        # time.  Provider invoices remain authoritative.
        if config["provider"] == "deepseek" and stage == "heldout_G0_posthoc":
            computed_usd = held.token_cost(
                config["provider"], ledger["tokens"], summary["run_started_utc"]
            )["computed_usd"]
            accounting_source += "; date-aware price reconstruction from recorded start time"
        rows.append(
            {
                "model": model,
                "stage": stage,
                "provider_responses": ledger["provider_completed_responses"] + ledger.get("billed_failed_responses", 0),
                "prompt_tokens": ledger["tokens"].get("prompt_tokens", 0),
                "completion_tokens": ledger["tokens"].get("completion_tokens", 0),
                "reasoning_tokens": ledger["tokens"].get("reasoning_tokens", 0),
                "total_tokens": ledger["tokens"].get("total_tokens", 0),
                "computed_usd": computed_usd,
                "wall_seconds": summary["total_wall_seconds"],
                "accounting_source": accounting_source,
            }
        )
    return rows


