"""Build deterministic entity and relation error taxonomies for the IU X-Ray study."""

from __future__ import annotations

import json
from collections import Counter, defaultdict
from pathlib import Path

from evaluate_radgraph_ie import entity_mapping, iou


ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / "study_resources/emnlp_guideline_study"
DATA = BASE / "data/interim/iu_xray"
GOLD = DATA / "human_gold_with_relations.jsonl"
PRED = DATA / "radgraph_pred_with_relations.jsonl"
ORACLE = BASE / "oracle/oracle_relations_50.jsonl"
OUT_DIR = BASE / "evaluation"
DETAILS = OUT_DIR / "error_taxonomy.jsonl"
SUMMARY_JSON = OUT_DIR / "error_taxonomy_summary.json"
SUMMARY_MD = OUT_DIR / "error_taxonomy_summary.md"
EXAMPLES_MD = OUT_DIR / "error_taxonomy_examples.md"


def load(path: Path) -> dict[str, dict]:
    return {str(x["doc_id"]): x for x in map(json.loads, path.read_text(encoding="utf-8").splitlines())}


def entity_ref(entity: dict) -> dict:
    return {key: entity[key] for key in ("id", "start", "end", "label", "text") if key in entity}


def relation_ref(relation: dict, entities: dict[str, dict]) -> dict:
    return {
        "id": relation["id"],
        "pred": relation["pred"],
        "subj": entity_ref(entities[relation["subj"]]),
        "obj": entity_ref(entities[relation["obj"]]),
    }


def pair_entities(gold_entities: list[dict], pred_entities: list[dict]) -> tuple[list[dict], Counter]:
    strict = entity_mapping(gold_entities, pred_entities, "strict")
    remaining_gold = set(range(len(gold_entities))) - set(strict.values())
    remaining_pred = set(range(len(pred_entities))) - set(strict)
    events, counts = [], Counter()

    candidates = []
    for pi in remaining_pred:
        for gi in remaining_gold:
            p, g = pred_entities[pi], gold_entities[gi]
            same_span = (p["start"], p["end"]) == (g["start"], g["end"])
            has_overlap = max(p["start"], g["start"]) < min(p["end"], g["end"])
            if same_span and p["label"] != g["label"]:
                category, priority = "label_confusion", 0
            elif has_overlap and p["label"] == g["label"]:
                category, priority = "boundary_mismatch", 1
            elif has_overlap:
                category, priority = "boundary_and_label_mismatch", 2
            else:
                continue
            candidates.append((priority, -iou(p, g), pi, gi, category))

    for _priority, _negative_iou, pi, gi, category in sorted(candidates):
        if pi not in remaining_pred or gi not in remaining_gold:
            continue
        p, g = pred_entities[pi], gold_entities[gi]
        subtype = None
        if "label" in category:
            if g["label"].startswith("OBS-") and p["label"].startswith("OBS-"):
                subtype = "certainty_confusion"
            elif {g["label"], p["label"]} & {"ANAT"}:
                subtype = "anatomy_observation_confusion"
            else:
                subtype = "other_label_confusion"
        events.append({"category": category, "subtype": subtype, "gold": entity_ref(g), "prediction": entity_ref(p)})
        counts[category] += 1
        if subtype:
            counts[f"subtype::{subtype}"] += 1
        remaining_pred.remove(pi)
        remaining_gold.remove(gi)

    for gi in sorted(remaining_gold):
        events.append({"category": "missed_entity", "gold": entity_ref(gold_entities[gi])})
        counts["missed_entity"] += 1
    for pi in sorted(remaining_pred):
        events.append({"category": "spurious_entity", "prediction": entity_ref(pred_entities[pi])})
        counts["spurious_entity"] += 1
    counts["strict_tp"] = len(strict)
    counts["strict_fn_units"] = len(gold_entities) - len(strict)
    counts["strict_fp_units"] = len(pred_entities) - len(strict)
    return events, counts


def relation_tuple(relation: dict) -> tuple[str, str, str]:
    return relation["subj"], relation["pred"], relation["obj"]


def pair_oracle_relations(gold_doc: dict, oracle_doc: dict) -> tuple[list[dict], Counter]:
    gold_entities = {x["id"]: x for x in gold_doc["entities"]}
    oracle_entities = {x["id"]: x for x in oracle_doc["entities"]}
    remaining_gold = {x["id"]: x for x in gold_doc["relations"]}
    remaining_pred = {x["id"]: x for x in oracle_doc["relations"]}
    exact = 0
    for gold_id in list(remaining_gold):
        key = relation_tuple(remaining_gold[gold_id])
        match = next((pred_id for pred_id, relation in remaining_pred.items() if relation_tuple(relation) == key), None)
        if match is not None:
            exact += 1
            del remaining_gold[gold_id]
            del remaining_pred[match]
    events, counts = [], Counter(oracle_tp=exact)

    rules = [
        ("reversed_direction", lambda g, p: g[0] == p[2] and g[2] == p[0] and g[1] == p[1]),
        ("wrong_relation_type", lambda g, p: g[0] == p[0] and g[2] == p[2] and g[1] != p[1]),
        ("wrong_object_attachment", lambda g, p: g[0] == p[0] and g[1] == p[1] and g[2] != p[2]),
        ("wrong_subject_attachment", lambda g, p: g[2] == p[2] and g[1] == p[1] and g[0] != p[0]),
    ]
    for category, rule in rules:
        candidates = sorted(
            (gold_id, pred_id)
            for gold_id, gold_relation in remaining_gold.items()
            for pred_id, pred_relation in remaining_pred.items()
            if rule(relation_tuple(gold_relation), relation_tuple(pred_relation))
        )
        for gold_id, pred_id in candidates:
            if gold_id not in remaining_gold or pred_id not in remaining_pred:
                continue
            events.append(
                {
                    "category": category,
                    "gold": relation_ref(remaining_gold[gold_id], gold_entities),
                    "prediction": relation_ref(remaining_pred[pred_id], oracle_entities),
                }
            )
            counts[category] += 1
            del remaining_gold[gold_id]
            del remaining_pred[pred_id]

    # Only pair residual errors as compound when the pairing is unique in both directions.
    residual_candidates = defaultdict(list)
    reverse_candidates = defaultdict(list)
    for gold_id, gold_relation in remaining_gold.items():
        g = relation_tuple(gold_relation)
        for pred_id, pred_relation in remaining_pred.items():
            p = relation_tuple(pred_relation)
            if g[0] == p[0] or g[2] == p[2]:
                residual_candidates[gold_id].append(pred_id)
                reverse_candidates[pred_id].append(gold_id)
    for gold_id in sorted(residual_candidates):
        options = residual_candidates[gold_id]
        if len(options) != 1:
            continue
        pred_id = options[0]
        if gold_id not in remaining_gold or pred_id not in remaining_pred or len(reverse_candidates[pred_id]) != 1:
            continue
        events.append(
            {
                "category": "compound_relation_mismatch",
                "gold": relation_ref(remaining_gold[gold_id], gold_entities),
                "prediction": relation_ref(remaining_pred[pred_id], oracle_entities),
            }
        )
        counts["compound_relation_mismatch"] += 1
        del remaining_gold[gold_id]
        del remaining_pred[pred_id]

    for relation_id in sorted(remaining_gold):
        events.append({"category": "missing_relation", "gold": relation_ref(remaining_gold[relation_id], gold_entities)})
        counts["missing_relation"] += 1
    for relation_id in sorted(remaining_pred):
        events.append({"category": "spurious_relation", "prediction": relation_ref(remaining_pred[relation_id], oracle_entities)})
        counts["spurious_relation"] += 1
    counts["oracle_fn_units"] = len(gold_doc["relations"]) - exact
    counts["oracle_fp_units"] = len(oracle_doc["relations"]) - exact
    return events, counts


def relation_recovery(gold_doc: dict, pred_doc: dict, oracle_doc: dict) -> Counter:
    mapping = entity_mapping(gold_doc["entities"], pred_doc["entities"], "overlap")
    pred_index = {x["id"]: i for i, x in enumerate(pred_doc["entities"])}
    e2e = Counter()
    for relation in pred_doc["relations"]:
        subj, obj = pred_index[relation["subj"]], pred_index[relation["obj"]]
        if subj in mapping and obj in mapping:
            e2e[(gold_doc["entities"][mapping[subj]]["id"], relation["pred"], gold_doc["entities"][mapping[obj]]["id"])] += 1
    reference = Counter(relation_tuple(x) for x in gold_doc["relations"])
    oracle = Counter(relation_tuple(x) for x in oracle_doc["relations"])
    counts = Counter()
    # Allocate duplicate relation triples as multisets. The former set-membership
    # implementation allowed one prediction to mark multiple duplicate reference
    # relations correct and therefore disagreed with micro true-positive totals.
    for key, reference_n in reference.items():
        e2e_n = min(reference_n, e2e[key])
        oracle_n = min(reference_n, oracle[key])
        both = min(e2e_n, oracle_n)
        counts["correct_both"] += both
        counts["end_to_end_only"] += e2e_n - both
        counts["oracle_only"] += oracle_n - both
        counts["incorrect_both"] += reference_n - max(e2e_n, oracle_n)
    return counts


def markdown_table(rows: list[tuple[str, int]], total: int) -> str:
    lines = ["| Category | Count | Percent |", "|---|---:|---:|"]
    lines.extend(f"| {name} | {count} | {100 * count / total:.1f}% |" for name, count in rows)
    return "\n".join(lines)


def describe(item: dict | None) -> str:
    if not item:
        return "-"
    if "subj" in item and "obj" in item:
        return f"{item['subj']['text']} -{item['pred']}-> {item['obj']['text']}"
    return f"{item.get('text', '')} [{item.get('label', '')}] ({item.get('start', '')}:{item.get('end', '')})"


def main() -> None:
    gold, pred, oracle = load(GOLD), load(PRED), load(ORACLE)
    if set(gold) != set(pred) or set(gold) != set(oracle):
        raise ValueError("Document IDs differ across gold, end-to-end, and oracle files")
    details = []
    entity_total, relation_total, recovery_total = Counter(), Counter(), Counter()
    examples: dict[str, list[dict]] = defaultdict(list)
    for doc_id in gold:
        entity_events, entity_counts = pair_entities(gold[doc_id]["entities"], pred[doc_id]["entities"])
        relation_events, relation_counts = pair_oracle_relations(gold[doc_id], oracle[doc_id])
        recovery = relation_recovery(gold[doc_id], pred[doc_id], oracle[doc_id])
        entity_total.update(entity_counts)
        relation_total.update(relation_counts)
        recovery_total.update(recovery)
        for event in entity_events + relation_events:
            event["doc_id"] = doc_id
            if len(examples[event["category"]]) < 3:
                examples[event["category"]].append(event)
        details.append(
            {
                "doc_id": doc_id,
                "split": gold[doc_id]["split"],
                "entity_errors": entity_events,
                "oracle_relation_errors": relation_events,
                "relation_recovery": dict(recovery),
            }
        )

    summary = {
        "definitions": {
            "entity_taxonomy": "Deterministic one-to-one pairing after strict matches: same-span label confusion, overlapping boundary mismatch, then residual missed/spurious entities.",
            "oracle_relation_taxonomy": "Deterministic correction taxonomy after exact relation matches: reverse, type, object attachment, subject attachment, mutually unique compound mismatch, then missing/spurious.",
            "relation_recovery": "Multiset allocation of each human reference relation under overlap-aligned end-to-end predictions versus the reference-entity rerun.",
        },
        "entity": dict(sorted(entity_total.items())),
        "oracle_relation": dict(sorted(relation_total.items())),
        "relation_recovery": dict(sorted(recovery_total.items())),
        "examples": dict(examples),
    }
    DETAILS.write_text("".join(json.dumps(x, ensure_ascii=False, separators=(",", ":")) + "\n" for x in details), encoding="utf-8")
    SUMMARY_JSON.write_text(json.dumps(summary, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    entity_rows = [(key, entity_total[key]) for key in ("label_confusion", "boundary_mismatch", "boundary_and_label_mismatch", "missed_entity", "spurious_entity")]
    relation_rows = [(key, relation_total[key]) for key in ("reversed_direction", "wrong_relation_type", "wrong_object_attachment", "wrong_subject_attachment", "compound_relation_mismatch", "missing_relation", "spurious_relation")]
    recovery_rows = [(key, recovery_total[key]) for key in ("correct_both", "oracle_only", "end_to_end_only", "incorrect_both")]
    md = f"""# Automated Error Taxonomy Summary

## Entity errors

Counts describe deterministic error events after removing {entity_total['strict_tp']} strict true positives. Percentages use {entity_total['strict_fn_units'] + entity_total['strict_fp_units']} total strict error units (FN + FP); paired mismatch events consume one FN and one FP and therefore should not be summed as if they were error units.

{markdown_table(entity_rows, sum(count for _name, count in entity_rows))}

Certainty-confusion subtype events: {entity_total['subtype::certainty_confusion']}. Anatomy/observation-confusion subtype events: {entity_total['subtype::anatomy_observation_confusion']}.

## Gold-entity oracle relation errors

The oracle has {relation_total['oracle_tp']} exact relation true positives, {relation_total['oracle_fp_units']} FP units, and {relation_total['oracle_fn_units']} FN units. Paired categories represent a single predicted relation paired to a single missing gold relation.

{markdown_table(relation_rows, sum(count for _name, count in relation_rows))}

## End-to-end versus oracle recovery

Each of the 1,454 human relations appears exactly once below.

{markdown_table(recovery_rows, sum(count for _name, count in recovery_rows))}

`oracle_only` relations are recovered when human entities are supplied. `end_to_end_only` relations show that forcing all gold spans can also alter the relation beam and remove some relations that the end-to-end run predicted correctly. `incorrect_both` indicates relation-level difficulty persisting under both settings.

## Interpretation boundary

This taxonomy is structural and reproducible. It does not by itself establish the linguistic or clinical cause of an error. Representative cases should be reviewed before assigning guideline-sensitive explanations.
"""
    SUMMARY_MD.write_text(md, encoding="utf-8")
    example_lines = [
        "# Automatically Selected Error Examples",
        "",
        "These are deterministic first-occurrence examples for audit and manuscript triage. They have not received new human adjudication and should not be presented as clinically interpreted examples without further review.",
        "",
        "| Category | Document | Gold | Prediction |",
        "|---|---:|---|---|",
    ]
    for category in sorted(examples):
        if not examples[category]:
            continue
        event = examples[category][0]
        gold_text = describe(event.get("gold")).replace("|", "\\|")
        pred_text = describe(event.get("prediction")).replace("|", "\\|")
        example_lines.append(f"| {category} | {event['doc_id']} | {gold_text} | {pred_text} |")
    EXAMPLES_MD.write_text("\n".join(example_lines) + "\n", encoding="utf-8")
    print(json.dumps({"entity": summary["entity"], "oracle_relation": summary["oracle_relation"], "relation_recovery": summary["relation_recovery"]}, indent=2))
    print(f"wrote {DETAILS}")
