"""Freeze a balanced nested 4/8/12 direct-demonstration protocol.

Only the 12 pilot gold graphs are inspected. The 38-report evaluation split is
not loaded while constructing the subsets. Three blocks of four are optimized
for feasible label coverage and unweighted relative feature balance.
"""

from __future__ import annotations

import argparse
import hashlib
import itertools
import json
from collections import Counter
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
ENTITY = ("ANAT", "OBS-DP", "OBS-DA", "OBS-U")
RELATION = ("LocatedAt", "Modify", "SuggestiveOf")
FEATURES = ("characters", "entities", "relations", *ENTITY, *RELATION)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--gold",
        type=Path,
        default=ROOT / "study_resources/emnlp_guideline_study/data/interim/iu_xray/human_gold_with_relations.jsonl",
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=ROOT / "llm_preliminary/deepseek_high_fewshot_4_8_12_plan.json",
    )
    return parser.parse_args()


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load_pilot(path: Path) -> list[dict]:
    rows = [
        json.loads(line)
        for line in path.read_text(encoding="utf-8").splitlines()
        if line.strip() and json.loads(line).get("split") == "pilot"
    ]
    if len(rows) != 12:
        raise ValueError(f"Expected 12 pilot reports, found {len(rows)}")
    return sorted(rows, key=lambda row: str(row["doc_id"]))


def vector(row: dict) -> tuple[int, ...]:
    entity_counts = Counter(entity["label"] for entity in row["entities"])
    relation_counts = Counter(relation["pred"] for relation in row["relations"])
    return (
        len(row["text"]),
        len(row["entities"]),
        len(row["relations"]),
        *(entity_counts[label] for label in ENTITY),
        *(relation_counts[label] for label in RELATION),
    )


def partitions_3x4(n: int = 12):
    remaining = tuple(range(n))
    for a_tail in itertools.combinations(remaining[1:], 3):
        a = (remaining[0],) + a_tail
        rest = tuple(index for index in remaining if index not in a)
        for b_tail in itertools.combinations(rest[1:], 3):
            b = (rest[0],) + b_tail
            c = tuple(index for index in rest if index not in b)
            yield a, b, c


def objective(blocks: tuple[tuple[int, ...], ...], vectors: list[tuple[int, ...]]) -> tuple:
    totals = [sum(row[j] for row in vectors) for j in range(len(FEATURES))]
    targets = [total / 3 for total in totals]
    block_totals = [
        [sum(vectors[index][j] for index in block) for j in range(len(FEATURES))]
        for block in blocks
    ]
    feasible = [sum(vector[j] > 0 for vector in vectors) >= 3 for j in range(3, len(FEATURES))]
    missing = sum(
        1
        for totals_for_block in block_totals
        for j, is_feasible in enumerate(feasible, start=3)
        if is_feasible and totals_for_block[j] == 0
    )
    imbalance = sum(
        ((totals_for_block[j] - targets[j]) / max(targets[j], 1.0)) ** 2
        for totals_for_block in block_totals
        for j in range(len(FEATURES))
    )
    canonical = tuple(tuple(sorted(block)) for block in blocks)
    return float(missing), float(imbalance), canonical


def main() -> None:
    args = parse_args()
    rows = load_pilot(args.gold)
    vectors = [vector(row) for row in rows]
    best = min(partitions_3x4(), key=lambda blocks: objective(blocks, vectors))
    names = ("A", "B", "C")
    blocks = {
        name: [str(rows[index]["doc_id"]) for index in block]
        for name, block in zip(names, best)
    }
    totals = {
        name: {
            feature: sum(vectors[index][j] for index in block)
            for j, feature in enumerate(FEATURES)
        }
        for name, block in zip(names, best)
    }
    conditions = {
        "S0_schema_only_current": {"type": "guideline", "demonstration_doc_ids": []},
        "G0_annotation_derived_initial_current": {"type": "guideline", "demonstration_doc_ids": []},
        "Gstar_refined_guideline_current": {"type": "guideline", "demonstration_doc_ids": []},
        "FS4_direct_gold": {"type": "direct_demonstration", "demonstration_doc_ids": blocks["A"]},
        "FS8_direct_gold": {
            "type": "direct_demonstration",
            "demonstration_doc_ids": blocks["A"] + blocks["B"],
        },
        "FS12_direct_gold": {
            "type": "direct_demonstration",
            "demonstration_doc_ids": blocks["A"] + blocks["B"] + blocks["C"],
        },
    }
    payload = {
        "protocol": "deepseek-high-direct-fewshot-4-8-12-v1",
        "status": "PREPARED_NOT_EXECUTED",
        "analysis_role": "post-hoc supplementary baseline on the fixed 38-report evaluation set",
        "model": "deepseek-v4-pro",
        "reasoning_effort": "high",
        "source_gold": str(args.gold.resolve()),
        "source_sha256": sha256(args.gold),
        "subset_construction_split": "pilot",
        "evaluation_gold_loaded_during_subset_construction": False,
        "features": list(FEATURES),
        "objective": {
            "primary": "minimize missing feasible label coverage across three four-report blocks",
            "secondary": "unweighted sum of squared relative deviations from one-third feature totals",
            "tie_break": "lexicographic document index",
        },
        "blocks": blocks,
        "block_feature_totals": totals,
        "optimization_score": {
            "missing_feasible_coverage": objective(best, vectors)[0],
            "relative_squared_imbalance": objective(best, vectors)[1],
        },
        "nested_path": ["A", "B", "C"],
        "conditions": conditions,
        "phase_contract": {
            "entity": "schema plus condition-specific guidance or report-to-gold-entity demonstrations",
            "relation": "schema plus condition-specific guidance or report/gold-entity-to-gold-relation demonstrations; target entities are condition-specific frozen predictions",
            "target_gold_in_prompt": False,
            "demonstration_gold_split": "pilot only",
        },
        "comparisons": {
            "main": "FS12_direct_gold - Gstar_refined_guideline_current",
            "secondary": [
                "FS12_direct_gold - G0_annotation_derived_initial_current",
                "FS4_direct_gold - S0_schema_only_current",
                "FS8_direct_gold - FS4_direct_gold",
                "FS12_direct_gold - FS8_direct_gold",
            ],
        },
        "scoring": {
            "canonical_view": "prediction-only reference-blind offset normalization",
            "metrics": ["entity exact micro-F1", "end-to-end relation exact micro-F1"],
            "uncertainty": "paired report bootstrap; one model execution only",
        },
    }
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"output": str(args.output.resolve()), "blocks": blocks}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

"""Current DeepSeek V4 API price reconstruction.

The direct API uses weekday peak/off-peak pricing.  Provider invoices remain
authoritative; local reconstruction assigns a request to the tier in effect at
its recorded UTC start time.  Experimental runs should be kept away from tier
boundaries so this convention is immaterial.
"""

from __future__ import annotations

from datetime import datetime, time, timedelta, timezone


DEEPSEEK_V4_PRICING = {
    "retrieved_date": "2026-09-03",
    "effective_utc": "2026-08-16T16:00:00+00:00",
    "currency": "USD",
    "unit": "per_1m_tokens",
    "model": "deepseek-v4-pro",
    "served_snapshot": "DeepSeek-V4-Pro-0813",
    "off_peak": {
        "cache_hit_input": 0.022,
        "cache_miss_input": 0.66,
        "output": 1.98,
    },
    "peak": {
        "cache_hit_input": 0.044,
        "cache_miss_input": 1.32,
        "output": 3.96,
    },
    "peak_schedule": {
        "timezone": "Asia/Shanghai (UTC+08:00; no daylight saving time)",
        "weekdays": "Monday-Friday",
        "local_windows": ["09:00-12:00", "14:00-18:00"],
        "utc_windows": ["01:00-04:00", "06:00-10:00"],
    },
    "source": "https://api-docs.deepseek.com/quick_start/pricing/",
    "qualification": (
        "Computed from raw provider usage at the rate in effect when each request "
        "started; provider billing exports are authoritative."
    ),
}

DEEPSEEK_V4_PRE_20260816_RATES = {
    "cache_hit_input": 0.003625,
    "cache_miss_input": 0.435,
    "output": 0.87,
}


def _parse_utc(value: str | datetime | None) -> datetime:
    if value is None:
        return datetime.now(timezone.utc)
    if isinstance(value, datetime):
        dt = value
    else:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def deepseek_rate_tier(at_utc: str | datetime | None = None) -> str:
    """Return the direct-API price tier at a request start time."""
    beijing = _parse_utc(at_utc).astimezone(timezone(timedelta(hours=8)))
    if beijing.weekday() >= 5:
        return "off_peak"
    current = beijing.time().replace(tzinfo=None)
    if time(9, 0) <= current < time(12, 0):
        return "peak"
    if time(14, 0) <= current < time(18, 0):
        return "peak"
    return "off_peak"


def deepseek_token_cost(usage: dict, at_utc: str | datetime | None = None) -> dict:
    """Reconstruct USD cost from cache-hit, cache-miss, and output tokens."""
    prompt = int(usage.get("prompt_tokens") or 0)
    hit = int(usage.get("prompt_cache_hit_tokens") or 0)
    miss = int(usage.get("prompt_cache_miss_tokens") or max(prompt - hit, 0))
    output = int(usage.get("completion_tokens") or 0)
    tier = deepseek_rate_tier(at_utc)
    rates = DEEPSEEK_V4_PRICING[tier]
    usd = (
        hit * rates["cache_hit_input"]
        + miss * rates["cache_miss_input"]
        + output * rates["output"]
    ) / 1_000_000
    return {
        "computed_usd": usd,
        "pricing_tier": tier,
        "rate_time_basis": "request_started_utc",
        "rates_usd_per_1m_tokens": rates,
        "token_breakdown": {
            "input_cache_hit_tokens": hit,
            "input_cache_miss_tokens": miss,
            "output_tokens_including_reasoning": output,
        },
        "qualification": DEEPSEEK_V4_PRICING["qualification"],
    }


def deepseek_legacy_flat_token_cost(usage: dict) -> dict:
    """Preserve reconstruction of experiments completed before the new schedule."""
    prompt = int(usage.get("prompt_tokens") or 0)
    hit = int(usage.get("prompt_cache_hit_tokens") or 0)
    miss = int(usage.get("prompt_cache_miss_tokens") or max(prompt - hit, 0))
    output = int(usage.get("completion_tokens") or 0)
    rates = DEEPSEEK_V4_PRE_20260816_RATES
    usd = (hit * rates["cache_hit_input"] + miss * rates["cache_miss_input"] + output * rates["output"]) / 1_000_000
    return {"computed_usd": usd, "pricing_tier": "legacy_flat_pre_20260816",
            "rates_usd_per_1m_tokens": rates,
            "token_breakdown": {"input_cache_hit_tokens": hit, "input_cache_miss_tokens": miss,
                                "output_tokens_including_reasoning": output},
            "qualification": "Historical flat-rate reconstruction for calls completed before 2026-08-16 16:00 UTC."}

"""Evaluate aligned RadGraph entity and relation predictions on 50 IU X-Ray reports."""

from __future__ import annotations

import argparse
import json
import random
from collections import Counter, defaultdict
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "study_resources/emnlp_guideline_study/data/interim/iu_xray"
GOLD = DATA / "human_gold_with_relations.jsonl"
PRED = DATA / "radgraph_pred_with_relations.jsonl"
OUTPUT_DIR = ROOT / "study_resources/emnlp_guideline_study/evaluation"
ENTITY_LABELS = ("ANAT", "OBS-DP", "OBS-DA", "OBS-U")
RELATION_LABELS = ("Modify", "LocatedAt", "SuggestiveOf")


def load_jsonl(path: Path) -> dict[str, dict]:
    records = [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
    result = {str(record["doc_id"]): record for record in records}
    if len(result) != len(records):
        raise ValueError(f"Duplicate document ID in {path}")
    return result


def overlap(a: dict, b: dict) -> int:
    return max(0, min(a["end"], b["end"]) - max(a["start"], b["start"]))


def iou(a: dict, b: dict) -> float:
    intersection = overlap(a, b)
    return intersection / (max(a["end"], b["end"]) - min(a["start"], b["start"])) if intersection else 0.0


def entity_mapping(gold: list[dict], pred: list[dict], mode: str) -> dict[int, int]:
    """Maximum-cardinality one-to-one mapping from prediction indices to gold indices."""
    adjacency: dict[int, list[int]] = {}
    for pi, p in enumerate(pred):
        candidates = []
        for gi, g in enumerate(gold):
            if p["label"] != g["label"]:
                continue
            valid = (p["start"], p["end"]) == (g["start"], g["end"]) if mode == "strict" else overlap(p, g) > 0
            if valid:
                candidates.append(gi)
        adjacency[pi] = sorted(candidates, key=lambda gi: (-iou(p, gold[gi]), gold[gi]["start"], gi))

    gold_to_pred: dict[int, int] = {}

    def augment(pi: int, seen: set[int]) -> bool:
        for gi in adjacency[pi]:
            if gi in seen:
                continue
            seen.add(gi)
            if gi not in gold_to_pred or augment(gold_to_pred[gi], seen):
                gold_to_pred[gi] = pi
                return True
        return False

    for pi in sorted(adjacency, key=lambda x: (len(adjacency[x]), pred[x]["start"], x)):
        augment(pi, set())
    return {pi: gi for gi, pi in gold_to_pred.items()}


def add_counts(target: Counter, tp: int, fp: int, fn: int) -> None:
    target["tp"] += tp
    target["fp"] += fp
    target["fn"] += fn


def counter_match(gold_items: list[tuple], pred_items: list[tuple]) -> tuple[int, int, int]:
    gold_counter, pred_counter = Counter(gold_items), Counter(pred_items)
    tp = sum((gold_counter & pred_counter).values())
    return tp, sum(pred_counter.values()) - tp, sum(gold_counter.values()) - tp


def relation_counts(record_gold: dict, record_pred: dict, mapping: dict[int, int], conditional: bool) -> dict:
    gold_entities = record_gold["entities"]
    pred_entities = record_pred["entities"]
    gold_id_to_index = {entity["id"]: i for i, entity in enumerate(gold_entities)}
    pred_id_to_index = {entity["id"]: i for i, entity in enumerate(pred_entities)}
    matched_gold = set(mapping.values())

    gold_items = []
    for relation in record_gold["relations"]:
        subj, obj = gold_id_to_index[relation["subj"]], gold_id_to_index[relation["obj"]]
        if not conditional or (subj in matched_gold and obj in matched_gold):
            gold_items.append((subj, relation["pred"], obj))

    pred_items = []
    unmapped_predictions = 0
    for relation in record_pred["relations"]:
        subj_pi, obj_pi = pred_id_to_index[relation["subj"]], pred_id_to_index[relation["obj"]]
        if subj_pi in mapping and obj_pi in mapping:
            pred_items.append((mapping[subj_pi], relation["pred"], mapping[obj_pi]))
        elif not conditional:
            unmapped_predictions += 1

    overall = Counter()
    tp, fp, fn = counter_match(gold_items, pred_items)
    add_counts(overall, tp, fp + unmapped_predictions, fn)
    per_label = {}
    for label in RELATION_LABELS:
        g = [item for item in gold_items if item[1] == label]
        p = [item for item in pred_items if item[1] == label]
        label_tp, label_fp, label_fn = counter_match(g, p)
        # Unmapped predicted relations still have known labels and count as end-to-end FP.
        extra = 0
        if not conditional:
            for relation in record_pred["relations"]:
                subj_pi, obj_pi = pred_id_to_index[relation["subj"]], pred_id_to_index[relation["obj"]]
                if relation["pred"] == label and (subj_pi not in mapping or obj_pi not in mapping):
                    extra += 1
        per_label[label] = Counter(tp=label_tp, fp=label_fp + extra, fn=label_fn)
    return {"overall": overall, "per_label": per_label}


def strict_relation_errors(gold: dict, pred: dict) -> tuple[list[dict], list[dict]]:
    """Return readable unmatched relation records under exact labeled endpoint matching."""
    def expand(record: dict) -> list[tuple[tuple, dict]]:
        entities = {entity["id"]: entity for entity in record["entities"]}
        expanded = []
        for relation in record["relations"]:
            subj, obj = entities[relation["subj"]], entities[relation["obj"]]
            key = (
                subj["start"], subj["end"], subj["label"],
                relation["pred"],
                obj["start"], obj["end"], obj["label"],
            )
            expanded.append((key, {"relation": relation, "subj_entity": subj, "obj_entity": obj}))
        return expanded

    gold_expanded, pred_expanded = expand(gold), expand(pred)
    available_gold: dict[tuple, list[dict]] = defaultdict(list)
    for key, item in gold_expanded:
        available_gold[key].append(item)
    false_positives = []
    for key, item in pred_expanded:
        if available_gold[key]:
            available_gold[key].pop()
        else:
            false_positives.append(item)
    false_negatives = [item for items in available_gold.values() for item in items]
    return false_negatives, false_positives


def evaluate_document(gold: dict, pred: dict) -> tuple[dict, dict]:
    if gold["text"] != pred["text"]:
        raise ValueError(f"Gold/prediction text mismatch in {gold['doc_id']}")
    result = {"entities": {}, "relations": {}}
    audit = {"doc_id": gold["doc_id"], "split": gold["split"]}

    for mode in ("strict", "overlap"):
        mapping = entity_mapping(gold["entities"], pred["entities"], mode)
        overall = Counter()
        per_label = {}
        for label in ENTITY_LABELS:
            gold_n = sum(e["label"] == label for e in gold["entities"])
            pred_n = sum(e["label"] == label for e in pred["entities"])
            tp = sum(pred["entities"][pi]["label"] == label for pi in mapping)
            per_label[label] = Counter(tp=tp, fp=pred_n - tp, fn=gold_n - tp)
            add_counts(overall, tp, pred_n - tp, gold_n - tp)
        result["entities"][mode] = {"overall": overall, "per_label": per_label}
        result["relations"][f"end_to_end_{mode}"] = relation_counts(gold, pred, mapping, conditional=False)
        result["relations"][f"matched_endpoint_{mode}"] = relation_counts(gold, pred, mapping, conditional=True)

        if mode == "strict":
            matched_gold = set(mapping.values())
            matched_pred = set(mapping)
            audit["strict_entity_false_negatives"] = [gold["entities"][i] for i in range(len(gold["entities"])) if i not in matched_gold]
            audit["strict_entity_false_positives"] = [pred["entities"][i] for i in range(len(pred["entities"])) if i not in matched_pred]
            relation_fn, relation_fp = strict_relation_errors(gold, pred)
            audit["strict_relation_false_negatives"] = relation_fn
            audit["strict_relation_false_positives"] = relation_fp
    return result, audit


def merge_results(results: list[dict]) -> dict:
    merged = {"entities": {}, "relations": {}}
    for family in ("entities", "relations"):
        keys = results[0][family]
        labels = ENTITY_LABELS if family == "entities" else RELATION_LABELS
        for key in keys:
            overall = sum((r[family][key]["overall"] for r in results), Counter())
            per_label = {label: sum((r[family][key]["per_label"][label] for r in results), Counter()) for label in labels}
            merged[family][key] = {"overall": overall, "per_label": per_label}
    return merged


def score(counts: Counter) -> dict:
    tp, fp, fn = counts["tp"], counts["fp"], counts["fn"]
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return {"tp": tp, "fp": fp, "fn": fn, "precision": precision, "recall": recall, "f1": f1}


def render_scores(merged: dict) -> dict:
    return {
        family: {
            key: {
                "overall": score(value["overall"]),
                "per_label": {label: score(counts) for label, counts in value["per_label"].items()},
            }
            for key, value in methods.items()
        }
        for family, methods in merged.items()
    }


def percentile(values: list[float], proportion: float) -> float:
    ordered = sorted(values)
    position = (len(ordered) - 1) * proportion
    lower = int(position)
    upper = min(lower + 1, len(ordered) - 1)
    fraction = position - lower
    return ordered[lower] * (1 - fraction) + ordered[upper] * fraction


def bootstrap(results: list[dict], iterations: int, seed: int) -> dict:
    rng = random.Random(seed)
    samples: dict[tuple[str, str, str, str], list[float]] = defaultdict(list)
    n = len(results)
    for _ in range(iterations):
        merged = merge_results([results[rng.randrange(n)] for _ in range(n)])
        rendered = render_scores(merged)
        for family, methods in rendered.items():
            for method, values in methods.items():
                for metric in ("precision", "recall", "f1"):
                    samples[(family, method, "overall", metric)].append(values["overall"][metric])
                for label, label_values in values["per_label"].items():
                    for metric in ("precision", "recall", "f1"):
                        samples[(family, method, label, metric)].append(label_values[metric])
    output: dict = {}
    for (family, method, group, metric), values in samples.items():
        output.setdefault(family, {}).setdefault(method, {}).setdefault(group, {})[metric] = {
            "lower_95": percentile(values, 0.025),
            "upper_95": percentile(values, 0.975),
        }
    return output


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--bootstrap", type=int, default=2000)
    parser.add_argument("--seed", type=int, default=20260721)
    args = parser.parse_args()

    gold, pred = load_jsonl(GOLD), load_jsonl(PRED)
    if set(gold) != set(pred):
        raise ValueError("Gold and prediction document IDs differ")
    doc_ids = list(gold)
    document_results, audits = [], []
    for doc_id in doc_ids:
        result, audit = evaluate_document(gold[doc_id], pred[doc_id])
        document_results.append(result)
        audits.append(audit)

    overall = render_scores(merge_results(document_results))
    by_split = {}
    for split in ("pilot", "heldout"):
        selected = [r for r, doc_id in zip(document_results, doc_ids) if gold[doc_id]["split"] == split]
        by_split[split] = {"documents": len(selected), "scores": render_scores(merge_results(selected))}

    output = {
        "inputs": {"gold": str(GOLD.relative_to(ROOT)), "prediction": str(PRED.relative_to(ROOT))},
        "definitions": {
            "entity_strict": "one-to-one match requires identical start, end, and label",
            "entity_overlap": "maximum-cardinality one-to-one match requires character overlap and identical label",
            "relation_end_to_end": "predicate and directed subject/object endpoints must match after the stated entity mapping; unmapped predicted endpoints count as false positives",
            "relation_matched_endpoint": "conditional diagnostic restricted to gold and predicted relations whose two endpoints participate in the stated one-to-one entity mapping; this is not a model rerun with oracle entities",
        },
        "documents": len(doc_ids),
        "bootstrap": {"iterations": args.bootstrap, "seed": args.seed, "unit": "document", "interval": "percentile 95%"},
        "overall": overall,
        "confidence_intervals": bootstrap(document_results, args.bootstrap, args.seed),
        "by_annotation_round_proxy": by_split,
    }
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    (OUTPUT_DIR / "radgraph_evaluation.json").write_text(json.dumps(output, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (OUTPUT_DIR / "strict_error_cases.jsonl").write_text(
        "".join(json.dumps(audit, ensure_ascii=False, separators=(",", ":")) + "\n" for audit in audits), encoding="utf-8"
    )
    print(json.dumps({
        "entity_strict": overall["entities"]["strict"]["overall"],
        "entity_overlap": overall["entities"]["overlap"]["overall"],
        "relation_end_to_end_strict": overall["relations"]["end_to_end_strict"]["overall"],
        "relation_end_to_end_overlap": overall["relations"]["end_to_end_overlap"]["overall"],
        "relation_matched_endpoint_overlap": overall["relations"]["matched_endpoint_overlap"]["overall"],
    }, indent=2))
    print(f"wrote {OUTPUT_DIR / 'radgraph_evaluation.json'}")
    print(f"wrote {OUTPUT_DIR / 'strict_error_cases.jsonl'}")


if __name__ == "__main__":
    main()

"""Normalize and evaluate DyGIE++ relation predictions made from human gold entities."""

from __future__ import annotations

import json
import random
import argparse
from collections import Counter, defaultdict
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / "study_resources/emnlp_guideline_study"
GOLD = BASE / "data/interim/iu_xray/human_gold_with_relations.jsonl"
LABELS = {"modify": "Modify", "located_at": "LocatedAt", "suggestive_of": "SuggestiveOf"}


def score(counts: Counter) -> dict:
    tp, fp, fn = counts["tp"], counts["fp"], counts["fn"]
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return {"tp": tp, "fp": fp, "fn": fn, "precision": precision, "recall": recall, "f1": f1}


def percentile(values: list[float], proportion: float) -> float:
    values = sorted(values)
    position = (len(values) - 1) * proportion
    lo = int(position)
    hi = min(lo + 1, len(values) - 1)
    return values[lo] * (hi - position) + values[hi] * (position - lo)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--variant", choices=("exact", "released"), default="exact")
    args = parser.parse_args()
    suffix = "" if args.variant == "exact" else "_released_tokenizer"
    audit_path = BASE / f"oracle/oracle_gold_entities_50{suffix}_audit.json"
    raw_path = BASE / f"oracle/oracle_raw_50{suffix}.jsonl"
    normalized_path = BASE / f"oracle/oracle_relations_50{suffix}.jsonl"
    output_path = BASE / f"oracle/oracle_evaluation{suffix}.json"
    gold = {str(x["doc_id"]): x for x in map(json.loads, GOLD.read_text(encoding="utf-8").splitlines())}
    audits = {str(x["doc_id"]): x for x in json.loads(audit_path.read_text(encoding="utf-8"))}
    raw = {x["doc_key"].removeprefix("iu_oracle_"): x for x in map(json.loads, raw_path.read_text(encoding="utf-8").splitlines())}
    if set(gold) != set(audits) or set(gold) != set(raw):
        raise ValueError("Gold, oracle input audit, and raw output document IDs differ")

    normalized, per_document = [], []
    for doc_id, gold_doc in gold.items():
        span_to_id: dict[tuple[int, int], str] = {}
        for entity_id, span in audits[doc_id]["gold_entity_token_spans"].items():
            key = tuple(span)
            if key in span_to_id:
                raise ValueError(f"Duplicate gold token span {key} in {doc_id}")
            span_to_id[key] = entity_id

        predictions = []
        for i, relation in enumerate(raw[doc_id]["predicted_relations"][0], start=1):
            subj_span, obj_span = tuple(relation[0:2]), tuple(relation[2:4])
            if subj_span not in span_to_id or obj_span not in span_to_id:
                raise ValueError(f"Oracle relation endpoint is not a human gold entity in {doc_id}: {relation}")
            predictions.append(
                {
                    "id": f"OR{i}",
                    "subj": span_to_id[subj_span],
                    "pred": LABELS[relation[4]],
                    "obj": span_to_id[obj_span],
                    "raw_score": relation[5],
                    "softmax_score": relation[6],
                }
            )

        normalized.append(
            {
                "doc_id": doc_id,
                "split": gold_doc["split"],
                "source": "radgraph_gold_entity_oracle",
                "entities": gold_doc["entities"],
                "relations": predictions,
            }
        )
        gold_items = [(x["subj"], x["pred"], x["obj"]) for x in gold_doc["relations"]]
        pred_items = [(x["subj"], x["pred"], x["obj"]) for x in predictions]
        gold_counter, pred_counter = Counter(gold_items), Counter(pred_items)
        matched = gold_counter & pred_counter
        overall = Counter(tp=sum(matched.values()), fp=sum((pred_counter - gold_counter).values()), fn=sum((gold_counter - pred_counter).values()))
        label_counts = {}
        for label in LABELS.values():
            g = Counter(x for x in gold_items if x[1] == label)
            p = Counter(x for x in pred_items if x[1] == label)
            m = g & p
            label_counts[label] = Counter(tp=sum(m.values()), fp=sum((p - g).values()), fn=sum((g - p).values()))
        per_document.append({"doc_id": doc_id, "split": gold_doc["split"], "overall": overall, "per_label": label_counts})

    def aggregate(records: list[dict]) -> dict:
        overall = sum((x["overall"] for x in records), Counter())
        return {
            "overall": score(overall),
            "per_label": {label: score(sum((x["per_label"][label] for x in records), Counter())) for label in LABELS.values()},
        }

    point = aggregate(per_document)
    rng = random.Random(20260721)
    bootstrap_values: dict[tuple[str, str], list[float]] = defaultdict(list)
    for _ in range(2000):
        sample = [per_document[rng.randrange(len(per_document))] for _ in per_document]
        result = aggregate(sample)
        for metric in ("precision", "recall", "f1"):
            bootstrap_values[("overall", metric)].append(result["overall"][metric])
        for label, values in result["per_label"].items():
            for metric in ("precision", "recall", "f1"):
                bootstrap_values[(label, metric)].append(values[metric])
    ci: dict = {}
    for (group, metric), values in bootstrap_values.items():
        ci.setdefault(group, {})[metric] = {"lower_95": percentile(values, 0.025), "upper_95": percentile(values, 0.975)}

    by_split = {
        split: {"documents": sum(x["split"] == split for x in per_document), "scores": aggregate([x for x in per_document if x["split"] == split])}
        for split in ("pilot", "heldout")
    }
    result = {
        "definition": "Original RadGraph relation head rerun with human gold entity spans forced into the relation candidate beam; human relation labels were not supplied during inference.",
        "checkpoint": "${USER_HOME}/Downloads/radgraph/models/model_checkpoint/model.tar.gz",
        "documents": len(per_document),
        "tokenization_variant": args.variant,
        "entity_boundary_adjustments": sum(len(x.get("boundary_adjustments", [])) for x in audits.values()),
        "gold_entities": sum(len(x["entities"]) for x in normalized),
        "gold_relations": sum(len(x["relations"]) for x in gold.values()),
        "predicted_relations": sum(len(x["relations"]) for x in normalized),
        "scores": point,
        "confidence_intervals": ci,
        "bootstrap": {"iterations": 2000, "seed": 20260721, "unit": "document", "interval": "percentile 95%"},
        "by_annotation_round_proxy": by_split,
    }
    normalized_path.write_text("".join(json.dumps(x, ensure_ascii=False, separators=(",", ":")) + "\n" for x in normalized), encoding="utf-8")
    output_path.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(result, indent=2))
    print(f"wrote {normalized_path}")
    print(f"wrote {output_path}")


if __name__ == "__main__":
    main()

"""Reconstruct OpenAI token costs from saved Chat Completions usage.

Provider billing exports remain authoritative.  The local estimate separates
uncached input, cache reads, cache writes, and output (including reasoning)
using the token fields returned by the API.
"""

from __future__ import annotations


OPENAI_PRICING = {
    "retrieved_date": "2026-08-28",
    "currency": "USD",
    "unit": "per_1m_tokens",
    "models": {
        "gpt-5.6-sol": {
            "input": 4.00,
            "cached_input": 0.40,
            "cache_write_input": 5.00,
            "output": 20.00,
            "source": "https://developers.openai.com/api/docs/models/gpt-5.6-sol",
        },
        "gpt-5.6-terra": {
            "input": 2.50,
            "cached_input": 0.25,
            "cache_write_input": 3.125,
            "output": 15.00,
            "source": "https://developers.openai.com/api/docs/models/gpt-5.6-terra",
        },
    },
    "qualification": (
        "Computed from raw provider usage at the public rate retrieved on the "
        "stated date; provider billing exports are authoritative."
    ),
}


def openai_token_cost(model: str, usage: dict) -> dict:
    """Return a reproducible USD estimate for one OpenAI response."""
    if model not in OPENAI_PRICING["models"]:
        raise ValueError(f"No frozen OpenAI pricing snapshot for {model}")
    rates = OPENAI_PRICING["models"][model]
    prompt = int(usage.get("prompt_tokens") or 0)
    completion = int(usage.get("completion_tokens") or 0)
    details = usage.get("prompt_tokens_details") or {}
    cached = int(details.get("cached_tokens") or 0)
    writes = int(details.get("cache_write_tokens") or 0)
    uncached = max(prompt - cached - writes, 0)
    usd = (
        uncached * rates["input"]
        + cached * rates["cached_input"]
        + writes * rates["cache_write_input"]
        + completion * rates["output"]
    ) / 1_000_000
    return {
        "computed_usd": usd,
        "rates_usd_per_1m_tokens": {
            k: rates[k]
            for k in ("input", "cached_input", "cache_write_input", "output")
        },
        "token_breakdown": {
            "input_uncached_tokens": uncached,
            "input_cached_tokens": cached,
            "input_cache_write_tokens": writes,
            "output_tokens_including_reasoning": completion,
        },
        "qualification": OPENAI_PRICING["qualification"],
    }

"""API-free rescore of author/human architecture cells on unchanged reference spans.

Uses the historical manuscript's prediction-only repair, not symmetric punctuation
canonicalization. Raw responses and previous analysis artifacts are never edited.
"""
import csv
import hashlib
import json
from pathlib import Path
import analyze_exact_overlap_gap as repair
from collections import Counter
import random

def score_docs(gold,preds,target):
    by={str(p['doc_id']):p for p in preds}; counts={}
    def keys(doc):
        ents={str(e['id']):(int(e['start']),int(e['end']),e['label']) for e in doc['entities']}
        if target=='entity': return Counter(ents.values())
        return Counter((ents[str(r['subj'])],r['pred'],ents[str(r['obj'])]) for r in doc['relations'])
    for g in gold:
        a,b=keys(g),keys(by[str(g['doc_id'])])
        counts[str(g['doc_id'])]=(sum((a&b).values()),sum((b-a).values()),sum((a-b).values()))
    tp,fp,fn=(sum(v[i] for v in counts.values()) for i in range(3))
    return dict(tp=tp,fp=fp,fn=fn,f1=2*tp/(2*tp+fp+fn)),counts

def paired_bootstrap(a,b,seed,n):
    rng=random.Random(seed);ids=sorted(a);values=[]
    for _ in range(n):
        sample=[rng.choice(ids) for _ in ids]; scores=[]
        for source in (a,b):
            tp,fp,fn=(sum(source[i][j] for i in sample) for j in range(3))
            scores.append(2*tp/(2*tp+fp+fn))
        values.append(scores[0]-scores[1])
    values.sort()
    return {'ci95':[values[249],values[9749]]}

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'llm_preliminary/analysis/manuscript_comparators_20260905'
RUNS = ROOT / 'llm_preliminary/runs'

def read(p):
    return json.loads(p.read_text(encoding='utf-8'))

def normalize(directory):
    rows = read(directory / 'predictions.json')
    details = []
    raw_dir = directory / ('raw_joint' if (directory / 'raw_joint').exists() else 'raw_entities')
    for doc in rows:
        answer = repair.raw_answer(raw_dir / (str(doc['doc_id']) + '.json'))
        retained = {(e['start'],e['end'],e['label']) for e in doc['entities']}
        seen = set()
        for e in answer.get('entities', []):
            try: key = (int(e['start']),int(e['end']),str(e['label']))
            except (KeyError,TypeError,ValueError): continue
            if key not in retained or key in seen: continue
            seen.add(key)
            start,end,label = key
            if e.get('text') != doc['text'][start:end]:
                details.append(dict(doc_id=str(doc['doc_id']),start=start,end=end,label=label,
                                    returned_text=e.get('text'),offset_text=doc['text'][start:end]))
    normalized,audit = repair.local_raw_text_repair(rows,details)
    return normalized, audit

def main():
    OUT.mkdir(parents=True,exist_ok=True)
    gold=[json.loads(s) for s in (ROOT/'study_resources/emnlp_guideline_study/data/interim/iu_xray/human_gold_with_relations.jsonl').read_text(encoding='utf-8').splitlines()]
    gold=[g for g in gold if g['split']=='heldout']
    for g in gold:
        g['relations']=list({(r['subj'],r['pred'],r['obj']):r for r in g['relations']}.values())
    ids = {str(g['doc_id']) for g in gold}
    rows_out=[]; contrasts=[]; count_store={}; sources=[]
    for slug,label in [('deepseek_v4_pro','DeepSeek high'),('gpt_5_6_terra','Terra high'),('gpt_5_6_sol','Sol high')]:
        cells={}
        if slug=='deepseek_v4_pro':
            for condition,key in [('Gstar_joint_current','Gstar matched joint'),('FS12_joint_direct_gold','FS12 matched joint')]:
                p=RUNS/'deepseek_v4_pro_high_joint_gstar_fs12_20260903_run01'/condition
                cells[key]=(p/'predictions.json',p)
        if slug != 'gpt_5_6_sol':
            for artifact,condition in [('Gstar','Gstar'),('Human routed','LocalV1'),('Gstar joint','joint_Gstar')]:
                p=ROOT/'llm_preliminary/normalized_predictions/prediction_only_v1'/slug/condition/'predictions.json'
                cells[artifact]=(p,None)
            for condition,key in [('S4_original_author_complete_routed','Author routed'),('S4_original_author_complete_routed_joint','Author routed joint')]:
                p=RUNS/(slug+'_high_author_complete_routed_architecture_20260903')/condition
                cells[key]=(p/'predictions.json',p)
        for condition,key in [('J1_project_human_guideline_v1_full_joint','Human full joint'),('J2_original_author_guideline_complete_joint','Author full joint')]:
            p=RUNS/(slug+'_high_human_author_joint_20260903')/condition
            cells[key]=(p/'predictions.json',p)
        p=RUNS/(slug+'_high_author_guideline_complete_20260903')/'S3_author_guideline_complete'
        cells['Author full']=(p/'predictions.json',p)
        for key,(p,directory) in cells.items():
            if directory:
                preds,audit=normalize(directory)
            else: preds,audit=read(p),[]
            assert len(preds)==38 and {str(x['doc_id']) for x in preds}==ids
            out=OUT/slug/key.replace(' ','_'); out.mkdir(parents=True,exist_ok=True)
            (out/'predictions.json').write_text(json.dumps(preds,ensure_ascii=False),encoding='utf-8')
            sources.append(dict(model=label,condition=key,path=str(p.relative_to(ROOT)),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),mismatches=len(audit),repaired=sum(a['status']=='repaired' for a in audit)))
            count_store[label,key]={}
            for target in ['entity','relation']:
                score,counts=score_docs(gold,preds,target)
                count_store[label,key][target]=counts
                rows_out.append(dict(model=label,condition=key,target=target,**score))
        for a,b in [('FS12 matched joint','Gstar matched joint'),('Gstar joint','Gstar'),('Author routed joint','Author routed'),('Human full joint','Human routed'),('Author full joint','Author full'),('Author full joint','Human full joint'),('Gstar','Author routed'),('Gstar','Author full')]:
            if a not in cells or b not in cells: continue
            for target in ['entity','relation']:
                aa=count_store[label,a][target];bb=count_store[label,b][target]
                boot=paired_bootstrap(aa,bb,seed=20260905,n=10000)
                def f(c):
                    tp,fp,fn=(sum(v[i] for v in c.values()) for i in range(3))
                    return 2*tp/(2*tp+fp+fn)
                contrasts.append(dict(model=label,contrast=a+' - '+b,target=target,difference=f(aa)-f(bb),low=boot['ci95'][0],high=boot['ci95'][1]))
    for name,data in [('scores',rows_out),('contrasts',contrasts),('sources',sources)]:
        with (OUT/(name+'.csv')).open('w',newline='',encoding='utf-8') as f:
            w=csv.DictWriter(f,fieldnames=data[0].keys());w.writeheader();w.writerows(data)
    print(json.dumps(rows_out,indent=2))

if __name__=='__main__': main()

