def build_conditions(plan: dict, pilot_by_id: dict[str, dict], paths: dict[str, Path]) -> dict[str, dict]:
    guidance = {
        "S0_schema_only_current": (
            "No additional annotation guideline is provided.",
            "No additional annotation guideline is provided.",
        ),
        "G0_annotation_derived_initial_current": (
            held.guideline_text(paths["entity_g0"], "entity"),
            held.guideline_text(paths["relation_g0"], "relation"),
        ),
        "Gstar_refined_guideline_current": (
            held.guideline_text(paths["entity_gstar"], "entity"),
            held.guideline_text(paths["relation_gstar"], "relation"),
        ),
    }
    conditions = {}
    for condition_id, specification in plan["conditions"].items():
        demo_ids = [str(doc_id) for doc_id in specification["demonstration_doc_ids"]]
        missing = [doc_id for doc_id in demo_ids if doc_id not in pilot_by_id]
        if missing:
            raise ValueError(f"Unknown pilot demonstration IDs for {condition_id}: {missing}")
        entity_guidance, relation_guidance = guidance.get(
            condition_id,
            ("No additional annotation guideline is provided.", "No additional annotation guideline is provided."),
        )
        conditions[condition_id] = {
            "type": specification["type"],
            "demo_ids": demo_ids,
            "entity_guidance": entity_guidance,
            "relation_guidance": relation_guidance,
            "entity_demonstrations": [entity_demonstration(pilot_by_id[doc_id]) for doc_id in demo_ids],
            "relation_demonstrations": [relation_demonstration(pilot_by_id[doc_id]) for doc_id in demo_ids],
        }
    return conditions


