def annotate_entities(api, conditions: dict, targets: list[dict], root: Path, workers: int) -> dict:
    system = "Annotate entities only in target_report. Return one valid JSON object; no relations or explanation."
    tasks = held.cyclic_tasks(targets, list(conditions))

    def one(task):
        condition_id, target = task
        payload = entity_payload(target, conditions[condition_id])
        output = root / condition_id
        held.dump(output / "entity_prompts" / f"{target['doc_id']}.json", {"system": system, "user": payload})
        answer = api.json(
            system,
            payload,
            output / "raw_entities" / f"{target['doc_id']}.json",
            {
                "phase": "two_stage_entity",
                "condition": condition_id,
                "doc_id": str(target["doc_id"]),
                "demonstration_reports": len(conditions[condition_id]["demo_ids"]),
            },
        )
        entities, audit = held.normalize_entities_audit(target, answer)
        prediction = {
            "doc_id": target["doc_id"],
            "split": "heldout",
            "text": target["text"],
            "entities": entities,
            "relations": [],
        }
        return condition_id, prediction, audit

    grouped = {condition_id: [] for condition_id in conditions}
    audits = {condition_id: {} for condition_id in conditions}
    with ThreadPoolExecutor(max_workers=workers) as pool:
        for condition_id, prediction, audit in pool.map(one, tasks):
            grouped[condition_id].append(prediction)
            audits[condition_id][str(prediction["doc_id"])] = audit
    for condition_id in grouped:
        grouped[condition_id].sort(key=lambda row: str(row["doc_id"]))
        held.dump(root / condition_id / "entity_predictions.json", grouped[condition_id])
        held.dump(root / condition_id / "entity_validation.json", audits[condition_id])
    return grouped


def annotate_relations(api, conditions: dict, targets: list[dict], entity_predictions: dict, root: Path, workers: int) -> dict:
    system = (
        "Annotate relations only over target immutable_entities. Never create or alter entities. "
        "Return one valid JSON object."
    )
    by_condition = {
        condition_id: {str(row["doc_id"]): row for row in rows}
        for condition_id, rows in entity_predictions.items()
    }
    tasks = held.cyclic_tasks(targets, list(conditions))

    def one(task):
        condition_id, target = task
        entities = copy.deepcopy(by_condition[condition_id][str(target["doc_id"])]["entities"])
        payload = relation_payload(target, entities, conditions[condition_id])
        output = root / condition_id
        held.dump(output / "relation_prompts" / f"{target['doc_id']}.json", {"system": system, "user": payload})
        answer = api.json(
            system,
            payload,
            output / "raw_relations" / f"{target['doc_id']}.json",
            {
                "phase": "two_stage_relation",
                "condition": condition_id,
                "doc_id": str(target["doc_id"]),
                "immutable_entity_count": len(entities),
                "demonstration_reports": len(conditions[condition_id]["demo_ids"]),
            },
        )
        relations, audit = held.normalize_relations_audit(answer, {entity["id"] for entity in entities})
        prediction = {
            "doc_id": target["doc_id"],
            "split": "heldout",
            "text": target["text"],
            "entities": entities,
            "relations": relations,
        }
        return condition_id, prediction, audit

    grouped = {condition_id: [] for condition_id in conditions}
    audits = {condition_id: {} for condition_id in conditions}
    with ThreadPoolExecutor(max_workers=workers) as pool:
        for condition_id, prediction, audit in pool.map(one, tasks):
            grouped[condition_id].append(prediction)
            audits[condition_id][str(prediction["doc_id"])] = audit
    for condition_id in grouped:
        grouped[condition_id].sort(key=lambda row: str(row["doc_id"]))
        held.dump(root / condition_id / "predictions.json", grouped[condition_id])
        held.dump(root / condition_id / "relation_validation.json", audits[condition_id])
    return grouped


def prompt_preflight(conditions: dict, targets: list[dict]) -> dict:
    rows = []
    target_ids = {str(target["doc_id"]) for target in targets}
    for condition_id, condition in conditions.items():
        if target_ids.intersection(condition["demo_ids"]):
            raise ValueError(f"Pilot/evaluation ID overlap in {condition_id}")
        entity_chars = []
        relation_chars = []
        for target in targets:
            entity_chars.append(len(json.dumps(entity_payload(target, condition), ensure_ascii=False)))
            relation_chars.append(len(json.dumps(relation_payload(target, [], condition), ensure_ascii=False)))
        rows.append(
            {
                "condition": condition_id,
                "demonstration_reports": len(condition["demo_ids"]),
                "demonstration_doc_ids": condition["demo_ids"],
                "entity_prompt_characters_mean": statistics.mean(entity_chars),
                "entity_prompt_characters_max": max(entity_chars),
                "relation_prompt_characters_mean_without_target_entities": statistics.mean(relation_chars),
                "relation_prompt_characters_max_without_target_entities": max(relation_chars),
            }
        )
    return {
        "status": "PASS",
        "evaluation_reports": len(targets),
        "evaluation_gold_in_prompt": False,
        "pilot_evaluation_doc_id_overlap": False,
        "conditions": rows,
    }


def main() -> None:
    args = cli()
    started_utc = datetime.now(timezone.utc).isoformat()
    wall_tick = time.perf_counter()
    cpu_tick = time.process_time()
    process = psutil.Process()
    initial_rss = process.memory_info().rss

    plan = json.loads(args.plan.read_text(encoding="utf-8"))
    if not args.prepare_only and plan.get("status") != "FROZEN_BEFORE_EXECUTION":
        raise RuntimeError("Execution blocked until plan status is FROZEN_BEFORE_EXECUTION")
    all_rows = load_rows(args.gold)
    pilot = [row for row in all_rows if row.get("split") == "pilot"]
    evaluation_gold = sorted(
        [row for row in all_rows if row.get("split") == "heldout"], key=lambda row: str(row["doc_id"])
    )
    if len(pilot) != 12 or len(evaluation_gold) != 38:
        raise ValueError(f"Expected 12 pilot and 38 evaluation reports; found {len(pilot)} and {len(evaluation_gold)}")
    targets = [{"doc_id": row["doc_id"], "text": row["text"]} for row in evaluation_gold]
    pilot_by_id = {str(row["doc_id"]): row for row in pilot}
    paths = {
        "entity_g0": args.entity_g0.resolve(),
        "entity_gstar": args.entity_gstar.resolve(),
        "relation_g0": args.relation_g0.resolve(),
        "relation_gstar": args.relation_gstar.resolve(),
    }
    conditions = build_conditions(plan, pilot_by_id, paths)
    preflight = prompt_preflight(conditions, targets)

    existing = list(args.output.iterdir()) if args.output.exists() else []
    if existing and not args.resume:
        raise RuntimeError(f"Output directory is not empty; use a fresh path or --resume: {args.output}")
    args.output.mkdir(parents=True, exist_ok=True)
    frozen = args.output / "frozen_inputs"
    for condition_id, condition in conditions.items():
        condition_root = frozen / condition_id
        held.dump(condition_root / "entity_demonstrations.json", condition["entity_demonstrations"])
        held.dump(condition_root / "relation_demonstrations.json", condition["relation_demonstrations"])
        (condition_root / "entity_guidance.txt").write_text(condition["entity_guidance"] + "\n", encoding="utf-8")
        (condition_root / "relation_guidance.txt").write_text(condition["relation_guidance"] + "\n", encoding="utf-8")
    held.dump(args.output / "preflight_report.json", preflight)
    schedule = {
        "two_stage_entity": [
            {"condition": condition_id, "doc_id": str(target["doc_id"])}
            for condition_id, target in held.cyclic_tasks(targets, list(conditions))
        ],
        "two_stage_relation": [
            {"condition": condition_id, "doc_id": str(target["doc_id"])}
            for condition_id, target in held.cyclic_tasks(targets, list(conditions))
        ],
    }
    held.dump(args.output / "call_schedule.json", schedule)

    identity = {
        "protocol": plan["protocol"],
        "provider": "deepseek",
        "model": "deepseek-v4-pro",
        "reasoning_effort": "high",
        "plan_sha256": held.sha(args.plan),
        "gold_sha256": held.sha(args.gold),
        "artifact_sha256": {name: held.sha(path) for name, path in paths.items()},
        "runner_sha256": held.sha(Path(__file__)),
    }
    manifest = {
        **identity,
        "status": "PREPARED" if args.prepare_only else "RUNNING",
        "analysis_role": plan["analysis_role"],
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "conditions": list(conditions),
        "workers": args.workers,
        "pilot_reports": 12,
        "evaluation_reports": 38,
        "evaluation_gold_in_api_prompts": False,
        "adaptive_revision_on_evaluation_set": False,
        "run_identity": identity,
        "schedule_sha256": held.sha(args.output / "call_schedule.json"),
        "preflight_sha256": held.sha(args.output / "preflight_report.json"),
        "frozen_input_sha256": {
            str(path.relative_to(args.output)): held.sha(path) for path in sorted(frozen.rglob("*")) if path.is_file()
        },
        "pricing_snapshot": held.PRICING_SNAPSHOT,
        "environment": {
            "python": platform.python_version(),
            "platform": platform.platform(),
            "openai_package": package_version("openai"),
            "psutil_package": package_version("psutil"),
        },
    }
    if args.resume and (args.output / "manifest.json").exists():
        old = json.loads((args.output / "manifest.json").read_text(encoding="utf-8"))
        if old.get("run_identity") != identity:
            raise RuntimeError("Resume rejected: run identity differs from the frozen execution")
    held.dump(args.output / "manifest.json", manifest)
    if args.prepare_only:
        print(
            json.dumps(
                {
                    "status": "PREPARE_ONLY_OK",
                    "conditions": list(conditions),
                    "provider_calls_planned": 2 * len(conditions) * len(targets),
                    "preflight": preflight,
                },
                ensure_ascii=False,
                indent=2,
            )
        )
        return

    held.base.load_env(args.env_file)
    api = held.FrozenAPI("deepseek", "deepseek-v4-pro", "high", args.max_retries, args.resume, args.output)
    timings = {}
    held.dump(args.output / "run_state.json", {"status": "RUNNING", "run_started_utc": started_utc})

    def phase(name, function):
        phase_started = datetime.now(timezone.utc).isoformat()
        tick = time.perf_counter()
        try:
            value = function()
        except Exception as error:
            timings[name] = {
                "status": "FAILED",
                "started_utc": phase_started,
                "failed_utc": datetime.now(timezone.utc).isoformat(),
                "wall_seconds": time.perf_counter() - tick,
                "error_type": type(error).__name__,
                "error_message": str(error)[:1000],
            }
            held.dump(args.output / "phase_timings.json", timings)
            held.dump(args.output / "run_state.json", {"status": "FAILED", "failed_phase": name, "error": str(error)[:1000]})
            raise
        timings[name] = {
            "status": "COMPLETED",
            "started_utc": phase_started,
            "completed_utc": datetime.now(timezone.utc).isoformat(),
            "wall_seconds": time.perf_counter() - tick,
        }
        held.dump(args.output / "phase_timings.json", timings)
        held.dump(
            args.output / "run_state.json",
            {"status": "RUNNING", "completed_phases": list(timings), "current_phase": None},
        )
        return value

    entity_predictions = phase(
        "two_stage_entity", lambda: annotate_entities(api, conditions, targets, args.output, args.workers)
    )
    relation_predictions = phase(
        "two_stage_relation",
        lambda: annotate_relations(api, conditions, targets, entity_predictions, args.output, args.workers),
    )

    results = {}
    document_counts = {}
    for condition_id in conditions:
        entity_score, entity_counts = held.score_docs(evaluation_gold, entity_predictions[condition_id], "entity")
        relation_score, relation_counts = held.score_docs(evaluation_gold, relation_predictions[condition_id], "relation")
        results[condition_id] = {"entity": entity_score, "relation": relation_score}
        document_counts[condition_id] = {"entity": entity_counts, "relation": relation_counts}
        held.dump(args.output / condition_id / "scores.json", results[condition_id])

    comparisons = [
        ("FS12_minus_Gstar", "FS12_direct_gold", "Gstar_refined_guideline_current"),
        ("FS12_minus_G0", "FS12_direct_gold", "G0_annotation_derived_initial_current"),
        ("FS4_minus_S0", "FS4_direct_gold", "S0_schema_only_current"),
        ("FS8_minus_FS4", "FS8_direct_gold", "FS4_direct_gold"),
        ("FS12_minus_FS8", "FS12_direct_gold", "FS8_direct_gold"),
    ]
    contrasts = {}
    for name, first, second in comparisons:
        contrasts[name] = {}
        for target_type in ("entity", "relation"):
            bootstrap = held.paired_bootstrap(
                document_counts[first][target_type], document_counts[second][target_type]
            )
            bootstrap["difference"] = results[first][target_type]["f1"] - results[second][target_type]["f1"]
            contrasts[name][target_type] = bootstrap

    report = {
        "scope": "post-hoc direct-demonstration baseline on the fixed 38-report evaluation set",
        "prediction_view": "as-returned parsed offsets; canonical normalized analysis follows separately",
        "results": results,
        "contrasts": contrasts,
    }
    held.dump(args.output / "results_raw.json", report)
    resources = {
        "run_started_utc": started_utc,
        "run_completed_utc": datetime.now(timezone.utc).isoformat(),
        "total_wall_seconds": time.perf_counter() - wall_tick,
        "total_process_cpu_seconds": time.process_time() - cpu_tick,
        "initial_rss_bytes": initial_rss,
        "final_rss_bytes": process.memory_info().rss,
        "workers": args.workers,
        "max_retries": args.max_retries,
        "phase_timings": timings,
        "ledger": held.ledger_summary(args.output / "call_ledger.jsonl"),
        "validation": held.validation_summary(args.output),
        "pricing_snapshot": held.PRICING_SNAPSHOT,
    }
    resources["output_directory_bytes_before_resource_summary"] = held.directory_bytes(args.output)
    held.dump(args.output / "resource_summary.json", resources)
    resources["output_directory_bytes_final"] = held.directory_bytes(args.output)
    held.dump(args.output / "resource_summary.json", resources)
    fingerprints = sorted(
        {
            str(event.get("system_fingerprint"))
            for event in api.usage
            if event.get("system_fingerprint")
        }
    )
    manifest.update(
        {
            "status": "COMPLETED",
            "completed_utc": resources["run_completed_utc"],
            "system_fingerprints": fingerprints,
            "results_raw": results,
            "resource_summary": "resource_summary.json",
            "call_ledger": "call_ledger.jsonl",
        }
    )
    held.dump(args.output / "manifest.json", manifest)
    held.dump(
        args.output / "run_state.json",
        {"status": "COMPLETED", "completed_utc": resources["run_completed_utc"], "completed_phases": list(timings)},
    )
    print(json.dumps(report, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

"""Run the frozen 12-document G0--G3 RadGraph guideline case-study pilot.

The program deliberately reads gold annotations only for records whose split is
``pilot``.  Held-out records are neither loaded nor evaluated.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import sys
import time
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path

from openai import OpenAI

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))
from evaluate_radgraph_ie import evaluate_document, merge_results, render_scores  # noqa: E402

ENTITY_LABELS = {"ANAT", "OBS-DP", "OBS-DA", "OBS-U"}
RELATION_LABELS = {"Modify", "LocatedAt", "SuggestiveOf"}
STAGES = ("G0", "G1", "G2", "G3")

STAGE_INSTRUCTIONS = {
    "G0": """PRINCIPLE GENERATION. Infer a deployable annotation guideline from the schema and all 12 report-gold pairs. State operational principles, boundary rules, label definitions, relation directionality, and evidence-linked examples. Do not merely summarize the examples.""",
    "G1": """PRINCIPLE COMPLETION. Use the current guideline, all 12 gold pairs, predictions, and deterministic discrepancy ledger. Add missing rules, definitions, exceptions, and clarifications. For every substantive change, cite supporting error IDs and classify its cause as omission, ambiguity, exception, or interaction.""",
    "G2": """INTERACTION RESOLUTION. Resolve rule conflicts, precedence, composition, regressions, and entity-relation interactions. Preserve useful rules, explicitly state precedence, and cite supporting error IDs. Do not optimize by memorizing document IDs or isolated spans.""",
    "G3": """CONSISTENCY NORMALIZATION. Deduplicate, normalize terminology, align prose with the rule inventory, and remove unsupported content. Do not add new substantive rules. Preserve existing rule IDs for retained rules and keep the principle count no larger than G2.""",
}

SYSTEM_GUIDELINE = """You are designing a RadGraph-style annotation manual for chest radiology reports. Use only the supplied evidence. Return one valid JSON object, with no markdown fence. The guideline must generalize beyond the supplied reports and must never mention answers for a particular document at deployment time."""

SYSTEM_ANNOTATE = """You are a deterministic RadGraph-style annotator. Apply only the supplied guideline to the report. Return one valid JSON object with keys entities and relations and no markdown fence. Entities use half-open Python character offsets [start,end), exact report substrings, and labels ANAT, OBS-DP, OBS-DA, OBS-U. Relations use predicates Modify, LocatedAt, SuggestiveOf and reference entity IDs. Do not emit explanations."""


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--gold", type=Path, default=ROOT / "study_resources/emnlp_guideline_study/data/interim/iu_xray/human_gold_with_relations.jsonl")
    parser.add_argument("--output-root", type=Path, default=ROOT / "llm_preliminary/runs")
    parser.add_argument("--env-file", type=Path)
    parser.add_argument("--model", default="deepseek-chat")
    parser.add_argument("--base-url", default="https://api.deepseek.com")
    parser.add_argument("--api-key-env", default="DEEPSEEK_API_KEY")
    parser.add_argument("--run-id")
    parser.add_argument("--resume", type=Path)
    parser.add_argument("--recompute-stage", action="append", choices=STAGES, default=[])
    parser.add_argument("--max-retries", type=int, default=4)
    return parser.parse_args()


def load_env(path: Path | None) -> None:
    if not path:
        return
    for raw in path.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))


def dump(path: Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load_pilot(path: Path) -> list[dict]:
    pilot = []
    with path.open(encoding="utf-8") as handle:
        for line in handle:
            record = json.loads(line)
            if record.get("split") == "pilot":
                pilot.append(record)
    if len(pilot) != 12:
        raise ValueError(f"Expected exactly 12 pilot records, found {len(pilot)}")
    return pilot


def compact_gold(records: list[dict]) -> list[dict]:
    return [{"doc_id": r["doc_id"], "text": r["text"], "entities": r["entities"], "relations": r["relations"]} for r in records]


def indexed_text(text: str) -> str:
    """Expose deterministic offsets without adding any annotation information."""
    return " ".join(f"[{m.start()}:{m.end()}]{m.group()}" for m in re.finditer(r"\S+", text))


def api_json(client: OpenAI, model: str, system: str, payload: dict, retries: int) -> tuple[dict, dict]:
    last_error = None
    for attempt in range(1, retries + 1):
        try:
            response = client.chat.completions.create(
                model=model,
                temperature=0,
                messages=[{"role": "system", "content": system}, {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}],
                response_format={"type": "json_object"},
            )
            raw = response.model_dump()
            content = response.choices[0].message.content
            return json.loads(content), raw
        except Exception as exc:  # API and malformed-output retry boundary
            last_error = exc
            if attempt < retries:
                time.sleep(min(2 ** attempt, 12))
    raise RuntimeError(f"API call failed after {retries} attempts: {last_error}")


def guideline_payload(stage: str, gold: list[dict], prior: dict | None, predictions: list[dict] | None, ledger: dict | None) -> dict:
    output_contract = {
        "stage": stage,
        "deployment_guideline": "self-contained prose manual",
        "principles": [{
            "rule_id": "stable ID such as E01 or R01", "domain": "entity|relation|interaction",
            "instruction": "operational rule", "applies_when": "condition", "exceptions": [],
            "priority": "integer", "supporting_doc_ids": [], "supporting_error_ids": [],
            "examples": [], "conflicts_with": [], "status": "active|removed",
        }],
        "change_log": [{"rule_id": "ID", "action": "add|revise|remove|retain", "cause": "generation|omission|ambiguity|exception|interaction|normalization", "supporting_error_ids": [], "rationale": "text"}],
        "unresolved_issues": [], "stage_summary": "text",
    }
    payload = {
        "task": STAGE_INSTRUCTIONS[stage],
        "schema": {"entity_labels": sorted(ENTITY_LABELS), "relation_labels": sorted(RELATION_LABELS), "offsets": "half-open [start,end)"},
        "all_12_report_gold_pairs": compact_gold(gold),
        "required_output_contract": output_contract,
        "output_budget": {
            "maximum_active_principles": 12,
            "maximum_examples_per_principle": 1,
            "maximum_representative_error_ids_per_principle_or_change": 3,
            "maximum_words_deployment_guideline": 800,
            "maximum_words_instruction_per_principle": 40,
            "maximum_words_applies_when_per_principle": 20,
            "maximum_exceptions_per_principle": 3,
            "maximum_words_per_exception": 15,
            "maximum_change_log_entries": 12,
            "maximum_words_rationale_per_change": 30,
            "change_log_policy": "one concise entry per substantively changed rule; do not enumerate every error",
            "maximum_unresolved_issues": 5,
            "instruction": "Hard limits. The complete ledger is preserved separately. Never list all errors or reproduce reports. Compress evidence into operational rules and finish the JSON object well below 20000 characters.",
        },
    }
    if prior is not None:
        payload["current_guideline"] = prior
        # Text is already present once in all_12_report_gold_pairs. Retain every
        # prediction and error, but remove duplicated text/context serialization.
        payload["current_stage_predictions"] = [
            {"doc_id": p["doc_id"], "entities": p["entities"], "relations": p["relations"]}
            for p in (predictions or [])
        ]
        payload["deterministic_discrepancy_ledger"] = {
            "summary": ledger["summary"],
            "resolved_error_ids": ledger["resolved_error_ids"],
            "errors": [
                {k: e[k] for k in ("error_id", "doc_id", "type", "key", "status_vs_previous")}
                for e in ledger["errors"]
            ],
        }
    return payload


def validate_guideline(stage: str, artifact: dict, prior: dict | None) -> None:
    # The stage is protocol metadata known to the runner, not an induced rule.
    # Deterministically filling this one field is a structural normalization.
    artifact.setdefault("stage", stage)
    required = {"stage", "deployment_guideline", "principles", "change_log", "unresolved_issues", "stage_summary"}
    missing = required - artifact.keys()
    if missing or artifact.get("stage") != stage or not isinstance(artifact.get("principles"), list):
        raise ValueError(f"Invalid {stage} guideline artifact; missing={sorted(missing)}")
    ids = [str(r.get("rule_id")) for r in artifact["principles"]]
    if len(ids) != len(set(ids)) or any(x in {"", "None"} for x in ids):
        raise ValueError(f"Invalid or duplicate rule IDs in {stage}")
    if stage == "G3" and prior is not None:
        prior_ids = {str(r.get("rule_id")) for r in prior["principles"]}
        if len(ids) > len(prior_ids) or not set(ids).issubset(prior_ids):
            raise ValueError("G3 introduced a new rule ID or increased the rule count")


def normalize_prediction(doc: dict, answer: dict) -> tuple[dict, list[dict]]:
    issues: list[dict] = []
    entities, old_to_new, seen = [], {}, set()
    for i, entity in enumerate(answer.get("entities", []), 1):
        old_id = str(entity.get("id", f"raw-{i}"))
        try:
            start, end, label = int(entity["start"]), int(entity["end"]), str(entity["label"])
        except Exception:
            issues.append({"type": "invalid_entity_schema", "raw": entity})
            continue
        if label not in ENTITY_LABELS or not (0 <= start < end <= len(doc["text"])):
            issues.append({"type": "invalid_entity_value", "raw": entity})
            continue
        actual = doc["text"][start:end]
        if "text" in entity and entity["text"] != actual:
            surface = str(entity["text"])
            candidates = [m.start() for m in re.finditer(re.escape(surface), doc["text"])
                          if abs(m.start() - start) <= 8 and abs((m.start() + len(surface)) - end) <= 8]
            ranked = sorted((abs(pos - start) + abs(pos + len(surface) - end), pos) for pos in candidates)
            if ranked and (len(ranked) == 1 or ranked[0][0] < ranked[1][0]):
                original = {"start": start, "end": end, "actual": actual}
                start, end = ranked[0][1], ranked[0][1] + len(surface)
                actual = doc["text"][start:end]
                issues.append({"type": "offset_normalized", "raw": entity, "original": original, "normalized": {"start": start, "end": end}})
            else:
                issues.append({"type": "entity_text_offset_mismatch", "raw": entity, "actual": actual})
                continue
        key = (start, end, label)
        if key in seen:
            issues.append({"type": "duplicate_entity", "raw": entity})
            continue
        new_id = f"T{len(entities) + 1}"
        old_to_new[old_id] = new_id
        seen.add(key)
        entities.append({"id": new_id, "start": start, "end": end, "label": label, "text": actual})
    relations, rel_seen = [], set()
    for relation in answer.get("relations", []):
        subj, obj, pred = str(relation.get("subj")), str(relation.get("obj")), str(relation.get("pred"))
        if pred not in RELATION_LABELS or subj not in old_to_new or obj not in old_to_new:
            issues.append({"type": "invalid_relation", "raw": relation})
            continue
        key = (old_to_new[subj], pred, old_to_new[obj])
        if key in rel_seen:
            issues.append({"type": "duplicate_relation", "raw": relation})
            continue
        rel_seen.add(key)
        relations.append({"id": f"R{len(relations) + 1}", "subj": key[0], "pred": pred, "obj": key[2]})
    return {"doc_id": doc["doc_id"], "split": "pilot", "text": doc["text"], "entities": entities, "relations": relations}, issues


def annotate_all(client: OpenAI, model: str, guideline: dict, gold: list[dict], stage_dir: Path, retries: int) -> tuple[list[dict], list[dict]]:
    predictions, validation = [], []
    for index, doc in enumerate(gold, 1):
        payload = {
            "guideline": guideline["deployment_guideline"],
            "rule_inventory": guideline["principles"],
            "report": {"doc_id": doc["doc_id"], "text": doc["text"]},
            "offset_reference": indexed_text(doc["text"]),
            "offset_instruction": "Use offset_reference to copy exact coordinates. It is the same report tokenized by non-whitespace spans. Entity boundaries may be narrower than a displayed token only when the guideline requires excluding punctuation; adjust that endpoint exactly against report.text.",
            "output_contract": {"entities": [{"id": "T1", "start": 0, "end": 4, "label": "ANAT", "text": "exact substring"}], "relations": [{"id": "R1", "subj": "T1", "pred": "LocatedAt", "obj": "T2"}]},
        }
        raw_path = stage_dir / "raw_annotations" / f"{doc['doc_id']}.json"
        if raw_path.exists():
            raw = json.loads(raw_path.read_text(encoding="utf-8"))
            answer = json.loads(raw["choices"][0]["message"]["content"])
        else:
            answer, raw = api_json(client, model, SYSTEM_ANNOTATE, payload, retries)
            dump(raw_path, raw)
        prediction, issues = normalize_prediction(doc, answer)
        predictions.append(prediction)
        validation.append({"doc_id": doc["doc_id"], "issues": issues})
        print(f"{stage_dir.name}: annotated {index}/12 ({doc['doc_id']})", flush=True)
    dump(stage_dir / "predictions.json", predictions)
    dump(stage_dir / "validation_issues.json", validation)
    return predictions, validation


def entity_key(entity: dict) -> tuple:
    return entity["start"], entity["end"], entity["label"]


def relation_key(record: dict, relation: dict) -> tuple:
    entities = {e["id"]: e for e in record["entities"]}
    return entity_key(entities[relation["subj"]]) + (relation["pred"],) + entity_key(entities[relation["obj"]])


def discrepancy_ledger(gold: list[dict], predictions: list[dict], previous_ids: set[str]) -> tuple[dict, set[str]]:
    errors, current_ids = [], set()
    pred_by_id = {p["doc_id"]: p for p in predictions}
    for g in gold:
        p = pred_by_id[g["doc_id"]]
        pairs = [
            ("entity_fn", Counter(entity_key(e) for e in g["entities"]), Counter(entity_key(e) for e in p["entities"]), True),
            ("entity_fp", Counter(entity_key(e) for e in p["entities"]), Counter(entity_key(e) for e in g["entities"]), False),
            ("relation_fn", Counter(relation_key(g, r) for r in g["relations"]), Counter(relation_key(p, r) for r in p["relations"]), True),
            ("relation_fp", Counter(relation_key(p, r) for r in p["relations"]), Counter(relation_key(g, r) for r in g["relations"]), False),
        ]
        for kind, source, other, is_fn in pairs:
            remaining = source - other
            for key, count in sorted(remaining.items(), key=lambda x: str(x[0])):
                for occurrence in range(count):
                    stable = f"{g['doc_id']}|{kind}|{json.dumps(key, separators=(',', ':'))}|{occurrence}"
                    error_id = "E-" + hashlib.sha256(stable.encode()).hexdigest()[:12]
                    current_ids.add(error_id)
                    errors.append({"error_id": error_id, "doc_id": g["doc_id"], "type": kind, "key": key, "status_vs_previous": "persistent" if error_id in previous_ids else "new", "context": g["text"][max(0, int(key[0])-40):min(len(g["text"]), int(key[1])+40)] if key else "", "gold_side": is_fn})
    return {
        "summary": {"total": len(errors), "persistent": len(current_ids & previous_ids), "new": len(current_ids - previous_ids), "resolved": len(previous_ids - current_ids)},
        "resolved_error_ids": sorted(previous_ids - current_ids), "errors": errors,
    }, current_ids


def evaluate(gold: list[dict], predictions: list[dict]) -> tuple[dict, list[dict]]:
    pred_by_id = {p["doc_id"]: p for p in predictions}
    document_results, audits = [], []
    for record in gold:
        result, audit = evaluate_document(record, pred_by_id[record["doc_id"]])
        document_results.append(result)
        audits.append(audit)
    return render_scores(merge_results(document_results)), audits


def main() -> None:
    args = parse_args()
    load_env(args.env_file)
    api_key = os.environ.get(args.api_key_env)
    if not api_key:
        raise RuntimeError(f"Missing API key environment variable {args.api_key_env}")
    gold = load_pilot(args.gold)
    run_dir = args.resume or args.output_root / (args.run_id or datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ"))
    run_dir.mkdir(parents=True, exist_ok=True)
    client = OpenAI(api_key=api_key, base_url=args.base_url)
    manifest = {
        "protocol": "G0-G3-all-12-development-v1", "created_utc": datetime.now(timezone.utc).isoformat(),
        "model": args.model, "base_url": args.base_url, "api_key_env": args.api_key_env,
        "gold_path": str(args.gold.resolve()), "gold_sha256": sha256(args.gold),
        "consumed_splits": ["pilot"], "development_doc_ids": [r["doc_id"] for r in gold],
        "heldout_gold_loaded": False, "stages": list(STAGES), "stage_definitions": STAGE_INSTRUCTIONS,
    }
    dump(run_dir / "manifest.json", manifest)
    prior = None
    previous_error_ids: set[str] = set()
    prior_predictions = prior_ledger = None
    trajectory = []
    for stage in STAGES:
        stage_dir = run_dir / stage
        complete = (stage_dir / "guideline.json").exists() and (stage_dir / "predictions.json").exists() and (stage_dir / "ledger.json").exists()
        if complete and stage not in args.recompute_stage:
            prior = json.loads((stage_dir / "guideline.json").read_text(encoding="utf-8"))
            prior_predictions = json.loads((stage_dir / "predictions.json").read_text(encoding="utf-8"))
            prior_ledger = json.loads((stage_dir / "ledger.json").read_text(encoding="utf-8"))
            previous_error_ids = {e["error_id"] for e in prior_ledger["errors"]}
            scores = json.loads((stage_dir / "scores.json").read_text(encoding="utf-8"))
        else:
            payload = guideline_payload(stage, gold, prior, prior_predictions, prior_ledger)
            dump(stage_dir / "guideline_prompt_payload.json", payload)
            if (stage_dir / "guideline.json").exists():
                artifact = json.loads((stage_dir / "guideline.json").read_text(encoding="utf-8"))
            else:
                artifact, raw = api_json(client, args.model, SYSTEM_GUIDELINE, payload, args.max_retries)
                dump(stage_dir / "raw_guideline_response.json", raw)
                dump(stage_dir / "guideline_candidate.json", artifact)
                validate_guideline(stage, artifact, prior)
                dump(stage_dir / "guideline.json", artifact)
            predictions, _ = annotate_all(client, args.model, artifact, gold, stage_dir, args.max_retries)
            scores, audits = evaluate(gold, predictions)
            ledger, previous_error_ids = discrepancy_ledger(gold, predictions, previous_error_ids)
            dump(stage_dir / "scores.json", scores)
            dump(stage_dir / "audit.json", audits)
            dump(stage_dir / "ledger.json", ledger)
            prior, prior_predictions, prior_ledger = artifact, predictions, ledger
        trajectory.append({
            "stage": stage,
            "entity_exact_f1": scores["entities"]["strict"]["overall"]["f1"],
            "relation_exact_end_to_end_f1": scores["relations"]["end_to_end_strict"]["overall"]["f1"],
            "errors": prior_ledger["summary"],
        })
        dump(run_dir / "trajectory.json", trajectory)
    manifest["completed_utc"] = datetime.now(timezone.utc).isoformat()
    manifest["artifact_hashes"] = {str(p.relative_to(run_dir)): sha256(p) for p in sorted(run_dir.rglob("*.json")) if p.name != "manifest.json"}
    dump(run_dir / "manifest.json", manifest)
    print(json.dumps({"run_dir": str(run_dir.resolve()), "trajectory": trajectory}, ensure_ascii=False, indent=2))


