                raise RuntimeError("Resume reconstruction did not reproduce the interrupted candidate prompt")
            prior_raw=prior_dir/"raw.json"
            if prior_raw.exists():
                shutil.copy2(prior_raw,cdir/"raw.json"); resume_meta["reused_cached_candidate_raw"]=True
