            execution_failure=isinstance(e,RuntimeError) and str(e).startswith("API failed for")
        if execution_failure:
            failure={"iteration":i,"stratum":stratum,"cases":len(cases),"reason":reason,
                "score_unchanged":score,"failed_utc":datetime.now(timezone.utc).isoformat()}
            two.dump(cdir/"execution_failure.json",failure)
            two.dump(a.output/"state.json",{"history":history,"current_score":score,"pending_execution":failure})
            manifest.update({"status":"INTERRUPTED","interrupted_utc":failure["failed_utc"],
                "interrupted_iteration":i,"interrupted_stratum":stratum,
                "interrupted_reason":reason,"usage":api.usage})
            two.dump(a.output/"manifest.json",manifest); raise RuntimeError(reason)
        decision={"iteration":i,"stratum":stratum,"cases":len(cases),"accepted":accept,"reason":reason,"before":score,"after":newscore}
        two.dump(cdir/"decision.json",decision); history.append(decision)
        if accept: current,pred,score=proposed,newpred,newscore
        else: rejected[sig].add(stratum)
        two.dump(a.output/"state.json",{"history":history,"current_score":score}); i+=1
    final_census=causal_census(relgold,pred); two.dump(a.output/"R_star/guideline.json",current); two.dump(a.output/"R_star/predictions.json",pred)
    two.dump(a.output/"R_star/score.json",score); two.dump(a.output/"R_star/causal_census.json",final_census)
    manifest.update({"status":"COMPLETED","completed_utc":datetime.now(timezone.utc).isoformat(),"r0_score":r0_score,
        "final_score":score,"candidates":len(history),"accepted":sum(x["accepted"] for x in history),
        "continuation_candidates":len(history)-(resume_meta["restored_through_iteration"] if resume_meta else 0),
        "usage":api.usage,
        "returned_models":sorted({str(x.get('returned_model')) for x in api.usage if x.get('returned_model')}),
        "system_fingerprints":sorted({str(x.get('system_fingerprint')) for x in api.usage if x.get('system_fingerprint')})})
    two.dump(a.output/"manifest.json",manifest); print(json.dumps(manifest,ensure_ascii=False,indent=2))

if __name__=="__main__": main()

