        "Computed from raw provider usage for reproducibility; the provider "
        "billing export remains authoritative."
    ),
}


def cli() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--env-file", type=Path, required=True)
    parser.add_argument(
        "--plan",
        type=Path,
        default=ROOT / "llm_preliminary/sol_heldout38_secondary_plan.json",
    )
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--workers", type=int, default=8)
    parser.add_argument("--max-retries", type=int, default=8)
    parser.add_argument("--prepare-only", action="store_true")
    parser.add_argument("--resume", action="store_true")
    return parser.parse_args()


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def dump(path: Path, value) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def resolve_sources(plan: dict) -> dict[str, Path]:
    return {key: (ROOT / relative).resolve() for key, relative in plan["sources"].items()}


def verify_frozen_plan(plan_path: Path, plan: dict, sources: dict[str, Path], execute: bool) -> None:
    if plan.get("protocol") != PROTOCOL:
        raise RuntimeError("Plan protocol does not match the Sol secondary runner")
    if execute and plan.get("status") != "FROZEN_BEFORE_SOL_HELDOUT_EXECUTION":
        raise RuntimeError("Execution blocked: the Sol held-out plan has not passed the freeze gate")
    if plan.get("model") != MODEL or plan.get("reasoning_effort") != REASONING_EFFORT:
        raise RuntimeError("Frozen model or reasoning setting does not match the runner")
    for key, path in sources.items():
        expected = plan["source_sha256"].get(key)
        observed = sha256(path)
        if observed != expected:
            raise RuntimeError(f"Frozen source hash mismatch for {key}: {observed} != {expected}")
    expected_runner = plan.get("runner_sha256")
    observed_runner = sha256(Path(__file__))
    if expected_runner and observed_runner != expected_runner:
        raise RuntimeError(f"Runner hash mismatch: {observed_runner} != {expected_runner}")
    if not plan_path.is_file():
        raise RuntimeError("Frozen plan path is unavailable")


def render_conditions(sources: dict[str, Path]) -> dict[str, tuple[str, str]]:
    rendered = {
        "S0_schema_only": (MINIMAL, MINIMAL),
        "G0_annotation_derived_initial": (
            held.guideline_text(sources["entity_g0"], "entity"),
            held.guideline_text(sources["relation_r0"], "relation"),
        ),
        "Gstar_final": (
            held.guideline_text(sources["entity_gstar"], "entity"),
            held.guideline_text(sources["relation_rstar"], "relation"),
        ),
    }
    if any(not entity.strip() or not relation.strip() for entity, relation in rendered.values()):
        raise RuntimeError("A rendered guidance condition is empty")
    return rendered


def annotate_component_cells(api, conditions, gold, entity_predictions, output, workers):
    system = (
        "Annotate relations only over immutable_entities. Never create or alter entities. "
        "Return one valid JSON object."
    )
    by_condition = {
        condition: {str(row["doc_id"]): row for row in rows}
        for condition, rows in entity_predictions.items()
    }
    tasks = held.cyclic_tasks(gold, list(COMPONENT_CELLS))

    def one(task):
        cell, report = task
        entity_condition, relation_condition = COMPONENT_CELLS[cell]
        out = output / "relation_components" / cell
        entities = copy.deepcopy(by_condition[entity_condition][str(report["doc_id"])]["entities"])
        valid_ids = {entity["id"] for entity in entities}
        payload = {
            "task_schema": held.RELATION_SCHEMA,
            "operational_guidance": conditions[relation_condition][1],
            "report": {"doc_id": report["doc_id"], "text": report["text"]},
            "immutable_entities": entities,
            "output_contract": {
                "type": "object",
                "required": ["relations"],
                "relations": {
                    "type": "array",
                    "item_required": ["subj", "pred", "obj"],
                    "constraints": [
                        "subj and obj are IDs in immutable_entities",
                        "pred is one of Modify, LocatedAt, SuggestiveOf",
                        "the ordered triple is unique",
                    ],
                },
            },
        }
        held.dump(out / "relation_prompts" / f"{report['doc_id']}.json", {"system": system, "user": payload})
        answer = api.json(
            system,
            payload,
            out / "raw_relations" / f"{report['doc_id']}.json",
            {
                "phase": "relation_component_cells",
                "condition": cell,
                "doc_id": str(report["doc_id"]),
                "entity_inventory_condition": entity_condition,
                "relation_guidance_condition": relation_condition,
                "immutable_entity_count": len(entities),
            },
        )
        relations, audit = held.normalize_relations_audit(answer, valid_ids)
        prediction = {
            "doc_id": report["doc_id"],
            "split": "heldout",
            "text": report["text"],
            "entities": entities,
            "relations": relations,
        }
        return cell, prediction, audit

    grouped = {cell: [] for cell in COMPONENT_CELLS}
    audits = {cell: {} for cell in COMPONENT_CELLS}
    with ThreadPoolExecutor(max_workers=workers) as pool:
        for cell, prediction, audit in pool.map(one, tasks):
            grouped[cell].append(prediction)
            audits[cell][str(prediction["doc_id"])] = audit
    for cell in COMPONENT_CELLS:
        out = output / "relation_components" / cell
        grouped[cell].sort(key=lambda row: str(row["doc_id"]))
        held.dump(out / "predictions.json", grouped[cell])
        held.dump(out / "relation_validation.json", audits[cell])
    return grouped


def main() -> None:
    args = cli()
    plan_path = args.plan.resolve()
    plan = json.loads(plan_path.read_text(encoding="utf-8"))
    sources = resolve_sources(plan)
    verify_frozen_plan(plan_path, plan, sources, execute=not args.prepare_only)
    conditions = render_conditions(sources)
    gold = held.load_heldout(sources["gold"])

    existing = list(args.output.iterdir()) if args.output.exists() else []
    if existing and not args.resume:
        raise RuntimeError(f"Output directory is not empty: {args.output}")
    if args.resume and existing and not (args.output / "manifest.json").exists():
        raise RuntimeError("Resume rejected: existing output has no manifest.json")
    previous_manifest = None
    if args.resume and existing:
        previous_manifest = json.loads(
            (args.output / "manifest.json").read_text(encoding="utf-8")
        )

    args.output.mkdir(parents=True, exist_ok=True)
    frozen_inputs = args.output / "frozen_inputs"
    for condition, (entity_guidance, relation_guidance) in conditions.items():
        target = frozen_inputs / condition
        target.mkdir(parents=True, exist_ok=True)
        (target / "entity.txt").write_text(entity_guidance + "\n", encoding="utf-8")
        (target / "relation.txt").write_text(relation_guidance + "\n", encoding="utf-8")

    schedule = {
        "two_stage_entity": held.cyclic_tasks(gold, list(conditions)),
        "two_stage_relation": held.cyclic_tasks(gold, list(conditions)),
        "relation_component_cells": held.cyclic_tasks(gold, list(COMPONENT_CELLS)),
    }
    schedule_ids = {
        phase: [{"condition": condition, "doc_id": report["doc_id"]} for condition, report in tasks]
        for phase, tasks in schedule.items()
    }
    dump(args.output / "call_schedule.json", schedule_ids)

    run_identity = {
        "protocol": PROTOCOL,
        "model": MODEL,
        "reasoning_effort": REASONING_EFFORT,
        "plan_sha256": sha256(plan_path),
        "runner_sha256": sha256(Path(__file__)),
        "source_sha256": {key: sha256(path) for key, path in sources.items()},
    }
    if previous_manifest is not None:
        previous_identity = {
            key: previous_manifest.get(key)
            for key in (
                "protocol",
                "model",
                "reasoning_effort",
                "plan_sha256",
                "runner_sha256",
                "source_sha256",
            )
        }
        if previous_identity != run_identity:
            raise RuntimeError("Resume rejected: existing manifest identity differs from frozen inputs")
    manifest = {
        **run_identity,
        "status": "PREPARED" if args.prepare_only else "RUNNING",
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "provider": "openai",
        "conditions": list(conditions),
        "component_cells": COMPONENT_CELLS,
        "heldout_reports": 38,
        "adaptive_revision_on_heldout": False,
        "evaluation_role": "secondary replication on a previously inspected evaluation set",
        "workers": args.workers,
        "max_retries": args.max_retries,
        "schedule_sha256": sha256(args.output / "call_schedule.json"),
        "rendered_guidance_sha256": {
            str(path.relative_to(args.output)): sha256(path)
            for path in frozen_inputs.rglob("*.txt")
        },
        "pricing_snapshot": SOL_PRICING_SNAPSHOT,
        "environment": {
            "python": platform.python_version(),
            "platform": platform.platform(),
            "openai_package": package_version("openai"),
            "psutil_package": package_version("psutil"),
        },
    }
    dump(args.output / "manifest.json", manifest)
    if args.prepare_only:
        print(
            json.dumps(
                {
                    "status": "PREPARE_ONLY_OK",
                    "calls": {phase: len(tasks) for phase, tasks in schedule.items()},
                    "total_calls": sum(len(tasks) for tasks in schedule.values()),
                    "manifest": manifest,
                },
                ensure_ascii=False,
                indent=2,
            )
        )
        return

    base.load_env(args.env_file)
    held.PRICING_SNAPSHOT = SOL_PRICING_SNAPSHOT
    api = held.FrozenAPI("openai", MODEL, REASONING_EFFORT, args.max_retries, args.resume, args.output)
    process = psutil.Process()
    run_started = datetime.now(timezone.utc).isoformat()
    run_tick = time.perf_counter()
    cpu_tick = time.process_time()
    phase_timings = {}
    dump(
        args.output / "run_state.json",
        {"status": "RUNNING", "run_started_utc": run_started, "completed_phases": []},
    )

    def run_phase(name, function):
        started = datetime.now(timezone.utc).isoformat()
        tick = time.perf_counter()
        local_cpu = time.process_time()
        dump(
            args.output / "run_state.json",
            {
                "status": "RUNNING",
                "run_started_utc": run_started,
                "current_phase": name,
                "phase_started_utc": started,
                "completed_phases": list(phase_timings),
            },
        )
        try:
            value = function()
        except Exception as error:
            phase_timings[name] = {
                "status": "FAILED",
                "started_utc": started,
                "failed_utc": datetime.now(timezone.utc).isoformat(),
                "wall_seconds": time.perf_counter() - tick,
                "process_cpu_seconds": time.process_time() - local_cpu,
                "error_type": type(error).__name__,
            }
            dump(args.output / "phase_timings.json", phase_timings)
            dump(
                args.output / "run_state.json",
                {
                    "status": "FAILED",
                    "failed_phase": name,
                    "failed_utc": datetime.now(timezone.utc).isoformat(),
                    "completed_phases": [
                        phase for phase, timing in phase_timings.items() if timing.get("status") == "COMPLETED"
                    ],
                },
            )
            raise
        phase_timings[name] = {
            "status": "COMPLETED",
            "started_utc": started,
            "completed_utc": datetime.now(timezone.utc).isoformat(),
            "wall_seconds": time.perf_counter() - tick,
            "process_cpu_seconds": time.process_time() - local_cpu,
            "rss_bytes_at_completion": process.memory_info().rss,
        }
        dump(args.output / "phase_timings.json", phase_timings)
        return value

    entity_predictions = run_phase(
        "two_stage_entity",
        lambda: held.annotate_entities_all(api, conditions, gold, args.output, args.workers),
    )
    relation_predictions = run_phase(
        "two_stage_relation",
        lambda: held.annotate_relations_all(
            api, conditions, gold, entity_predictions, args.output, args.workers
        ),
    )
    component_predictions = run_phase(
        "relation_component_cells",
        lambda: annotate_component_cells(
            api, conditions, gold, entity_predictions, args.output, args.workers
        ),
    )

    provisional_scores = {}
    for condition in conditions:
        entity_score, entity_counts = held.score_docs(gold, entity_predictions[condition], "entity")
        relation_score, relation_counts = held.score_docs(gold, relation_predictions[condition], "relation")
        provisional_scores[condition] = {"entity": entity_score, "relation": relation_score}
        dump(args.output / condition / "scores_as_returned.json", provisional_scores[condition])
    for cell in COMPONENT_CELLS:
        relation_score, _ = held.score_docs(gold, component_predictions[cell], "relation")
        provisional_scores[cell] = {"relation": relation_score}
        dump(
            args.output / "relation_components" / cell / "scores_as_returned.json",
            provisional_scores[cell],
        )

    resources = {
        "run_started_utc": run_started,
        "run_completed_utc": datetime.now(timezone.utc).isoformat(),
        "total_wall_seconds": time.perf_counter() - run_tick,
        "total_process_cpu_seconds": time.process_time() - cpu_tick,
        "workers": args.workers,
        "max_retries": args.max_retries,
        "phase_timings": phase_timings,
        "ledger": held.ledger_summary(args.output / "call_ledger.jsonl"),
        "validation": held.validation_summary(args.output),
        "pricing_snapshot": SOL_PRICING_SNAPSHOT,
        "output_directory_bytes_before_resource_summary": held.directory_bytes(args.output),
    }
    dump(args.output / "resource_summary.json", resources)
    resources["output_directory_bytes_final"] = held.directory_bytes(args.output)
    dump(args.output / "resource_summary.json", resources)
    completed_utc = datetime.now(timezone.utc).isoformat()
    dump(
        args.output / "run_state.json",
        {
            "status": "COMPLETED_API_AND_RAW_SCORING",
            "run_started_utc": run_started,
            "completed_utc": completed_utc,
            "completed_phases": list(phase_timings),
            "postprocessing_required": True,
        },
    )
    manifest.update(
        {
            "status": "COMPLETED_API_AND_RAW_SCORING",
            "completed_utc": completed_utc,
            "returned_models": sorted(
                {str(event.get("returned_model")) for event in api.usage if event.get("returned_model")}
            ),
            "provisional_as_returned_scores": provisional_scores,
            "resource_summary": "resource_summary.json",
        }
    )
    dump(args.output / "manifest.json", manifest)
    print(json.dumps({"status": manifest["status"], "scores": provisional_scores}, indent=2))


if __name__ == "__main__":
    main()

"""Run one frozen entity-first/relation-second development condition.

Only condition-specific pilot records are retained. The relation phase receives
the frozen predicted entity inventory and cannot alter it. This is a
development-only runner; it has no held-out evaluation mode.
"""
from __future__ import annotations

import argparse, copy, hashlib, json, os, re, sys, threading, time
from collections import Counter, defaultdict
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone
from pathlib import Path
from openai import OpenAI

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))
import run_guideline_case_study_preliminary as base  # noqa
from deepseek_pricing import DEEPSEEK_V4_PRICING, deepseek_token_cost
from openai_pricing import OPENAI_PRICING, openai_token_cost

ENTITY_LABELS = sorted(base.ENTITY_LABELS)
RELATION_LABELS = sorted(base.RELATION_LABELS)


def cli():
    p=argparse.ArgumentParser()
    p.add_argument("--plan",type=Path,default=ROOT/"llm_preliminary/two_phase_experiment_plan.json")
    p.add_argument("--gold",type=Path,default=ROOT/"study_resources/emnlp_guideline_study/data/interim/iu_xray/human_gold_with_relations.jsonl")
    p.add_argument("--condition",default="C13_n12")
    p.add_argument("--provider",choices=["openai","deepseek"],required=True)
    p.add_argument("--model",required=True); p.add_argument("--reasoning-effort",default="high",choices=["low", "high", "max"])
    p.add_argument("--env-file",type=Path); p.add_argument("--output",type=Path,required=True)
    p.add_argument("--max-retries",type=int,default=5)
    p.add_argument("--relation-mode",choices=["original", "seed-only"],default="original",
                   help="Use seed-only when the causal relation refinement runner will consume R0.")
    return p.parse_args()


def dump(p,v):
    p.parent.mkdir(parents=True,exist_ok=True); p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")


def load_selected(path, ids):
    out=[]
    with path.open(encoding="utf-8") as f:
        for line in f:
            r=json.loads(line)
            if r.get("split")=="pilot" and str(r["doc_id"]) in ids: out.append(r)
    if {str(x["doc_id"]) for x in out} != set(ids): raise ValueError("Condition IDs do not match pilot records")
    return sorted(out,key=lambda x:ids.index(str(x["doc_id"])))


class API:
    def __init__(self,a):
        env="OPENAI_API_KEY" if a.provider=="openai" else "DEEPSEEK_API_KEY"
        key=os.environ.get(env)
        if not key: raise RuntimeError(f"Missing {env}")
        self.client=OpenAI(api_key=key,base_url=None if a.provider=="openai" else "https://api.deepseek.com")
        self.a=a; self.usage=[]; self.lock=threading.Lock()
        self.ledger_path=a.output/"call_ledger.jsonl"
        self.sequence=sum(1 for _ in self.ledger_path.open(encoding="utf-8")) if self.ledger_path.exists() else 0
    def record(self,event):
        with self.lock:
            self.sequence+=1; event={"ledger_sequence":self.sequence,**event}
            self.ledger_path.parent.mkdir(parents=True,exist_ok=True)
            with self.ledger_path.open("a",encoding="utf-8",newline="\n") as f:
                f.write(json.dumps(event,ensure_ascii=False,sort_keys=True)+"\n"); f.flush()
            self.usage.append(event)
    def json(self,system,payload,cache):
        if cache.exists():
            raw=json.loads(cache.read_text(encoding="utf-8")); return json.loads(raw["choices"][0]["message"]["content"])
        last=None
        for attempt in range(1,self.a.max_retries+1):
            started_utc=datetime.now(timezone.utc).isoformat(); tick=time.perf_counter(); raw=None
            try:
                kw=dict(model=self.a.model,messages=[{"role":"system","content":system},{"role":"user","content":json.dumps(payload,ensure_ascii=False)}],
                        response_format={"type":"json_object"},reasoning_effort=self.a.reasoning_effort)
                if self.a.provider=="deepseek": kw["extra_body"]={"thinking":{"type":"enabled"}}
                response=self.client.chat.completions.create(**kw); raw=response.model_dump()
                content=response.choices[0].message.content
                if not content: raise ValueError("empty JSON content")
                answer=json.loads(content); dump(cache,raw)
                u=raw.get("usage") or {}
                cost=(deepseek_token_cost(u,started_utc) if self.a.provider=="deepseek"
                      else openai_token_cost(self.a.model,u))
                self.record({"event":"completed","cache":str(cache),"attempt":attempt,"usage":u,"cost":cost,
                    "started_utc":started_utc,"completed_utc":datetime.now(timezone.utc).isoformat(),
                    "latency_seconds":time.perf_counter()-tick,"reasoning_effort":self.a.reasoning_effort,
                    "returned_model":raw.get("model"),"response_id":raw.get("id"),
                    "system_fingerprint":raw.get("system_fingerprint")})
                return answer
            except Exception as e:
                last=e
                u=(raw or {}).get("usage") or {}
                cost=(deepseek_token_cost(u,started_utc) if self.a.provider=="deepseek"
                      else openai_token_cost(self.a.model,u)) if u else None
                self.record({"event":"failed_attempt","cache":str(cache),"attempt":attempt,"usage":u,"cost":cost,
                    "started_utc":started_utc,"completed_utc":datetime.now(timezone.utc).isoformat(),
                    "latency_seconds":time.perf_counter()-tick,"reasoning_effort":self.a.reasoning_effort,
                    "provider_response_received":raw is not None,"error_type":type(e).__name__,
                    "error_message":str(e)[:1000],"returned_model":(raw or {}).get("model"),
                    "response_id":(raw or {}).get("id"),"system_fingerprint":(raw or {}).get("system_fingerprint")})
                if attempt<self.a.max_retries: time.sleep(min(2**attempt,12))
        raise RuntimeError(f"API failed for {cache}: {last}")


def render(g):
    return "\n".join(f"[{r['rule_id']}] {r['instruction']} Applies when: {r.get('applies_when','')}." for r in g["principles"] if r.get("status","active")=="active")


def validate_guideline(g,domain):
    if not isinstance(g.get("principles"),list): raise ValueError("guideline has no principle list")
    ids=[str(x.get("rule_id")) for x in g["principles"]]
    if len(ids)!=len(set(ids)) or any(x in {"None",""} for x in ids): raise ValueError("bad rule IDs")
    for x in g["principles"]: x["domain"]=domain; x.setdefault("status","active")
    g["deployment_guideline"]=render(g); return g


def initial_guideline(api,phase,gold,out):
    if phase=="entity":
        evidence=[{"doc_id":r["doc_id"],"text":r["text"],"entities":r["entities"]} for r in gold]
        schema={"entity_labels":ENTITY_LABELS,"offsets":"half-open character offsets"}
    else:
        evidence=[]
        for r in gold:
            es={e["id"]:e for e in r["entities"]}
            rels=[{"pred":q["pred"],"subject":es[q["subj"]],"object":es[q["obj"]]} for q in r["relations"]]
            evidence.append({"doc_id":r["doc_id"],"text":r["text"],"human_relations":rels,
                             "available_predicted_entities":r["frozen_entities"]})
        schema={"relation_labels":RELATION_LABELS,"endpoint_policy":"select only supplied predicted entity IDs"}
    payload={"task":f"Induce a self-contained operational {phase} annotation guideline from every supplied development example. Generalize; do not memorize document IDs or surface strings.",
             "schema":schema,"complete_development_evidence":evidence,
             "output_contract":{"principles":[{"rule_id":f"{'E' if phase=='entity' else 'R'}01","instruction":"operational rule","applies_when":"condition","exceptions":[],"priority":1,"examples":[]}],"deployment_guideline":"self-contained prose"}}
    dump(out/f"{phase}_initial_prompt.json",payload)
    ans=api.json("Return exactly one valid JSON object. Use all evidence and obey the output contract.",payload,out/f"{phase}_initial_raw.json")
    return validate_guideline(ans,phase)


def normalize_entities(doc,answer):
    out=[]; seen=set()
    for x in answer.get("entities",[]):
        try: s,e,l=int(x["start"]),int(x["end"]),str(x["label"])
        except Exception: continue
        if l not in ENTITY_LABELS or not 0<=s<e<=len(doc["text"]) or (s,e,l) in seen: continue
        seen.add((s,e,l)); out.append({"id":f"T{len(out)+1}","start":s,"end":e,"label":l,"text":doc["text"][s:e]})
    return out


def annotate_entities(api,g,gold,out):
    def one(r):
        payload={"guideline":g["deployment_guideline"],"rules":g["principles"],"report":{"doc_id":r["doc_id"],"text":r["text"]},
                 "offset_reference":base.indexed_text(r["text"]),"output_contract":{"entities":[{"id":"T1","start":0,"end":4,"label":"ANAT","text":"exact substring"}]}}
        ans=api.json("Annotate entities only. Return one JSON object. Do not output relations or explanations.",payload,out/"raw_annotations"/f"{r['doc_id']}.json")
        return {"doc_id":r["doc_id"],"split":"pilot","text":r["text"],"entities":normalize_entities(r,ans),"relations":[]}
    # Reports are independent annotation units. Parallel execution changes
    # latency only; output order is restored deterministically by map().
    with ThreadPoolExecutor(max_workers=len(gold)) as pool:
        preds=list(pool.map(one,gold))
    dump(out/"predictions.json",preds); return preds


def ekey(e): return e["start"],e["end"],e["label"]
def f1(tp,fp,fn): return 0 if 2*tp+fp+fn==0 else 2*tp/(2*tp+fp+fn)


def entity_score(gold,preds):
    by={p["doc_id"]:p for p in preds}; tp=fp=fn=0
    for g in gold:
        a=Counter(ekey(x) for x in g["entities"]); b=Counter(ekey(x) for x in by[g["doc_id"]]["entities"])
        tp+=sum((a&b).values()); fn+=sum((a-b).values()); fp+=sum((b-a).values())
    return {"tp":tp,"fp":fp,"fn":fn,"f1":f1(tp,fp,fn)}


def entity_census(gold,preds):
    by={p["doc_id"]:p for p in preds}; d=defaultdict(list)
    for g in gold:
        p=by[g["doc_id"]]; ga=list(g["entities"]); pa=list(p["entities"])
        exact=set(ekey(x) for x in ga)&set(ekey(x) for x in pa)
        gu=[x for x in ga if ekey(x) not in exact]; pu=[x for x in pa if ekey(x) not in exact]
        used=set()
        for x in gu:
            candidates=[(i,y) for i,y in enumerate(pu) if i not in used and x["start"]==y["start"] and x["end"]==y["end"]]
            if candidates:
                i,y=candidates[0]; used.add(i); d[f"ENT_LABEL|{x['label']}->{y['label']}"] .append({"doc_id":g["doc_id"],"gold":x,"prediction":y,"context":g["text"][max(0,x['start']-50):x['end']+50]})
            else:
                candidates=[(i,y) for i,y in enumerate(pu) if i not in used and x["label"]==y["label"] and max(x["start"],y["start"])<min(x["end"],y["end"])]
                if candidates:
                    i,y=candidates[0]; used.add(i); d[f"ENT_BOUNDARY|{x['label']}"] .append({"doc_id":g["doc_id"],"gold":x,"prediction":y,"context":g["text"][max(0,min(x['start'],y['start'])-50):max(x['end'],y['end'])+50]})
                else: d[f"ENT_FN|{x['label']}"] .append({"doc_id":g["doc_id"],"gold":x,"context":g["text"][max(0,x['start']-50):x['end']+50]})
        for i,y in enumerate(pu):
            if i not in used: d[f"ENT_FP|{y['label']}"] .append({"doc_id":g["doc_id"],"prediction":y,"context":g["text"][max(0,y['start']-50):y['end']+50]})
    return dict(d)


def annotate_relations(api,g,gold,out):
    def one(r):
        ents=copy.deepcopy(r["frozen_entities"]); valid={x["id"] for x in ents}; rels=[]; seen=set()
        payload={"guideline":g["deployment_guideline"],"rules":g["principles"],"report":{"doc_id":r["doc_id"],"text":r["text"]},"immutable_entities":ents,
                 "output_contract":{"relations":[{"subj":"T1","pred":"LocatedAt","obj":"T2"}]}}
        ans=api.json("Annotate relations only over immutable_entities. Never create or modify entities. Return one JSON object.",payload,out/"raw_annotations"/f"{r['doc_id']}.json")
        for q in ans.get("relations",[]):
            key=(str(q.get("subj")),str(q.get("pred")),str(q.get("obj")))
            if key[0] in valid and key[2] in valid and key[1] in RELATION_LABELS and key not in seen:
                seen.add(key); rels.append({"id":f"R{len(rels)+1}","subj":key[0],"pred":key[1],"obj":key[2]})
        return {"doc_id":r["doc_id"],"split":"pilot","text":r["text"],"entities":ents,"relations":rels}
    with ThreadPoolExecutor(max_workers=len(gold)) as pool:
        preds=list(pool.map(one,gold))
    dump(out/"predictions.json",preds); return preds


def rkey(record,q):
    es={x["id"]:x for x in record["entities"]}; return ekey(es[q["subj"]])+(q["pred"],)+ekey(es[q["obj"]])


def relation_score(gold,preds):
    by={p["doc_id"]:p for p in preds}; tp=fp=fn=0
    for g in gold:
        a=Counter(rkey(g,x) for x in g["relations"]); p=by[g["doc_id"]]; b=Counter(rkey(p,x) for x in p["relations"])
        tp+=sum((a&b).values()); fn+=sum((a-b).values()); fp+=sum((b-a).values())
    return {"tp":tp,"fp":fp,"fn":fn,"f1":f1(tp,fp,fn)}


def relation_census(gold,preds):
    by={p["doc_id"]:p for p in preds}; d=defaultdict(list)
    for g in gold:
        p=by[g["doc_id"]]; available={ekey(x) for x in p["entities"]}
        a=Counter(rkey(g,x) for x in g["relations"]); b=Counter(rkey(p,x) for x in p["relations"])
        for key,n in (a-b).items():
            cause="UNAVAILABLE|missing_entity_endpoint" if key[:3] not in available or key[4:] not in available else f"REL_FN|{key[3]}"
            for _ in range(n): d[cause].append({"doc_id":g["doc_id"],"gold_relation":key,"context":g["text"]})
        for key,n in (b-a).items():
            for _ in range(n): d[f"REL_FP|{key[3]}"] .append({"doc_id":g["doc_id"],"predicted_relation":key,"context":g["text"]})
    return dict(d)


def apply_candidate(g,c,iteration,cases,phase):
    out=copy.deepcopy(g); action=str(c.get("action","")).upper(); rule=copy.deepcopy(c.get("principle",{}))
    if action not in {"ADD","REVISE"} or not rule.get("instruction"): raise ValueError("invalid atomic candidate")
    rule.update({"domain":phase,"status":"active","supporting_doc_ids":sorted({str(x["doc_id"]) for x in cases})})
    if action=="ADD": rule["rule_id"]=f"{'EA' if phase=='entity' else 'RA'}{iteration:03d}"; out["principles"].append(rule)
    else:
        target=str(c.get("target_rule_id")); ix=[i for i,x in enumerate(out["principles"]) if str(x.get("rule_id"))==target]
        if len(ix)!=1: raise ValueError("REVISE target missing")
        rule["rule_id"]=target; out["principles"][ix[0]]=rule
    out["deployment_guideline"]=render(out); return out


def atomic_phase(api,phase,gold,g0,out):
    current=g0; pred=(annotate_entities if phase=="entity" else annotate_relations)(api,current,gold,out/"G0")
    score=(entity_score if phase=="entity" else relation_score)(gold,pred); rejected=defaultdict(set); history=[]; i=1
    dump(out/"G0"/"guideline.json",current); dump(out/"G0"/"score.json",score)
    while True:
        census=(entity_census if phase=="entity" else relation_census)(gold,pred)
        eligible={k:v for k,v in census.items() if not k.startswith("UNAVAILABLE|")}
        sig=hashlib.sha256(json.dumps({"g":current["principles"],"c":eligible},sort_keys=True,default=str).encode()).hexdigest()
        ranked=[k for k,v in sorted(eligible.items(),key=lambda z:(-len(z[1]),-len({str(x['doc_id']) for x in z[1]}),z[0])) if k not in rejected[sig]]
        if not ranked: break
        stratum=ranked[0]; cases=eligible[stratum]
        payload={"task":f"Propose exactly one generalizable atomic ADD or REVISE for the selected {phase} discrepancy stratum.","selected_stratum":stratum,
                 "complete_discrepancy_evidence":cases,"current_principles":current["principles"],"prior_decisions":history,
                 "output_contract":{"action":"ADD or REVISE","target_rule_id":"existing ID for REVISE; null for ADD","principle":{"instruction":"one operational rule","applies_when":"condition","exceptions":[],"priority":1,"examples":[]},"rationale":"text"}}
        cdir=out/f"candidate_{i:03d}"; dump(cdir/"prompt.json",payload)
        try:
            c=api.json("Return one valid JSON object. Change one rule only; do not patch a document-specific answer.",payload,cdir/"raw.json")
            proposed=apply_candidate(current,c,i,cases,phase); dump(cdir/"guideline.json",proposed)
            newpred=(annotate_entities if phase=="entity" else annotate_relations)(api,proposed,gold,cdir)
            newscore=(entity_score if phase=="entity" else relation_score)(gold,newpred)
            oldn=sum(len(x) for x in eligible.values()); newc=(entity_census if phase=="entity" else relation_census)(gold,newpred)
            newn=sum(len(v) for k,v in newc.items() if not k.startswith("UNAVAILABLE|"))
            accept=newscore["f1"]>score["f1"]+1e-12 or (abs(newscore["f1"]-score["f1"])<=1e-12 and newn<oldn)
            reason="f1_improved" if newscore["f1"]>score["f1"]+1e-12 else ("f1_tied_net_errors_improved" if accept else "admission_failed")
        except Exception as e:
            accept=False; reason=f"invalid_candidate:{e}"; newscore=score
        decision={"iteration":i,"stratum":stratum,"cases":len(cases),"accepted":accept,"reason":reason,"before":score,"after":newscore}
        dump(cdir/"decision.json",decision); history.append(decision)
        if accept: current,pred,score=proposed,newpred,newscore
        else: rejected[sig].add(stratum)
        dump(out/"state.json",{"history":history,"current_score":score}); i+=1
    dump(out/"G_star"/"guideline.json",current); dump(out/"G_star"/"predictions.json",pred); dump(out/"G_star"/"score.json",score)
    return current,pred,score,history


def main():
    a=cli(); base.load_env(a.env_file); plan=json.loads(a.plan.read_text(encoding="utf-8"))
    cond=next((x for x in plan["conditions"] if x["condition_id"]==a.condition),None)
    if not cond: raise ValueError("Unknown condition")
    gold=load_selected(a.gold,cond["doc_ids"]); a.output.mkdir(parents=True,exist_ok=True); api=API(a)
    manifest={"protocol":"two-phase-preliminary-v1","provider":a.provider,"requested_model":a.model,"reasoning_effort":a.reasoning_effort,
              "thinking_enabled":a.provider=="deepseek","temperature_sent":False,"condition":cond,"heldout_retained_or_evaluated":False,
              "relation_mode":a.relation_mode,
              "pricing_snapshot":DEEPSEEK_V4_PRICING if a.provider=="deepseek" else OPENAI_PRICING,
              "created_utc":datetime.now(timezone.utc).isoformat()}; dump(a.output/"manifest.json",manifest)
    e0=initial_guideline(api,"entity",gold,a.output/"entity"); eg,ep,es,eh=atomic_phase(api,"entity",gold,e0,a.output/"entity")
    relgold=[]
    by={p["doc_id"]:p for p in ep}
    for g in gold:
        x=copy.deepcopy(g); x["frozen_entities"]=copy.deepcopy(by[g["doc_id"]]["entities"]); relgold.append(x)
    r0=initial_guideline(api,"relation",relgold,a.output/"relation")
    if a.relation_mode=="seed-only":
        rp=annotate_relations(api,r0,relgold,a.output/"relation/G0")
        rs=relation_score(relgold,rp); rg=r0; rh=[]
        dump(a.output/"relation/G0/guideline.json",r0); dump(a.output/"relation/G0/score.json",rs)
        dump(a.output/"relation/G_star/guideline.json",r0); dump(a.output/"relation/G_star/predictions.json",rp)
        dump(a.output/"relation/G_star/score.json",rs)
    else:
        rg,rp,rs,rh=atomic_phase(api,"relation",relgold,r0,a.output/"relation")
    manifest.update({"completed_utc":datetime.now(timezone.utc).isoformat(),"entity_score":es,"relation_score":rs,
                     "entity_candidates":len(eh),"relation_candidates":len(rh),"usage":api.usage,
                     "returned_models":sorted({str(x.get('returned_model')) for x in api.usage if x.get('returned_model')}),
                     "system_fingerprints":sorted({str(x.get('system_fingerprint')) for x in api.usage if x.get('system_fingerprint')})})
    dump(a.output/"manifest.json",manifest)
    print(json.dumps({"output":str(a.output),"entity":es,"relation":rs,"entity_candidates":len(eh),"relation_candidates":len(rh)},indent=2))

if __name__=="__main__": main()

"""Combine model resource summaries and optionally reconcile provider billing."""
from __future__ import annotations

import argparse, json
from collections import Counter
from datetime import datetime
from pathlib import Path


def cli():
    p=argparse.ArgumentParser()
    p.add_argument("--deepseek-run",type=Path,required=True)
    p.add_argument("--gpt-run",type=Path,required=True)
    p.add_argument("--deepseek-billed-usd",type=float)
    p.add_argument("--gpt-billed-usd",type=float)
    p.add_argument("--usd-krw",type=float)
    p.add_argument("--output",type=Path,required=True)
    return p.parse_args()


def load(root):
    return json.loads((root/"resource_summary.json").read_text(encoding="utf-8"))


def main():
    a=cli(); models={"deepseek":load(a.deepseek_run),"gpt":load(a.gpt_run)}; tokens=Counter()
    for x in models.values(): tokens.update(x["ledger"]["tokens"])
    computed={k:float(v["ledger"]["computed_token_cost_usd"]) for k,v in models.items()}
    starts=[datetime.fromisoformat(x["run_started_utc"]) for x in models.values()]
    ends=[datetime.fromisoformat(x["run_completed_utc"]) for x in models.values()]
    report={"models":models,"combined":{"tokens":dict(tokens),"computed_token_cost_usd":sum(computed.values()),
        "sum_model_wall_seconds":sum(float(x["total_wall_seconds"]) for x in models.values()),
        "elapsed_from_first_start_to_last_completion_seconds":(max(ends)-min(starts)).total_seconds()}}
    billed={"deepseek":a.deepseek_billed_usd,"gpt":a.gpt_billed_usd}
    if any(v is not None for v in billed.values()):
        report["billing_reconciliation"]={}
        for k,actual in billed.items():
            if actual is not None:
                report["billing_reconciliation"][k]={"provider_billed_usd":actual,"computed_usd":computed[k],
                    "absolute_difference_usd":actual-computed[k],
                    "relative_difference":(actual-computed[k])/computed[k] if computed[k] else None}
        report["billing_reconciliation"]["provider_billed_total_usd"]=sum(v for v in billed.values() if v is not None)
    if a.usd_krw:
        report["combined"]["exchange_rate_usd_krw"]=a.usd_krw
        report["combined"]["computed_token_cost_krw"]=report["combined"]["computed_token_cost_usd"]*a.usd_krw
    a.output.parent.mkdir(parents=True,exist_ok=True)
    a.output.write_text(json.dumps(report,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    print(json.dumps(report["combined"],ensure_ascii=False,indent=2))


if __name__ == "__main__": main()
